pub fn mutationRowClaimAlloc(
    alloc: std.mem.Allocator,
    maybe_claim: ?db_mod.types.RowClaimRequest,
    skip_locked_default: bool,
) !db_mod.types.RowClaimRequest {
    var claim = maybe_claim orelse db_mod.types.RowClaimRequest{
        .skip_locked = skip_locked_default,
        .wait_policy = if (skip_locked_default) .skip_locked else .wait,
    };
    claim.owner_id = if (claim.owner_id.len > 0) try alloc.dupe(u8, claim.owner_id) else "";
    return claim;
}

pub fn parseInsertSourceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    cte_hooks: plan_mod.CteSelectParserHooks,
    hooks: InsertSourceParserHooks,
) !plan_mod.LoweredInsertSource {
    if (!parser.peekKeywordTag(tokens, pos.*, .with)) return try parseInsertSourceWithCtesAlloc(alloc, tokens, pos, hooks, .{
        .ctes = &.{},
        .base_table_name = null,
    });

    var base_table_name: ?[]const u8 = null;
    defer if (base_table_name) |table| alloc.free(table);
    var ctes = try plan_mod.parseCtesForPlanAlloc(alloc, tokens, pos, &base_table_name, cte_hooks);
    errdefer plan_mod.freePlanCtes(alloc, ctes);

    var lowered = try parseInsertSourceWithCtesAlloc(alloc, tokens, pos, hooks, .{
        .ctes = ctes,
        .base_table_name = &base_table_name,
    });
    errdefer lowered.deinit(alloc);
    lowered.ctes = ctes;
    ctes = &.{};
    return lowered;
}

pub fn parseInsertSourceWithCtesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    hooks: InsertSourceParserHooks,
    options: InsertSourceParserOptions,
) !plan_mod.LoweredInsertSource {
    try parser.expectKeywordTag(tokens, pos, .insert);
    try parser.expectKeywordTag(tokens, pos, .into);

    const target_table = if (try generatedInsertSourceTargetAliasAlloc(alloc, tokens, pos, hooks.generated_dml_ast)) |generated_target|
        generated_target
    else
        try plan_mod.parseDmlTargetAliasAlloc(alloc, tokens, pos);
    errdefer plan_mod.freeTableAlias(alloc, target_table);

    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (columns.items) |column| alloc.free(column);
        columns.deinit(alloc);
    }
    try parser.expectToken(tokens, pos, .lparen);
    if (hooks.generated_dml_ast != null and hooks.generated_insert_column_items == null) return error.UnsupportedSqlShape;
    if (hooks.generated_insert_column_items) |generated_columns| {
        try validateGeneratedInsertSourceColumnHookRange(tokens, pos.*, hooks.generated_dml_ast, generated_columns);
        try parseGeneratedInsertSourceColumnsAlloc(alloc, tokens, pos, generated_columns, hooks.schema, &columns);
    } else {
        while (true) {
            const column = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
            var column_transferred = false;
            errdefer if (!column_transferred) alloc.free(column);
            if (parser.peekKind(tokens, pos.*, .lparen)) return error.UnsupportedSqlShape;
            if (binder.relationalColumnForField(hooks.schema, column, null) == null) return error.InvalidSqlCatalog;
            try columns.append(alloc, column);
            column_transferred = true;
            if (parser.matchToken(tokens, pos, .comma) == null) break;
        }
    }
    try parser.expectToken(tokens, pos, .rparen);
    try validateSqlInsertColumnsUnique(hooks.schema, columns.items);
    if (!parser.peekKeywordTag(tokens, pos.*, .select)) return error.UnsupportedSqlShape;

    const base_source_schema = hooks.joined_source_schema orelse hooks.schema;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (options.ctes.len != 0) planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, base_source_schema, options.ctes);

    var source = try parseInsertSourceSelectAlloc(alloc, tokens, pos, base_source_schema, planned_ctes, hooks);
    errdefer source.deinit(alloc);
    if (options.ctes.len != 0) {
        try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &source, options.ctes, options.base_table_name orelse return error.UnsupportedSqlShape);
    }
    const resolved_source_table = if (options.ctes.len != 0)
        (options.base_table_name orelse return error.UnsupportedSqlShape).* orelse return error.UnsupportedSqlShape
    else
        source.table_name;
    if (!hooks.insert_source_allows_different_table and !std.mem.eql(u8, resolved_source_table, target_table.name)) return error.UnsupportedSqlShape;
    if (source.query.row_claim != null) return error.UnsupportedSqlShape;
    if (source.query.select_all or source.select_outputs.len != columns.items.len) return error.UnsupportedSqlShape;

    const effective_source_schema = relational_rows.rowsPlannedQuerySourceSchema(base_source_schema, planned_ctes, source.query) orelse return error.UnsupportedSqlShape;

    const type_context: expr_type.RowExpressionTypeContext = .{
        .alloc = alloc,
        .schema = hooks.schema,
        .joined_source_schema = effective_source_schema,
        .defer_row_expression_field_validation = hooks.defer_row_expression_field_validation,
    };
    const assignments = try insertSourceAssignmentsFromSelectAlloc(alloc, hooks.schema, effective_source_schema, type_context, columns.items, source.query, source.select_outputs);
    var assignments_transferred = false;
    errdefer if (!assignments_transferred) freeExpressionAssignments(alloc, assignments);

    clearInsertSourceQueryProjection(alloc, &source.query);

    var conflict: ?db_mod.types.RelationalRowsOnConflict = null;
    errdefer if (conflict) |value| freeRowsOnConflictValue(alloc, value);
    var conflict_where = false;
    if (parser.matchKeywordTag(tokens, pos, .on)) {
        const conflict_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        const parsed_conflict = try parseConflictClauseWithContextAlloc(alloc, tokens, pos, .{
            .params = hooks.params,
            .schema = hooks.schema,
            .joined_source_schema = effective_source_schema,
            .table_name = target_table.name,
            .existing_qualifiers = &conflict_qualifiers,
            .insert_columns = columns.items,
            .insert_values = &.{},
            .defer_row_expression_field_validation = hooks.defer_row_expression_field_validation,
            .context_hooks = hooks.conflict_context_hooks,
            .target_options = hooks.conflict_target_options,
            .assignment_hooks = hooks.conflict_assignment_hooks,
            .generated_assignment_items = hooks.generated_conflict_assignment_items,
            .generated_assignments_tokens = hooks.generated_conflict_assignments_tokens,
            .generated_action_tokens = hooks.generated_conflict_action_tokens,
            .generated_action_kind = hooks.generated_conflict_action_kind,
            .condition_options = hooks.conflict_condition_options,
            .dispatch_options = hooks.conflict_dispatch_options,
        });
        defer freeConflictClause(alloc, parsed_conflict);
        if (parsed_conflict.where_expression != null or parsed_conflict.where_expressions.len != 0 or parsed_conflict.where_any.len != 0 or parsed_conflict.where_not.len != 0) conflict_where = true;
        conflict = try insertSourceOnConflictFromClauseAlloc(alloc, hooks.schema, parsed_conflict);
    }

    var returning: ReturningProjection = .{};
    errdefer returning.deinit(alloc);
    if (parser.matchKeywordTag(tokens, pos, .returning)) {
        const returning_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        const generated_returning_range = try validateGeneratedDmlReturningHookRange(
            tokens,
            pos.*,
            hooks.generated_dml_ast,
            hooks.returning_hooks.generated_returning_items,
        );
        returning = try expr_projection.parseReturningProjectionAlloc(alloc, tokens, pos, hooks.schema, &returning_qualifiers, hooks.returning_hooks);
        if (generated_returning_range) |range| {
            if (pos.* != range.end) return error.UnsupportedSqlShape;
        }
    }

    if (parser.matchToken(tokens, pos, .semicolon) != null and !parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;

    const table_name = target_table.name;
    const source_table = try alloc.dupe(u8, resolved_source_table);
    var source_table_transferred = false;
    errdefer if (!source_table_transferred) alloc.free(source_table);

    const returning_expression_count = returning.expressions.len;
    const returning_all = returning.returnsAll();
    if (returning_all) {
        strings.freeStringSlice(alloc, returning.fields);
        returning.fields = &.{};
    }
    const req: db_mod.types.RelationalRowsInsertSourceRequest = .{
        .source_table = source_table,
        .source = source.query,
        .assignments = assignments,
        .on_conflict = conflict,
        .returning = returning.fields,
        .returning_expressions = returning.expressions,
        .returning_all = returning_all,
    };
    db_mod.DB.validateRelationalRowsInsertSourceRequestWithSchemas(hooks.schema, effective_source_schema, req) catch return error.UnsupportedSqlShape;

    for (columns.items) |column| alloc.free(column);
    columns.deinit(alloc);
    alloc.free(source.table_name);
    source.query = .{};
    source.clearSelectOutputs(alloc);
    assignments_transferred = true;
    conflict = null;
    returning = .{};
    alloc.free(target_table.alias);
    source_table_transferred = true;

    return .{
        .table_name = table_name,
        .insert_source = .{ .req = req },
        .returning_expression_count = returning_expression_count,
        .returning_all = returning_all,
        .conflict_where = conflict_where,
    };
}

fn validateGeneratedInsertSourceColumnHookRange(
    tokens: []const Token,
    pos: usize,
    generated_dml_ast: ?*const generated_parser.GeneratedSqlDmlAst,
    generated_column_items: *const generated_parser.GeneratedSqlListAst,
) !void {
    const ast = generated_dml_ast orelse return error.UnsupportedSqlShape;
    if (ast.kind != .insert_select) return error.UnsupportedSqlShape;
    const columns = ast.insert_columns_tokens orelse return error.UnsupportedSqlShape;
    if (columns.start >= columns.end or columns.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[columns.start].kind != .lparen or tokens[columns.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    if (pos != columns.start + 1) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, .{ .start = columns.start + 1, .end = columns.end - 1 }, generated_column_items);
}

fn parseGeneratedInsertSourceColumnsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    items: *const generated_parser.GeneratedSqlListAst,
    schema: runtime_schema.TableSchema,
    columns: *std.ArrayListUnmanaged([]const u8),
) !void {
    const first_tokens = items.first_tokens orelse return error.UnsupportedSqlShape;
    const last_tokens = items.last_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, .{ .start = first_tokens.start, .end = last_tokens.end }, items);
    if (items.count == 0 or items.items.len != items.count) return error.UnsupportedSqlShape;
    if (pos.* != items.items[0].start) return error.UnsupportedSqlShape;
    for (items.items) |item| {
        if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
        pos.* = item.start;
        const column = try grammar.parseIdentifierOwnedAlloc(alloc, tokens[0..item.end], pos);
        var column_transferred = false;
        errdefer if (!column_transferred) alloc.free(column);
        if (pos.* != item.end) return error.UnsupportedSqlShape;
        if (parser.peekKind(tokens, pos.*, .lparen)) return error.UnsupportedSqlShape;
        if (binder.relationalColumnForField(schema, column, null) == null) return error.InvalidSqlCatalog;
        try columns.append(alloc, @constCast(column));
        column_transferred = true;
    }
}

fn parseInsertSourceSelectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    base_source_schema: runtime_schema.TableSchema,
    planned_ctes: []const relational_rows.RowsPlannedCte,
    hooks: InsertSourceParserHooks,
) !plan_mod.LoweredSelect {
    const start = pos.*;
    var end = tokens.len;
    var depth: usize = 0;
    var i = start;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) break;
                depth -= 1;
            },
            .semicolon => if (depth == 0) {
                end = i;
                break;
            },
            .identifier => if (depth == 0) {
                if (token.matchesKeywordTag(.returning)) {
                    end = i;
                    break;
                }
                if (token.matchesKeywordTag(.on) and i + 1 < tokens.len and tokens[i + 1].matchesKeywordTag(.conflict)) {
                    end = i;
                    break;
                }
            },
            else => {},
        }
    }
    if (end == start) return error.UnsupportedSqlShape;

    const parse_schema = if (try insertSourceSelectSourceCteSchema(tokens, start, end, planned_ctes)) |schema|
        schema
    else
        base_source_schema;
    var lowered = try hooks.parse_select(hooks.ptr, tokens[start..end], parse_schema);
    errdefer lowered.deinit(alloc);
    pos.* = end;
    return lowered;
}

pub fn parseMergeMutationPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    cte_hooks: plan_mod.CteSelectParserHooks,
    parser_options: MergeMutationParserOptions,
) !plan_mod.LoweredMergeMutationPlan {
    if (!parser.peekKeywordTag(tokens, pos.*, .with)) return try parseMergeMutationBodyAlloc(alloc, tokens, pos, parser_options, .{
        .ctes = &.{},
        .base_table_name = null,
    });

    var base_table_name: ?[]const u8 = null;
    defer if (base_table_name) |table| alloc.free(table);
    var parsed_ctes = try parseMergeCtesForPlanAlloc(alloc, tokens, pos, &base_table_name, cte_hooks, parser_options, null);
    errdefer parsed_ctes.deinit(alloc);

    var final = try parseMergeMutationBodyAlloc(alloc, tokens, pos, parser_options, .{
        .ctes = parsed_ctes.read_ctes,
        .data_modifying_ctes = parsed_ctes.data_modifying_ctes,
        .base_table_name = &base_table_name,
    });
    errdefer final.deinit(alloc);
    if (parser.matchToken(tokens, pos, .semicolon) != null and !parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    _ = base_table_name orelse return error.UnsupportedSqlShape;
    final.ctes = parsed_ctes.read_ctes;
    final.data_modifying_ctes = parsed_ctes.data_modifying_ctes;
    parsed_ctes.read_ctes = &.{};
    parsed_ctes.data_modifying_ctes = &.{};
    return final;
}

const ParsedMergeCtes = struct {
    read_ctes: []const db_mod.types.RelationalRowsCte = &.{},
    data_modifying_ctes: []const plan_mod.LoweredDataModifyingCte = &.{},

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        plan_mod.freePlanCtes(alloc, self.read_ctes);
        for (self.data_modifying_ctes) |cte| {
            var owned = cte;
            owned.deinit(alloc);
        }
        if (self.data_modifying_ctes.len > 0) alloc.free(self.data_modifying_ctes);
        self.* = undefined;
    }
};

fn parseMergeCtesForPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    base_table_name: *?[]const u8,
    hooks: plan_mod.CteSelectParserHooks,
    parser_options: MergeMutationParserOptions,
    generated_cte_prefix: ?generated_parser.GeneratedSqlDmlCteAst,
) !ParsedMergeCtes {
    const cursor = parser.Cursor.init(tokens, pos);
    const with_index = pos.*;
    try cursor.expectKeywordTag(.with);
    const list_start = pos.*;
    var read_ctes = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCte).empty;
    errdefer {
        for (read_ctes.items) |cte| {
            var owned = cte;
            owned.deinit(alloc);
        }
        read_ctes.deinit(alloc);
    }
    var data_ctes = std.ArrayListUnmanaged(plan_mod.LoweredDataModifyingCte).empty;
    errdefer {
        for (data_ctes.items) |cte| {
            var owned = cte;
            owned.deinit(alloc);
        }
        data_ctes.deinit(alloc);
    }

    const generated_prefix = generated_cte_prefix;
    var generated_cte_index: usize = 0;
    if (generated_prefix) |cte_prefix| {
        if (cte_prefix.recursive) return error.UnsupportedSqlShape;
        if (cte_prefix.count == 0 or cte_prefix.count != cte_prefix.items.len) return error.UnsupportedSqlShape;
        try validateGeneratedDmlNonRecursiveCtePrefixLayout(tokens, cte_prefix, with_index, list_start);
        try validateGeneratedDmlCtePrefixBoundaryMirrors(tokens, cte_prefix);
    }

    while (true) {
        const generated_cte: ?*const generated_parser.GeneratedSqlDmlCteItemAst = if (generated_prefix) |cte_prefix| blk: {
            if (generated_cte_index >= cte_prefix.items.len) return error.UnsupportedSqlShape;
            break :blk &cte_prefix.items[generated_cte_index];
        } else null;

        const cte_name = if (generated_cte) |cte|
            try generatedDmlCteNameAlloc(alloc, tokens, cte, pos)
        else
            try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        var cte_name_transferred = false;
        errdefer if (!cte_name_transferred) alloc.free(cte_name);
        if (plan_mod.findCteByName(read_ctes.items, cte_name) != null or findDataModifyingCteByName(data_ctes.items, cte_name) != null) return error.UnsupportedSqlShape;
        const cte_column_aliases = if (generated_cte) |cte|
            try generatedDmlCteColumnAliasesAlloc(alloc, tokens, cte, pos)
        else
            try grammar.parseOptionalCteColumnAliasesAlloc(alloc, tokens, pos);
        defer strings.freeStringSlice(alloc, cte_column_aliases);
        try cursor.expectKeywordTag(.as);
        if (generated_cte) |cte| {
            try consumeGeneratedDmlCteMaterialization(tokens, cte, pos);
        } else {
            try parser.consumeCteMaterializationHint(tokens, pos);
        }
        try cursor.expectToken(.lparen);
        const close_index = (parser.findMatchingRParenAfterOpenIndex(tokens, pos.*) orelse return error.UnsupportedSqlShape);
        if (generated_cte) |cte| {
            if (cte.body_tokens.start != pos.* or cte.body_tokens.end != close_index) return error.UnsupportedSqlShape;
        }
        if (parser.peekKeywordTag(tokens, pos.*, .update) or parser.peekKeywordTag(tokens, pos.*, .delete)) {
            if (cte_column_aliases.len != 0) return error.UnsupportedSqlShape;
            var inner_pos: usize = 0;
            var lowered = if (generated_cte) |cte| blk: {
                const generated_body_dml = cte.body_dml orelse return error.UnsupportedSqlShape;
                break :blk try parseDataModifyingCteMutationSourceWithGeneratedDmlAstAlloc(alloc, tokens[pos.*..close_index], &inner_pos, parser_options, generated_body_dml);
            } else try parseDataModifyingCteMutationSourceAlloc(alloc, tokens[pos.*..close_index], &inner_pos, parser_options);
            var lowered_transferred = false;
            errdefer if (!lowered_transferred) lowered.deinit(alloc);
            if (!parser.atEnd(tokens[pos.*..close_index], inner_pos)) return error.UnsupportedSqlShape;
            try resolveDataModifyingCteBaseSourceTableAlloc(alloc, lowered.table_name, base_table_name);
            try data_ctes.append(alloc, .{
                .name = cte_name,
                .table_name = lowered.table_name,
                .mutation = lowered.mutation,
                .claim_placeholder = true,
            });
            lowered_transferred = true;
            cte_name_transferred = true;
            pos.* = close_index + 1;
            if (generated_cte != null) generated_cte_index += 1;
            if (cursor.matchToken(.comma) == null) break;
            continue;
        }
        if (generated_cte) |cte| {
            const generated_body_read = cte.body_read orelse return error.UnsupportedSqlShape;
            if (try lowerGeneratedDmlGraphTableFunctionCteAlloc(alloc, tokens, &generated_body_read)) |table_function| {
                pos.* = close_index + 1;
                try plan_mod.resolveTableFunctionBaseSourceTableAlloc(alloc, table_function, base_table_name);
                try read_ctes.append(alloc, .{
                    .name = cte_name,
                    .table_function = table_function,
                });
                cte_name_transferred = true;
                generated_cte_index += 1;
                if (cursor.matchToken(.comma) == null) break;
                continue;
            }
        }
        var lowered = try hooks.parse_select(hooks.ptr, tokens[pos.*..close_index], read_ctes.items, null);
        errdefer lowered.deinit(alloc);
        pos.* = close_index + 1;
        try plan_mod.applyCteColumnAliasesAlloc(alloc, &lowered, cte_column_aliases);
        try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &lowered, read_ctes.items, base_table_name);
        try read_ctes.append(alloc, .{
            .name = cte_name,
            .query = lowered.query,
        });
        lowered.query = .{};
        lowered.clearSelectOutputs(alloc);
        alloc.free(lowered.table_name);
        lowered.table_name = "";
        cte_name_transferred = true;
        if (generated_cte != null) generated_cte_index += 1;
        if (cursor.matchToken(.comma) == null) break;
    }
    if (generated_prefix) |cte_prefix| {
        if (generated_cte_index != cte_prefix.items.len) return error.UnsupportedSqlShape;
    }

    return .{
        .read_ctes = try read_ctes.toOwnedSlice(alloc),
        .data_modifying_ctes = try data_ctes.toOwnedSlice(alloc),
    };
}

fn generatedDmlTokenRangeEqual(
    a: generated_parser.GeneratedSqlTokenRange,
    b: generated_parser.GeneratedSqlTokenRange,
) bool {
    return a.start == b.start and a.end == b.end;
}

fn validateGeneratedDmlCtePrefixBoundaryMirrors(
    tokens: []const Token,
    cte_prefix: generated_parser.GeneratedSqlDmlCteAst,
) !void {
    if (cte_prefix.count == 0 or cte_prefix.items.len == 0 or cte_prefix.count != cte_prefix.items.len) return error.UnsupportedSqlShape;
    const first = cte_prefix.items[0];
    if (!generatedDmlTokenRangeEqual(cte_prefix.first_name_tokens, first.name_tokens) or
        !generatedDmlTokenRangeEqual(cte_prefix.first_body_tokens, first.body_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlCteBodyBoundaryMirror(tokens, first, cte_prefix.first_body_read, cte_prefix.first_body_dml);

    const last = cte_prefix.items[cte_prefix.items.len - 1];
    if (!generatedDmlTokenRangeEqual(cte_prefix.last_name_tokens, last.name_tokens) or
        !generatedDmlTokenRangeEqual(cte_prefix.last_body_tokens, last.body_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlCteBodyBoundaryMirror(tokens, last, cte_prefix.last_body_read, cte_prefix.last_body_dml);
}

fn validateGeneratedDmlNonRecursiveCtePrefixLayout(
    tokens: []const Token,
    cte_prefix: generated_parser.GeneratedSqlDmlCteAst,
    with_index: usize,
    list_start: usize,
) !void {
    if (cte_prefix.recursive) return error.UnsupportedSqlShape;
    if (with_index >= tokens.len or !tokens[with_index].matchesKeywordTag(.with)) return error.UnsupportedSqlShape;
    if (list_start != with_index + 1 or list_start >= tokens.len) return error.UnsupportedSqlShape;
    if (cte_prefix.tokens.start != list_start or cte_prefix.tokens.end > tokens.len or cte_prefix.tokens.start >= cte_prefix.tokens.end) return error.UnsupportedSqlShape;
    if (cte_prefix.list_tokens.start != cte_prefix.tokens.start or cte_prefix.list_tokens.end != cte_prefix.tokens.end) return error.UnsupportedSqlShape;
    if (cte_prefix.count == 0 or cte_prefix.items.len != cte_prefix.count) return error.UnsupportedSqlShape;
    const first = cte_prefix.items[0];
    if (first.name_tokens.start != cte_prefix.list_tokens.start) return error.UnsupportedSqlShape;
    const last = cte_prefix.items[cte_prefix.items.len - 1];
    if (last.body_tokens.end >= tokens.len or last.body_tokens.end + 1 != cte_prefix.list_tokens.end) return error.UnsupportedSqlShape;
    if (last.body_tokens.start == 0 or tokens[last.body_tokens.start - 1].kind != .lparen or tokens[last.body_tokens.end].kind != .rparen) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlCteBodyBoundaryMirror(
    tokens: []const Token,
    item: generated_parser.GeneratedSqlDmlCteItemAst,
    mirror_read: ?generated_parser.GeneratedSqlDmlReadBodyAst,
    mirror_dml: ?*const generated_parser.GeneratedSqlDmlAst,
) !void {
    if (item.body_read) |body_read| {
        if (mirror_dml != null) return error.UnsupportedSqlShape;
        const prefix_read = mirror_read orelse return error.UnsupportedSqlShape;
        try validateGeneratedDmlReadBodyBoundaryMirror(tokens, body_read, prefix_read);
        return;
    }
    if (item.body_dml) |body_dml| {
        if (mirror_read != null) return error.UnsupportedSqlShape;
        const prefix_dml = mirror_dml orelse return error.UnsupportedSqlShape;
        try validateGeneratedDmlAstBoundaryMirror(tokens, body_dml, prefix_dml);
        return;
    }
    if (mirror_read != null or mirror_dml != null) return error.UnsupportedSqlShape;
    return error.UnsupportedSqlShape;
}

fn generatedDmlOptionalTokenRangeEqual(
    a: ?generated_parser.GeneratedSqlTokenRange,
    b: ?generated_parser.GeneratedSqlTokenRange,
) bool {
    if (a == null or b == null) return a == null and b == null;
    return generatedDmlTokenRangeEqual(a.?, b.?);
}

fn generatedDmlTokenRangeSliceEqual(
    a: []const generated_parser.GeneratedSqlTokenRange,
    b: []const generated_parser.GeneratedSqlTokenRange,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |a_item, b_item| {
        if (!generatedDmlTokenRangeEqual(a_item, b_item)) return false;
    }
    return true;
}

fn generatedDmlOptionalTokenRangeSliceEqual(
    a: []const ?generated_parser.GeneratedSqlTokenRange,
    b: []const ?generated_parser.GeneratedSqlTokenRange,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |a_item, b_item| {
        if (!generatedDmlOptionalTokenRangeEqual(a_item, b_item)) return false;
    }
    return true;
}

fn generatedDmlListScalarSurfaceEqual(
    a: generated_parser.GeneratedSqlListAst,
    b: generated_parser.GeneratedSqlListAst,
) bool {
    return a.count == b.count and
        generatedDmlOptionalTokenRangeEqual(a.first_tokens, b.first_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.last_tokens, b.last_tokens) and
        generatedDmlTokenRangeSliceEqual(a.items, b.items) and
        generatedDmlTokenRangeSliceEqual(a.expression_items, b.expression_items) and
        generatedDmlOptionalTokenRangeSliceEqual(a.alias_items, b.alias_items) and
        generatedDmlOptionalTokenRangeSliceEqual(a.alias_name_items, b.alias_name_items) and
        generatedDmlOptionalTokenRangeSliceEqual(a.direction_items, b.direction_items) and
        generatedDmlOrderDirectionSliceEqual(a.directions, b.directions) and
        generatedDmlOptionalTokenRangeSliceEqual(a.order_using_operator_items, b.order_using_operator_items) and
        generatedDmlOptionalTokenRangeSliceEqual(a.nulls_order_items, b.nulls_order_items) and
        generatedDmlNullsOrderSliceEqual(a.nulls_orders, b.nulls_orders);
}

fn generatedDmlOptionalExpressionPtrSurfaceEqual(
    a: ?*const generated_parser.GeneratedSqlExpressionAst,
    b: ?*const generated_parser.GeneratedSqlExpressionAst,
) bool {
    if (a == null or b == null) return a == null and b == null;
    return generatedDmlOptionalExpressionSurfaceEqual(a.?.*, b.?.*);
}

fn generatedDmlSetOperationPtrSurfaceEqual(
    a: ?*const generated_parser.GeneratedSqlSetOperationAst,
    b: ?*const generated_parser.GeneratedSqlSetOperationAst,
) bool {
    if (a == null or b == null) return a == null and b == null;
    return generatedDmlSetOperationSurfaceEqual(a.?.*, b.?.*);
}

fn generatedDmlSubqueryTailSurfaceEqual(
    a: generated_parser.GeneratedSqlSubqueryTailAst,
    b: generated_parser.GeneratedSqlSubqueryTailAst,
) bool {
    return a.limit_all == b.limit_all and
        generatedDmlOptionalTokenRangeEqual(a.order_tokens, b.order_tokens) and
        generatedDmlListSurfaceEqual(a.order_items, b.order_items) and
        generatedDmlOptionalExpressionPtrSurfaceEqual(a.order_first_expression, b.order_first_expression) and
        generatedDmlOptionalExpressionPtrSurfaceEqual(a.order_last_expression, b.order_last_expression) and
        generatedDmlOptionalTokenRangeEqual(a.limit_tokens, b.limit_tokens) and
        generatedDmlOptionalExpressionPtrSurfaceEqual(a.limit_expression, b.limit_expression) and
        generatedDmlOptionalTokenRangeEqual(a.offset_tokens, b.offset_tokens) and
        generatedDmlOptionalExpressionPtrSurfaceEqual(a.offset_expression, b.offset_expression) and
        generatedDmlOptionalTokenRangeEqual(a.fetch_tokens, b.fetch_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.fetch_count_tokens, b.fetch_count_tokens) and
        generatedDmlOptionalExpressionPtrSurfaceEqual(a.fetch_count_expression, b.fetch_count_expression);
}

fn generatedDmlSubqueryTailPtrSurfaceEqual(
    a: ?*const generated_parser.GeneratedSqlSubqueryTailAst,
    b: ?*const generated_parser.GeneratedSqlSubqueryTailAst,
) bool {
    if (a == null or b == null) return a == null and b == null;
    return generatedDmlSubqueryTailSurfaceEqual(a.?.*, b.?.*);
}

fn generatedDmlOptionalExpressionSurfaceEqual(
    a: generated_parser.GeneratedSqlExpressionAst,
    b: generated_parser.GeneratedSqlExpressionAst,
) bool {
    if (a.kind != b.kind or
        a.inner_expression_kind != b.inner_expression_kind or
        a.subquery_read_kind != b.subquery_read_kind or
        a.subquery_where_expression_kind != b.subquery_where_expression_kind or
        a.aggregate_function_kind != b.aggregate_function_kind or
        a.window_function_kind != b.window_function_kind or
        a.filter_expression_kind != b.filter_expression_kind or
        a.over_frame_start_expression_kind != b.over_frame_start_expression_kind or
        a.over_frame_end_expression_kind != b.over_frame_end_expression_kind or
        a.cast_expression_kind != b.cast_expression_kind or
        a.case_branch_count != b.case_branch_count or
        a.case_first_condition_kind != b.case_first_condition_kind or
        a.case_first_result_kind != b.case_first_result_kind or
        a.case_else_expression_kind != b.case_else_expression_kind or
        a.boolean_condition_count != b.boolean_condition_count or
        a.boolean_first_condition_kind != b.boolean_first_condition_kind or
        a.boolean_last_condition_kind != b.boolean_last_condition_kind or
        a.extract_source_expression_kind != b.extract_source_expression_kind or
        a.left_expression_kind != b.left_expression_kind or
        a.between_modifier != b.between_modifier or
        a.between_lower_expression_kind != b.between_lower_expression_kind or
        a.between_upper_expression_kind != b.between_upper_expression_kind or
        a.right_expression_kind != b.right_expression_kind or
        a.escape_expression_kind != b.escape_expression_kind)
    {
        return false;
    }

    if (!generatedDmlOptionalTokenRangeEqual(a.tokens, b.tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.inner_tokens, b.inner_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.subquery_select_tokens, b.subquery_select_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.subquery_projection_tokens, b.subquery_projection_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.subquery_source_tokens, b.subquery_source_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.subquery_where_tokens, b.subquery_where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.subquery_set_operation_tokens, b.subquery_set_operation_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.function_name_tokens, b.function_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.argument_tokens, b.argument_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.argument_distinct_tokens, b.argument_distinct_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.argument_value_tokens, b.argument_value_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.argument_order_tokens, b.argument_order_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.within_group_tokens, b.within_group_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.within_group_order_tokens, b.within_group_order_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.filter_tokens, b.filter_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.filter_predicate_tokens, b.filter_predicate_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_tokens, b.over_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_name_tokens, b.over_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_definition_tokens, b.over_definition_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_partition_tokens, b.over_partition_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_order_tokens, b.over_order_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_frame_tokens, b.over_frame_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_frame_start_expression_tokens, b.over_frame_start_expression_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.over_frame_end_expression_tokens, b.over_frame_end_expression_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.array_tokens, b.array_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.cast_expression_tokens, b.cast_expression_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.cast_type_tokens, b.cast_type_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_first_when_tokens, b.case_first_when_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_last_when_tokens, b.case_last_when_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_first_condition_tokens, b.case_first_condition_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_first_result_tokens, b.case_first_result_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_else_tokens, b.case_else_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.case_else_expression_tokens, b.case_else_expression_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.boolean_first_condition_tokens, b.boolean_first_condition_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.boolean_last_condition_tokens, b.boolean_last_condition_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.interval_value_tokens, b.interval_value_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.timestamp_type_tokens, b.timestamp_type_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.timestamp_value_tokens, b.timestamp_value_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.current_timestamp_precision_tokens, b.current_timestamp_precision_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.extract_field_tokens, b.extract_field_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.extract_source_tokens, b.extract_source_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.left_tokens, b.left_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.negation_tokens, b.negation_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.operator_tokens, b.operator_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.between_modifier_tokens, b.between_modifier_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.between_lower_tokens, b.between_lower_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.between_upper_tokens, b.between_upper_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.quantifier_tokens, b.quantifier_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.right_tokens, b.right_tokens) or
