        !generatedDmlOptionalTokenRangeEqual(a.having_tokens, b.having_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.window_tokens, b.window_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.order_tokens, b.order_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.limit_tokens, b.limit_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.offset_tokens, b.offset_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.fetch_tokens, b.fetch_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.fetch_count_tokens, b.fetch_count_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.row_lock_tokens, b.row_lock_tokens) or
        a.row_lock_mode != b.row_lock_mode or
        a.row_lock_wait_policy != b.row_lock_wait_policy or
        !generatedDmlOptionalTokenRangeEqual(a.set_operation_tokens, b.set_operation_tokens))
    {
        return false;
    }
    return generatedDmlReadCteSliceSurfaceEqual(a.cte_items, b.cte_items) and
        generatedDmlAntflyTableFunctionSliceEqual(a.source_antfly_function_items, b.source_antfly_function_items) and
        generatedDmlGraphTableFunctionSliceEqual(a.source_graph_function_items, b.source_graph_function_items) and
        generatedDmlListSurfaceEqual(a.distinct_on_items, b.distinct_on_items) and
        generatedDmlListSurfaceEqual(a.projection_items, b.projection_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.projection_first_expression, b.projection_first_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.projection_last_expression, b.projection_last_expression) and
        generatedDmlJoinSliceSurfaceEqual(a.join_items, b.join_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.join_predicate_expression, b.join_predicate_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.where_expression, b.where_expression) and
        generatedDmlListSurfaceEqual(a.group_items, b.group_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.group_first_expression, b.group_first_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.group_last_expression, b.group_last_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.having_expression, b.having_expression) and
        generatedDmlWindowSliceSurfaceEqual(a.window_items, b.window_items) and
        generatedDmlListSurfaceEqual(a.order_items, b.order_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.order_first_expression, b.order_first_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.order_last_expression, b.order_last_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.limit_expression, b.limit_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.offset_expression, b.offset_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.fetch_count_expression, b.fetch_count_expression) and
        generatedDmlSetOperationSurfaceEqual(a.set_operation, b.set_operation);
}

fn generatedDmlAstSurfaceEqual(
    a: generated_parser.GeneratedSqlDmlAst,
    b: generated_parser.GeneratedSqlDmlAst,
) bool {
    if (a.kind != b.kind or
        !std.meta.eql(a.statement_span, b.statement_span) or
        !std.meta.eql(a.command_span, b.command_span) or
        a.cte_recursive != b.cte_recursive or
        a.mutation_source_tail != b.mutation_source_tail or
        a.mutation_join_source != b.mutation_join_source or
        a.default_values != b.default_values or
        a.mutation_limit_all != b.mutation_limit_all or
        a.restart_identity != b.restart_identity or
        a.cascade != b.cascade)
    {
        return false;
    }

    if (!generatedDmlOptionalTokenRangeEqual(a.cte_tokens, b.cte_tokens) or
        !generatedDmlOptionalCtePrefixSurfaceEqual(a.cte_prefix, b.cte_prefix) or
        !generatedDmlOptionalTokenRangeEqual(a.target_table_tokens, b.target_table_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.target_alias_tokens, b.target_alias_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.target_alias_name_tokens, b.target_alias_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.insert_columns_tokens, b.insert_columns_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.values_tokens, b.values_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.source_tokens, b.source_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.assignments_tokens, b.assignments_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.where_tokens, b.where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_order_tokens, b.mutation_order_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_limit_tokens, b.mutation_limit_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_offset_tokens, b.mutation_offset_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_fetch_tokens, b.mutation_fetch_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_fetch_count_tokens, b.mutation_fetch_count_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.mutation_row_lock_tokens, b.mutation_row_lock_tokens) or
        a.mutation_row_lock_mode != b.mutation_row_lock_mode or
        a.mutation_row_lock_wait_policy != b.mutation_row_lock_wait_policy or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_tokens, b.conflict_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_target_tokens, b.conflict_target_tokens) or
        a.conflict_target_kind != b.conflict_target_kind or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_action_tokens, b.conflict_action_tokens) or
        a.conflict_action_kind != b.conflict_action_kind or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_assignments_tokens, b.conflict_assignments_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_target_where_tokens, b.conflict_target_where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.conflict_action_where_tokens, b.conflict_action_where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.returning_tokens, b.returning_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.additional_target_tokens, b.additional_target_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.semijoin_source_table_tokens, b.semijoin_source_table_tokens))
    {
        return false;
    }

    return generatedDmlListSurfaceEqual(a.insert_column_items, b.insert_column_items) and
        generatedDmlListSurfaceEqual(a.insert_value_rows, b.insert_value_rows) and
        generatedDmlOptionalReadBodySurfaceEqual(a.source_read, b.source_read) and
        generatedDmlListSurfaceEqual(a.assignment_items, b.assignment_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.where_expression, b.where_expression) and
        generatedDmlListSurfaceEqual(a.mutation_order_items, b.mutation_order_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.mutation_limit_expression, b.mutation_limit_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.mutation_offset_expression, b.mutation_offset_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.mutation_fetch_count_expression, b.mutation_fetch_count_expression) and
        generatedDmlListSurfaceEqual(a.conflict_target_items, b.conflict_target_items) and
        generatedDmlListSurfaceEqual(a.conflict_assignment_items, b.conflict_assignment_items) and
        generatedDmlOptionalExpressionSurfaceEqual(a.conflict_target_where_expression, b.conflict_target_where_expression) and
        generatedDmlOptionalExpressionSurfaceEqual(a.conflict_action_where_expression, b.conflict_action_where_expression) and
        generatedDmlListSurfaceEqual(a.returning_items, b.returning_items) and
        generatedDmlListSurfaceEqual(a.additional_target_items, b.additional_target_items) and
        generatedDmlMergeArmListSurfaceEqual(a.merge_arms, b.merge_arms);
}

fn generatedDmlAntflyTableFunctionEqual(
    a: generated_parser.GeneratedSqlAntflyTableFunctionAst,
    b: generated_parser.GeneratedSqlAntflyTableFunctionAst,
) bool {
    if (a.kind != b.kind or
        a.argument_count != b.argument_count or
        a.argument_items.len != b.argument_items.len or
        !generatedDmlTokenRangeEqual(a.tokens, b.tokens) or
        !generatedDmlTokenRangeEqual(a.name_tokens, b.name_tokens) or
        !generatedDmlTokenRangeEqual(a.argument_tokens, b.argument_tokens))
    {
        return false;
    }
    for (a.argument_items, b.argument_items) |a_argument, b_argument| {
        if (!generatedDmlTokenRangeEqual(a_argument.tokens, b_argument.tokens) or
            !generatedDmlTokenRangeEqual(a_argument.name_tokens, b_argument.name_tokens) or
            !generatedDmlTokenRangeEqual(a_argument.operator_tokens, b_argument.operator_tokens) or
            !generatedDmlTokenRangeEqual(a_argument.value_tokens, b_argument.value_tokens))
        {
            return false;
        }
    }
    return true;
}

fn generatedDmlAntflyTableFunctionSliceEqual(
    a: []const generated_parser.GeneratedSqlAntflyTableFunctionAst,
    b: []const generated_parser.GeneratedSqlAntflyTableFunctionAst,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |a_item, b_item| {
        if (!generatedDmlAntflyTableFunctionEqual(a_item, b_item)) return false;
    }
    return true;
}

fn generatedDmlGraphTableFunctionEqual(
    a: generated_parser.GeneratedSqlGraphTableFunctionAst,
    b: generated_parser.GeneratedSqlGraphTableFunctionAst,
) bool {
    return a.kind == b.kind and
        a.argument_count == b.argument_count and
        generatedDmlTokenRangeEqual(a.tokens, b.tokens) and
        generatedDmlTokenRangeEqual(a.name_tokens, b.name_tokens) and
        generatedDmlTokenRangeEqual(a.argument_tokens, b.argument_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.table_name_value_tokens, b.table_name_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.index_value_tokens, b.index_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.start_value_tokens, b.start_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.start_result_ref_value_tokens, b.start_result_ref_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.target_value_tokens, b.target_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.target_result_ref_value_tokens, b.target_result_ref_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.pattern_value_tokens, b.pattern_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.return_value_tokens, b.return_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.metric_value_tokens, b.metric_value_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.query_value_tokens, b.query_value_tokens);
}

fn generatedDmlGraphTableFunctionSliceEqual(
    a: []const generated_parser.GeneratedSqlGraphTableFunctionAst,
    b: []const generated_parser.GeneratedSqlGraphTableFunctionAst,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |a_item, b_item| {
        if (!generatedDmlGraphTableFunctionEqual(a_item, b_item)) return false;
    }
    return true;
}

fn generatedDmlMergeArmSurfaceEqual(
    a: generated_parser.GeneratedSqlMergeArmAst,
    b: generated_parser.GeneratedSqlMergeArmAst,
) bool {
    return a.action_kind == b.action_kind and
        a.matched == b.matched and
        generatedDmlTokenRangeEqual(a.tokens, b.tokens) and
        generatedDmlOptionalTokenRangeEqual(a.predicate_tokens, b.predicate_tokens) and
        generatedDmlOptionalExpressionSurfaceEqual(a.predicate_expression, b.predicate_expression) and
        generatedDmlTokenRangeEqual(a.action_tokens, b.action_tokens) and
        generatedDmlOptionalTokenRangeEqual(a.assignments_tokens, b.assignments_tokens) and
        generatedDmlListSurfaceEqual(a.assignment_items, b.assignment_items) and
        generatedDmlOptionalTokenRangeEqual(a.insert_columns_tokens, b.insert_columns_tokens) and
        generatedDmlListSurfaceEqual(a.insert_column_items, b.insert_column_items) and
        generatedDmlOptionalTokenRangeEqual(a.insert_values_tokens, b.insert_values_tokens) and
        generatedDmlListSurfaceEqual(a.insert_value_items, b.insert_value_items);
}

fn generatedDmlMergeArmListSurfaceEqual(
    a: generated_parser.GeneratedSqlMergeArmListAst,
    b: generated_parser.GeneratedSqlMergeArmListAst,
) bool {
    if (a.count != b.count or
        a.matched_count != b.matched_count or
        a.not_matched_count != b.not_matched_count or
        a.items.len != b.items.len or
        !generatedDmlOptionalTokenRangeEqual(a.first_tokens, b.first_tokens) or
        !generatedDmlOptionalTokenRangeEqual(a.last_tokens, b.last_tokens))
    {
        return false;
    }
    for (a.items, b.items) |a_item, b_item| {
        if (!generatedDmlMergeArmSurfaceEqual(a_item, b_item)) return false;
    }
    return true;
}

fn validateGeneratedDmlAstBoundaryMirror(
    tokens: []const Token,
    body_dml: *const generated_parser.GeneratedSqlDmlAst,
    prefix_dml: *const generated_parser.GeneratedSqlDmlAst,
) !void {
    if (!generatedDmlAstSurfaceEqual(body_dml.*, prefix_dml.*)) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementSpanEnd(tokens, body_dml.statement_span) orelse return error.UnsupportedSqlShape;
    const start = generatedDmlStatementSpanStart(tokens, body_dml.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlBoundaryMirrorAssignments(tokens, start, end, body_dml.*);
    try validateGeneratedDmlBoundaryMirrorWhereExpression(tokens, start, end, body_dml.*);
    try validateGeneratedDmlBoundaryMirrorReturningItems(tokens, end, body_dml.*);
}

fn validateGeneratedDmlBoundaryMirrorAssignments(
    tokens: []const Token,
    body_start: usize,
    body_end: usize,
    body_dml: generated_parser.GeneratedSqlDmlAst,
) !void {
    switch (body_dml.kind) {
        .update => {
            const assignments = body_dml.assignments_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedDmlBoundaryMirrorListItemsRange(tokens, body_start, body_end, assignments, &body_dml.assignment_items, .set);
        },
        else => if (body_dml.assignments_tokens != null) return error.UnsupportedSqlShape else try validateGeneratedDmlEmptyList(&body_dml.assignment_items),
    }
}

fn validateGeneratedDmlBoundaryMirrorWhereExpression(
    tokens: []const Token,
    body_start: usize,
    body_end: usize,
    body_dml: generated_parser.GeneratedSqlDmlAst,
) !void {
    switch (body_dml.kind) {
        .update, .delete => {
            if (validateGeneratedDmlWhereExpressionMetadata(tokens, body_end, body_dml)) return else |_| {}
            if (body_start >= body_end or body_end > tokens.len) return error.UnsupportedSqlShape;
            const local_tokens = tokens[body_start..body_end];
            try validateGeneratedDmlWhereExpressionMetadata(local_tokens, local_tokens.len, body_dml);
        },
        else => try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, body_dml.where_expression),
    }
}

fn validateGeneratedDmlBoundaryMirrorReturningItems(
    tokens: []const Token,
    body_end: usize,
    body_dml: generated_parser.GeneratedSqlDmlAst,
) !void {
    const returning_tokens = body_dml.returning_tokens orelse {
        try validateGeneratedDmlEmptyList(&body_dml.returning_items);
        return;
    };
    if (returning_tokens.start > 0 and
        returning_tokens.start < returning_tokens.end and
        returning_tokens.end <= tokens.len and
        tokens[returning_tokens.start - 1].matchesKeywordTag(.returning))
    {
        try generated_read_validate.validateGeneratedProjectionListForClause(tokens, returning_tokens, body_dml.returning_items);
        return;
    }

    const body_start = generatedDmlStatementSpanStart(tokens, body_dml.statement_span) orelse return error.UnsupportedSqlShape;
    if (body_start >= body_end or body_end > tokens.len) return error.UnsupportedSqlShape;
    const body_len = body_end - body_start;
    if (returning_tokens.start == 0 or returning_tokens.start >= returning_tokens.end or returning_tokens.end > body_len) return error.UnsupportedSqlShape;
    const local_tokens = tokens[body_start..body_end];
    if (!local_tokens[returning_tokens.start - 1].matchesKeywordTag(.returning)) return error.UnsupportedSqlShape;
    try generated_read_validate.validateGeneratedProjectionListForClause(local_tokens, returning_tokens, body_dml.returning_items);
}

fn validateGeneratedDmlBoundaryMirrorListItemsRange(
    tokens: []const Token,
    body_start: usize,
    body_end: usize,
    range: generated_parser.GeneratedSqlTokenRange,
    list: *const generated_parser.GeneratedSqlListAst,
    keyword: token_mod.TokenKeyword,
) !void {
    if (body_start >= body_end or body_end > tokens.len) return error.UnsupportedSqlShape;
    if (range.start >= body_start and range.end <= body_end and range.start > 0 and tokens[range.start - 1].matchesKeywordTag(keyword)) {
        try validateGeneratedDmlListItemsRange(tokens, range, list);
        return;
    }
    const local_tokens = tokens[body_start..body_end];
    if (range.start == 0 or range.start >= range.end or range.end > local_tokens.len) return error.UnsupportedSqlShape;
    if (!local_tokens[range.start - 1].matchesKeywordTag(keyword)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(local_tokens, range, list);
}

fn validateGeneratedDmlReadBodyBoundaryMirror(
    tokens: []const Token,
    body_read: generated_parser.GeneratedSqlDmlReadBodyAst,
    prefix_read: generated_parser.GeneratedSqlDmlReadBodyAst,
) !void {
    if (body_read.kind != prefix_read.kind or
        !std.meta.eql(body_read.statement_span, prefix_read.statement_span) or
        !std.meta.eql(body_read.command_span, prefix_read.command_span) or
        body_read.wrapper_projection_star != prefix_read.wrapper_projection_star or
        body_read.source_antfly_function_count != prefix_read.source_antfly_function_count or
        body_read.source_graph_function_count != prefix_read.source_graph_function_count or
        body_read.source_antfly_function_items.len != prefix_read.source_antfly_function_items.len or
        body_read.source_graph_function_items.len != prefix_read.source_graph_function_items.len)
    {
        return error.UnsupportedSqlShape;
    }
    for (body_read.source_antfly_function_items, prefix_read.source_antfly_function_items) |body_item, prefix_item| {
        if (!generatedDmlAntflyTableFunctionEqual(body_item, prefix_item)) return error.UnsupportedSqlShape;
    }
    for (body_read.source_graph_function_items, prefix_read.source_graph_function_items) |body_item, prefix_item| {
        if (!generatedDmlGraphTableFunctionEqual(body_item, prefix_item)) return error.UnsupportedSqlShape;
    }
    if (!generatedDmlTokenRangeEqual(body_read.tokens, prefix_read.tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.projection_tokens, prefix_read.projection_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_tokens, prefix_read.source_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_table_tokens, prefix_read.source_table_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_alias_tokens, prefix_read.source_alias_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_alias_name_tokens, prefix_read.source_alias_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_system_time_tokens, prefix_read.source_system_time_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.source_system_time_sequence_tokens, prefix_read.source_system_time_sequence_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.where_tokens, prefix_read.where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(body_read.set_operation_tokens, prefix_read.set_operation_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlReadBodyLayout(tokens, body_read.tokens, body_read);
    try validateGeneratedDmlReadBodyReadAst(tokens, body_read.tokens, body_read);
    try validateGeneratedDmlReadAstBoundaryMirror(body_read.read_ast, prefix_read.read_ast);
}

fn validateGeneratedDmlReadAstBoundaryMirror(
    maybe_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    maybe_prefix_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !void {
    if (maybe_read_ast == null or maybe_prefix_ast == null) {
        if (maybe_read_ast == null and maybe_prefix_ast == null) return;
        return error.UnsupportedSqlShape;
    }
    const read_ast = maybe_read_ast.?;
    const prefix_ast = maybe_prefix_ast.?;
    if (read_ast.kind != prefix_ast.kind or
        !std.meta.eql(read_ast.statement_span, prefix_ast.statement_span) or
        !std.meta.eql(read_ast.command_span, prefix_ast.command_span) or
        read_ast.source_antfly_function_count != prefix_ast.source_antfly_function_count or
        read_ast.source_graph_function_count != prefix_ast.source_graph_function_count or
        read_ast.source_antfly_function_items.len != prefix_ast.source_antfly_function_items.len or
        read_ast.source_graph_function_items.len != prefix_ast.source_graph_function_items.len or
        read_ast.source_graph_function_kind != prefix_ast.source_graph_function_kind)
    {
        return error.UnsupportedSqlShape;
    }
    for (read_ast.source_antfly_function_items, prefix_ast.source_antfly_function_items) |read_item, prefix_item| {
        if (!generatedDmlAntflyTableFunctionEqual(read_item, prefix_item)) return error.UnsupportedSqlShape;
    }
    for (read_ast.source_graph_function_items, prefix_ast.source_graph_function_items) |read_item, prefix_item| {
        if (!generatedDmlGraphTableFunctionEqual(read_item, prefix_item)) return error.UnsupportedSqlShape;
    }
    if (!generatedDmlOptionalTokenRangeEqual(read_ast.projection_tokens, prefix_ast.projection_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_tokens, prefix_ast.source_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_table_tokens, prefix_ast.source_table_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_alias_tokens, prefix_ast.source_alias_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_alias_name_tokens, prefix_ast.source_alias_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_system_time_tokens, prefix_ast.source_system_time_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_system_time_sequence_tokens, prefix_ast.source_system_time_sequence_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_graph_function_tokens, prefix_ast.source_graph_function_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_graph_function_name_tokens, prefix_ast.source_graph_function_name_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.source_graph_function_argument_tokens, prefix_ast.source_graph_function_argument_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.where_tokens, prefix_ast.where_tokens) or
        !generatedDmlOptionalTokenRangeEqual(read_ast.set_operation_tokens, prefix_ast.set_operation_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    if (!generatedDmlReadAstSurfaceEqual(read_ast.*, prefix_ast.*)) return error.UnsupportedSqlShape;
}

fn generatedDmlCteNameAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    cte: *const generated_parser.GeneratedSqlDmlCteItemAst,
    pos: *usize,
) ![]const u8 {
    if (cte.name_tokens.start != pos.* or cte.name_tokens.end != cte.name_tokens.start + 1 or cte.name_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[cte.name_tokens.start].kind != .identifier) return error.UnsupportedSqlShape;
    pos.* = cte.name_tokens.end;
    return try alloc.dupe(u8, tokens[cte.name_tokens.start].text);
}

fn generatedDmlCteColumnAliasesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    cte: *const generated_parser.GeneratedSqlDmlCteItemAst,
    pos: *usize,
) ![]const []const u8 {
    const column_tokens = cte.column_tokens orelse {
        if (cte.column_name_tokens != null) return error.UnsupportedSqlShape;
        try validateGeneratedDmlEmptyList(&cte.column_names);
        if (pos.* < tokens.len and tokens[pos.*].kind == .lparen) return error.UnsupportedSqlShape;
        return &.{};
    };
    if (column_tokens.start != pos.* or column_tokens.end > tokens.len or column_tokens.end <= column_tokens.start + 1) return error.UnsupportedSqlShape;
    if (tokens[column_tokens.start].kind != .lparen or tokens[column_tokens.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    const column_name_tokens = cte.column_name_tokens orelse return error.UnsupportedSqlShape;
    if (column_name_tokens.start != column_tokens.start + 1 or column_name_tokens.end != column_tokens.end - 1) return error.UnsupportedSqlShape;
    if (cte.column_names.count == 0 or cte.column_names.items.len != cte.column_names.count) return error.UnsupportedSqlShape;
    if (cte.column_names.expression_items.len != cte.column_names.count or cte.column_names.expressions.len != cte.column_names.count) return error.UnsupportedSqlShape;
    if (cte.column_names.alias_items.len != cte.column_names.count or cte.column_names.alias_name_items.len != cte.column_names.count) return error.UnsupportedSqlShape;
    if (cte.column_names.direction_items.len != cte.column_names.count or cte.column_names.directions.len != cte.column_names.count) return error.UnsupportedSqlShape;
    if (cte.column_names.order_using_operator_items.len != cte.column_names.count or cte.column_names.nulls_order_items.len != cte.column_names.count or cte.column_names.nulls_orders.len != cte.column_names.count) return error.UnsupportedSqlShape;
    if (cte.column_names.first_tokens == null or cte.column_names.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEqual(cte.column_names.first_tokens.?, cte.column_names.items[0])) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEqual(cte.column_names.last_tokens.?, cte.column_names.items[cte.column_names.count - 1])) return error.UnsupportedSqlShape;

    var aliases = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (aliases.items) |alias| alloc.free(alias);
        aliases.deinit(alloc);
    }
    var expected_start = column_name_tokens.start;
    for (cte.column_names.items, 0..) |item, index| {
        if (item.start != expected_start or item.end != item.start + 1 or item.end > column_name_tokens.end) return error.UnsupportedSqlShape;
        if (tokens[item.start].kind != .identifier) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEqual(cte.column_names.expression_items[index], item)) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEqual(cte.column_names.expressions[index].tokens orelse return error.UnsupportedSqlShape, item)) return error.UnsupportedSqlShape;
        if (cte.column_names.alias_items[index] != null or
            cte.column_names.alias_name_items[index] != null or
            cte.column_names.direction_items[index] != null or
            cte.column_names.directions[index] != null or
            cte.column_names.order_using_operator_items[index] != null or
            cte.column_names.nulls_order_items[index] != null or
            cte.column_names.nulls_orders[index] != null)
        {
            return error.UnsupportedSqlShape;
        }
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, item, cte.column_names.expressions[index]);
        try aliases.append(alloc, try alloc.dupe(u8, tokens[item.start].text));
        expected_start = item.end;
        if (index + 1 < cte.column_names.items.len) {
            if (expected_start >= column_name_tokens.end or tokens[expected_start].kind != .comma) return error.UnsupportedSqlShape;
            expected_start += 1;
        }
    }
    if (expected_start != column_name_tokens.end) return error.UnsupportedSqlShape;
    pos.* = column_tokens.end;
    return try aliases.toOwnedSlice(alloc);
}

fn consumeGeneratedDmlCteMaterialization(
    tokens: []const Token,
    cte: *const generated_parser.GeneratedSqlDmlCteItemAst,
    pos: *usize,
) !void {
    const materialization_tokens = cte.materialization_tokens orelse {
        if (cte.materialization != null) return error.UnsupportedSqlShape;
        if (pos.* < tokens.len and (tokens[pos.*].matchesKeywordTag(.materialized) or tokens[pos.*].matchesKeywordTag(.not))) return error.UnsupportedSqlShape;
        return;
    };
    if (materialization_tokens.start != pos.* or materialization_tokens.end > tokens.len or materialization_tokens.start >= materialization_tokens.end) return error.UnsupportedSqlShape;
    switch (cte.materialization orelse return error.UnsupportedSqlShape) {
        .materialized => {
            if (materialization_tokens.end != materialization_tokens.start + 1 or !tokens[materialization_tokens.start].matchesKeywordTag(.materialized)) return error.UnsupportedSqlShape;
        },
        .not_materialized => {
            if (materialization_tokens.end != materialization_tokens.start + 2 or
                !tokens[materialization_tokens.start].matchesKeywordTag(.not) or
                !tokens[materialization_tokens.start + 1].matchesKeywordTag(.materialized))
            {
                return error.UnsupportedSqlShape;
            }
        },
    }
    pos.* = materialization_tokens.end;
}

fn lowerGeneratedDmlGraphTableFunctionCteAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    body_read: *const generated_parser.GeneratedSqlDmlReadBodyAst,
) !?db_mod.types.RelationalRowsTableFunction {
    try validateGeneratedDmlReadBodyTableFunctionPayloads(
        tokens,
        body_read.source_tokens,
        body_read.source_antfly_function_items,
        body_read.source_antfly_function_count,
        body_read.source_graph_function_items,
        body_read.source_graph_function_count,
    );
    if (body_read.source_graph_function_items.len == 0) return null;
    if (body_read.source_graph_function_items.len != 1) return error.UnsupportedSqlShape;
    const graph_item = body_read.source_graph_function_items[0];
    var matching_antfly_item: ?generated_parser.GeneratedSqlAntflyTableFunctionAst = null;
    for (body_read.source_antfly_function_items) |antfly_item| {
        if (!std.meta.eql(antfly_item.tokens, graph_item.tokens)) continue;
        if (!std.meta.eql(antfly_item.name_tokens, graph_item.name_tokens)) continue;
        if (!std.meta.eql(antfly_item.argument_tokens, graph_item.argument_tokens)) continue;
        matching_antfly_item = antfly_item;
        break;
    }
    const antfly_item = matching_antfly_item orelse return error.UnsupportedSqlShape;
    return try query_function.lowerAntflyGraphTableFunctionGeneratedAstAlloc(alloc, tokens, antfly_item, graph_item);
}

fn parseDataModifyingCteMutationSourceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    parser_options: MergeMutationParserOptions,
) !plan_mod.LoweredMutationSource {
    var generated = try generated_parser.parseGeneratedGateTokensStrictAlloc(alloc, tokens) orelse return error.UnsupportedSqlShape;
    defer generated.deinit(alloc);
    const generated_dml = if (generated.ast) |*generated_ast| switch (generated_ast.*) {
        .dml => |*dml| dml,
        else => return error.UnsupportedSqlShape,
    } else return error.UnsupportedSqlShape;
    return try parseDataModifyingCteMutationSourceWithGeneratedDmlAstAlloc(alloc, tokens, pos, parser_options, generated_dml);
}

fn parseDataModifyingCteMutationSourceWithGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    parser_options: MergeMutationParserOptions,
    generated_dml: *const generated_parser.GeneratedSqlDmlAst,
) !plan_mod.LoweredMutationSource {
    const end = generatedDmlStatementEnd(tokens, generated_dml.statement_span) orelse return error.UnsupportedSqlShape;
    const options = try dataModifyingCteMutationSourceParserOptionsAlloc(alloc, parser_options);
    var generated_options = options;
    generated_options.returning_hooks.generated_returning_items = generatedDmlFinalStatementReturningItems(generated_dml);
    generated_options.generated_assignment_items = &generated_dml.assignment_items;
    generated_options.generated_dml_ast = generated_dml;
    if (parser.peekKeywordTag(tokens, pos.*, .update)) {
        if (generated_dml.kind != .update) {
            if (generated_options.row_claim.owner_id.len > 0) alloc.free(generated_options.row_claim.owner_id);
            return error.UnsupportedSqlShape;
        }
        validateGeneratedUpdateSourceRanges(tokens, generated_dml.*, end) catch |err| {
            if (generated_options.row_claim.owner_id.len > 0) alloc.free(generated_options.row_claim.owner_id);
            return err;
        };
        return try parseUpdateMutationSourceAlloc(alloc, tokens, pos, generated_options);
    }
    if (parser.peekKeywordTag(tokens, pos.*, .delete)) {
        if (generated_dml.kind != .delete) {
            if (generated_options.row_claim.owner_id.len > 0) alloc.free(generated_options.row_claim.owner_id);
            return error.UnsupportedSqlShape;
        }
        validateGeneratedDeleteSourceRanges(tokens, generated_dml.*, end) catch |err| {
            if (generated_options.row_claim.owner_id.len > 0) alloc.free(generated_options.row_claim.owner_id);
            return err;
        };
        return try parseDeleteMutationSourceAlloc(alloc, tokens, pos, generated_options);
    }
    if (generated_options.row_claim.owner_id.len > 0) alloc.free(generated_options.row_claim.owner_id);
    return error.UnsupportedSqlShape;
}

fn dataModifyingCteMutationSourceParserOptionsAlloc(
    alloc: std.mem.Allocator,
    parser_options: MergeMutationParserOptions,
) !MutationSourceParserOptions {
    return .{
        .params = parser_options.params,
        .schema = parser_options.schema,
        .function_bindings = parser_options.function_bindings,
        .row_claim = .{
            .mode = .for_update,
            .wait_policy = .wait,
            .owner_id = try alloc.dupe(u8, "__antfly_sql_data_modifying_cte_claim__"),
            .txn_id = [_]u8{0} ** 16,
        },
        .realtime_ns = parser_options.realtime_ns,
        .defer_row_expression_field_validation = parser_options.defer_row_expression_field_validation,
        .context_hooks = parser_options.mutation_context_hooks,
        .assignment_value_hooks = parser_options.mutation_assignment_value_hooks,
        .fixed_binary_hooks = parser_options.fixed_binary_hooks,
        .bare_boolean_hooks = parser_options.bare_boolean_hooks,
        .expression_alternatives_hooks = parser_options.expression_alternatives_hooks,
        .expression_condition_hooks = parser_options.expression_condition_hooks,
        .order_expression_hooks = parser_options.order_expression_hooks,
        .returning_hooks = parser_options.returning_hooks,
    };
}

fn resolveDataModifyingCteBaseSourceTableAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    base_table_name: *?[]const u8,
) !void {
    if (base_table_name.*) |base| {
        if (!std.mem.eql(u8, base, table_name)) return error.UnsupportedSqlShape;
        return;
    }
    base_table_name.* = try alloc.dupe(u8, table_name);
}

fn findDataModifyingCteByName(
    ctes: []const plan_mod.LoweredDataModifyingCte,
    name: []const u8,
) ?plan_mod.LoweredDataModifyingCte {
    for (ctes) |cte| {
        if (std.ascii.eqlIgnoreCase(cte.name, name)) return cte;
    }
    return null;
}

const DataModifyingCteReturningSchema = struct {
    schema: runtime_schema.TableSchema,
    owns_columns: bool = false,

    fn deinit(self: @This(), alloc: std.mem.Allocator) void {
        if (self.owns_columns and self.schema.relational_columns.len > 0) {
            alloc.free(self.schema.relational_columns);
        }
    }
};

fn dataModifyingCteReturningSchemaAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    producer: plan_mod.LoweredDataModifyingCte,
) !DataModifyingCteReturningSchema {
    if (producer.mutation.req.returning_all) {
        return .{ .schema = base_schema };
    }
    if (producer.mutation.req.returning_expressions.len != 0) return error.UnsupportedSqlShape;
    if (producer.mutation.req.returning.len == 0) return error.UnsupportedSqlShape;
    for (producer.mutation.req.returning) |field| {
        if (std.mem.eql(u8, field, "*")) return .{ .schema = base_schema };
    }

    var columns = try alloc.alloc(runtime_schema.RelationalColumn, producer.mutation.req.returning.len);
    errdefer alloc.free(columns);
    for (producer.mutation.req.returning, 0..) |field, i| {
        columns[i] = binder.relationalColumnForField(base_schema, field, null) orelse return error.UnsupportedSqlShape;
    }

    var schema = base_schema;
    schema.relational_columns = columns;
    schema.primary_key = null;
    schema.unique_constraints = &.{};
    schema.checks = &.{};
    schema.foreign_keys = &.{};
    return .{
        .schema = schema,
        .owns_columns = true,
    };
}

pub fn parseMergeMutationBodyAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    parser_options: MergeMutationParserOptions,
    options: MergeMutationBodyOptions,
) !plan_mod.LoweredMergeMutationPlan {
    if ((parser_options.generated_dml_ast == null) != (parser_options.generated_merge_arms == null)) return error.UnsupportedSqlShape;
    try parser.expectKeywordTag(tokens, pos, .merge);
    try parser.expectKeywordTag(tokens, pos, .into);
    const target_table = if (try generatedMergeTargetAliasAlloc(alloc, tokens, pos, parser_options.generated_dml_ast)) |generated_target|
        generated_target
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, target_table);
    try parser.expectKeywordTag(tokens, pos, .using);
    const source_table = if (try generatedMergeSourceAliasAlloc(alloc, tokens, pos, parser_options.generated_dml_ast)) |generated_source|
        generated_source
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, source_table);
    if (std.mem.eql(u8, target_table.alias, source_table.alias)) return error.UnsupportedSqlShape;

    var source = db_mod.types.RelationalRowsQueryRequest{};
    errdefer source.deinit(alloc);
    var resolved_source_table = source_table.name;
    const base_source_schema = parser_options.joined_source_schema orelse parser_options.schema;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);

    const previous_context = parser_options.context_hooks.get_context(parser_options.context_hooks.ptr);
    var parse_context = previous_context;
    parse_context.joined_source_schema = parser_options.joined_source_schema;
    parse_context.available_ctes = options.ctes;
    var source_resolved_from_cte = false;
    const data_cte_source = findDataModifyingCteByName(options.data_modifying_ctes, source_table.name);
    var data_cte_source_schema: ?DataModifyingCteReturningSchema = null;
    defer if (data_cte_source_schema) |schema| schema.deinit(alloc);
    if (options.ctes.len != 0) {
        planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, base_source_schema, options.ctes);
        if (relational_rows.rowsPlannedCteSchema(planned_ctes, source_table.name)) |cte_schema| {
            source.source_cte = try alloc.dupe(u8, source_table.name);
            parse_context.joined_source_schema = cte_schema;
            resolved_source_table = (options.base_table_name orelse return error.UnsupportedSqlShape).* orelse return error.UnsupportedSqlShape;
            source_resolved_from_cte = true;
        } else if (data_cte_source == null) {
            const base_ptr = options.base_table_name orelse return error.UnsupportedSqlShape;
            if (base_ptr.*) |base| {
                if (!std.mem.eql(u8, base, source_table.name)) return error.UnsupportedSqlShape;
            } else {
                base_ptr.* = try alloc.dupe(u8, source_table.name);
            }
        }
    }
    if (!source_resolved_from_cte) {
        if (data_cte_source) |producer| {
            if (source.source_cte.len != 0) return error.UnsupportedSqlShape;
            source.source_cte = try alloc.dupe(u8, source_table.name);
            data_cte_source_schema = try dataModifyingCteReturningSchemaAlloc(alloc, parser_options.schema, producer);
            parse_context.joined_source_schema = data_cte_source_schema.?.schema;
            resolved_source_table = producer.table_name;
        } else if (options.data_modifying_ctes.len != 0) {
            return error.UnsupportedSqlShape;
        }
    }
    parser_options.context_hooks.set_context(parser_options.context_hooks.ptr, parse_context);
    defer parser_options.context_hooks.set_context(parser_options.context_hooks.ptr, previous_context);

    const clauses = try parseMergeMutationClausesAlloc(
        alloc,
        tokens,
        pos,
        parser_options.schema,
        parse_context.joined_source_schema,
        target_table,
        source_table,
        options.ctes.len,
        parser_options.params,
        parser_options.realtime_ns,
        parser_options.condition_options,
        parser_options.assignment_options,
        parser_options.generated_merge_arms,
        parser_options.returning_hooks,
    );
    errdefer {
        var owned_clauses = clauses;
        owned_clauses.deinit(alloc);
    }

    return .{
        .target_table_name = try alloc.dupe(u8, target_table.name),
        .source_table_name = try alloc.dupe(u8, resolved_source_table),
        .source = source,
        .match_fields = clauses.match_fields,
        .matched_arms = clauses.matched_arms,
        .not_matched_arms = clauses.not_matched_arms,
        .returning = clauses.returning,
    };
}

pub fn parseJoinedMutationSourceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    cte_hooks: plan_mod.CteSelectParserHooks,
    hooks: JoinedMutationSourceParserHooks,
) !plan_mod.LoweredJoinedMutationSource {
    if (!parser.peekKeywordTag(tokens, pos.*, .with)) return try hooks.parse_joined_mutation_source(hooks.ptr, &.{}, null);

    var base_table_name: ?[]const u8 = null;
    defer if (base_table_name) |table| alloc.free(table);
    var ctes = try plan_mod.parseCtesForPlanAlloc(alloc, tokens, pos, &base_table_name, cte_hooks);
    errdefer plan_mod.freePlanCtes(alloc, ctes);

    const lowered = try hooks.parse_joined_mutation_source(hooks.ptr, ctes, &base_table_name);
    plan_mod.freePlanCtes(alloc, ctes);
    ctes = &.{};
    return lowered;
}

pub const JoinedMutationSourceAssignment = struct {
    field: []const u8,
    source_qualifier: []const u8,
    source_field: []const u8,
};

pub const FieldExpressionValue = struct {
    field: []const u8,
    expression: db_mod.types.RelationalRowsExpression,
};

pub const FieldPredicate = struct {
    field: []const u8,
    op: runtime_schema.UniquePredicateOp,
    value_json: ?[]const u8 = null,
};

pub const JsonSetValue = struct {
    field: []const u8,
    path: []const []const u8,
    value_json: ?[]const u8 = null,
    expression: ?db_mod.types.RelationalRowsExpression = null,
};

pub const JsonSetParsedValue = struct {
    value_json: ?[]const u8 = null,
    expression: ?db_mod.types.RelationalRowsExpression = null,
};

pub const ArrayTransformValue = struct {
    field: []const u8,
    op: db_mod.types.TransformOpType,
    value_json: []const u8,
};

pub fn validateInsertSourceAssignmentExpressionType(
    type_context: expr_type.RowExpressionTypeContext,
    target_column: runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) !void {
    const expression_type = try type_context.rowExpressionOutputType(expression);
    const compatible = if (target_column.field_type == .json or target_column.field_type == .array)
        expression_type == target_column.field_type
    else
        expr_type.sqlExpressionTypesComparable(target_column.field_type, expression_type);
    if (!compatible) return error.UnsupportedSqlShape;
}

pub const AssignmentExpressionValidationOptions = struct {
    validate_json: bool = false,
};

pub fn validateMutationAssignmentExpressionType(
    type_context: expr_type.RowExpressionTypeContext,
    target_column: runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
    options: AssignmentExpressionValidationOptions,
) !void {
    if (expr_type.sqlExpressionIsInterval(expression)) return error.UnsupportedSqlShape;
    try validateInsertSourceAssignmentExpressionType(type_context, target_column, expression);
    if (target_column.field_type == .numeric) {
        try type_context.validateNumericRowExpression(expression);
    } else if (target_column.field_type == .datetime) {
        try type_context.validateNumericOrDatetimeRowExpression(expression);
    } else if (target_column.field_type == .keyword or target_column.field_type == .text or target_column.field_type == .link) {
        try type_context.validateTextRowExpression(expression);
    } else if (target_column.field_type == .boolean) {
        try type_context.validateBooleanRowExpression(expression);
    } else if (target_column.field_type == .json and options.validate_json) {
        try type_context.validateJsonRowExpression(expression);
    }
}

pub fn insertSourceSelectSourceCteSchema(
    tokens: []const Token,
    start: usize,
    end: usize,
    planned_ctes: []const relational_rows.RowsPlannedCte,
) !?runtime_schema.TableSchema {
    if (planned_ctes.len == 0) return null;
    const from_index = parser.findTopLevelKeywordTag(tokens[start..end], .from) orelse return null;
    var source_index = start + from_index + 1;
    _ = parser.matchKeywordTag(tokens, &source_index, .only);
    if (source_index >= end or tokens[source_index].kind != .identifier) return error.UnsupportedSqlShape;
    return relational_rows.rowsPlannedCteSchema(planned_ctes, tokens[source_index].text);
}

pub fn insertSourceAssignmentsFromSelectAlloc(
    alloc: std.mem.Allocator,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    target_columns: []const []const u8,
    source_query: db_mod.types.RelationalRowsQueryRequest,
    source_outputs: []const SelectOutputRef,
) ![]const db_mod.types.RelationalRowsExpressionAssignment {
    if (target_columns.len != source_outputs.len) return error.UnsupportedSqlShape;
    const assignments = try alloc.alloc(db_mod.types.RelationalRowsExpressionAssignment, target_columns.len);
    var initialized: usize = 0;
    errdefer {
        for (assignments[0..initialized]) |assignment| {
            alloc.free(@constCast(assignment.field));
            freeExpression(alloc, assignment.expression);
        }
        alloc.free(assignments);
    }
    for (target_columns, source_outputs) |target_name, output| {
        const target_column = binder.relationalColumnForField(target_schema, target_name, null) orelse return error.InvalidSqlCatalog;
        const expression = try insertSourceExpressionFromSelectOutputAlloc(alloc, source_schema, source_query, output);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try validateInsertSourceAssignmentExpressionType(type_context, target_column, expression);
        const target_field = try alloc.dupe(u8, target_column.path);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target_field);
        assignments[initialized] = .{
            .field = target_field,
            .expression = expression,
        };
        target_transferred = true;
        expression_transferred = true;
        initialized += 1;
    }
    return assignments;
}

pub fn insertSourceExpressionFromSelectOutputAlloc(
    alloc: std.mem.Allocator,
    source_schema: runtime_schema.TableSchema,
    source_query: db_mod.types.RelationalRowsQueryRequest,
    output: SelectOutputRef,
) !db_mod.types.RelationalRowsExpression {
    var expression = switch (output.kind) {
        .field => blk: {
            if (output.index >= source_query.select.len) return error.UnsupportedSqlShape;
            const source_column = binder.relationalColumnForField(source_schema, source_query.select[output.index], null) orelse return error.InvalidSqlCatalog;
            break :blk db_mod.types.RelationalRowsExpression{
                .kind = .field,
                .field = try alloc.dupe(u8, source_column.path),
                .field_source = .source,
            };
        },
        .json_extract => blk: {
            if (output.index >= source_query.json_extract.len) return error.UnsupportedSqlShape;
            break :blk try expr_projection.expressionFromJsonExtractProjectionAlloc(alloc, source_query.json_extract[output.index]);
        },
        .array_length => blk: {
            if (output.index >= source_query.array_length.len) return error.UnsupportedSqlShape;
            break :blk try expr_projection.expressionFromArrayLengthProjectionAlloc(alloc, source_query.array_length[output.index]);
        },
        .coalesce => blk: {
            if (output.index >= source_query.coalesce.len) return error.UnsupportedSqlShape;
            break :blk try expr_projection.expressionFromCoalesceProjectionAlloc(alloc, source_query.coalesce[output.index]);
        },
        .field_alias => blk: {
            if (output.index >= source_query.field_aliases.len) return error.UnsupportedSqlShape;
            const source_column = binder.relationalColumnForField(source_schema, source_query.field_aliases[output.index].field, null) orelse return error.InvalidSqlCatalog;
            break :blk db_mod.types.RelationalRowsExpression{
                .kind = .field,
                .field = try alloc.dupe(u8, source_column.path),
                .field_source = .source,
            };
        },
        .expression => blk: {
            if (output.index >= source_query.expressions.len) return error.UnsupportedSqlShape;
            break :blk try cloneExpressionAlloc(alloc, source_query.expressions[output.index].expression);
        },
    };
    errdefer freeExpression(alloc, expression);
    plan_mod.rewriteExpressionFieldsToSource(&expression);
    return expression;
}

pub fn clearInsertSourceQueryProjection(alloc: std.mem.Allocator, query: *db_mod.types.RelationalRowsQueryRequest) void {
    strings.freeStringSlice(alloc, query.select);
    freeJsonExtract(alloc, query.json_extract);
    freeArrayLengthProjections(alloc, query.array_length);
    freeCoalesceProjections(alloc, query.coalesce);
    freeFieldAliasProjections(alloc, query.field_aliases);
    freeExpressionProjections(alloc, query.expressions);
    query.select = &.{};
    query.json_extract = &.{};
    query.array_length = &.{};
    query.coalesce = &.{};
    query.field_aliases = &.{};
    query.expressions = &.{};
    query.select_all = true;
}

pub fn insertSourceOnConflictFromClauseAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    clause: ConflictClause,
) !db_mod.types.RelationalRowsOnConflict {
    const target = try insertSourceConflictTargetFromClauseAlloc(alloc, schema, clause.target);
    var target_transferred = false;
    errdefer if (!target_transferred) freeRowsConflictTargetValue(alloc, target);

    if (clause.action == .nothing) {
        target_transferred = true;
        return .{
            .target = target,
            .action = .nothing,
        };
    }

    const operations = try insertSourceConflictOperationsFromClauseAlloc(alloc, schema, clause);
    var operations_transferred = false;
    errdefer if (!operations_transferred) freeTransformOps(alloc, operations);

    const patch_expressions = try insertSourceConflictExpressionAssignmentsFromClauseAlloc(alloc, schema, clause.patch_expr);
    var patch_transferred = false;
    errdefer if (!patch_transferred) freeExpressionAssignments(alloc, patch_expressions);

    const increment_expressions = try insertSourceConflictExpressionAssignmentsFromClauseAlloc(alloc, schema, clause.increment_expr);
    var increment_transferred = false;
    errdefer if (!increment_transferred) freeExpressionAssignments(alloc, increment_expressions);

    const json_set_expressions = try insertSourceConflictJsonSetExpressionAssignmentsFromClauseAlloc(alloc, schema, clause.json_set);
    var json_set_transferred = false;
    errdefer if (!json_set_transferred) freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);

    const where_expression: ?db_mod.types.RelationalRowsExpressionCondition = if (clause.where_expression) |condition|
        try cloneExpressionConditionAlloc(alloc, condition)
    else
        null;
    var where_transferred = false;
    errdefer if (!where_transferred) if (where_expression) |condition| freeExpressionCondition(alloc, condition);

    const where_expressions = try cloneExpressionConditionsAlloc(alloc, clause.where_expressions);
    var where_expressions_transferred = false;
    errdefer if (!where_expressions_transferred) {
        freeExpressionConditions(alloc, where_expressions);
        if (where_expressions.len > 0) alloc.free(where_expressions);
    };

    const where_any = try cloneExpressionPredicateGroupsAlloc(alloc, clause.where_any);
    var where_any_transferred = false;
    errdefer if (!where_any_transferred) {
        freeExpressionPredicateGroups(alloc, where_any);
        if (where_any.len > 0) alloc.free(where_any);
    };

    const where_not = try cloneExpressionPredicateGroupsAlloc(alloc, clause.where_not);
    var where_not_transferred = false;
    errdefer if (!where_not_transferred) {
        freeExpressionPredicateGroups(alloc, where_not);
        if (where_not.len > 0) alloc.free(where_not);
    };

    target_transferred = true;
    operations_transferred = true;
    patch_transferred = true;
    increment_transferred = true;
    json_set_transferred = true;
    where_transferred = true;
    where_expressions_transferred = true;
    where_any_transferred = true;
    where_not_transferred = true;
    return .{
        .target = target,
        .action = .update,
        .operations = operations,
        .patch_expressions = patch_expressions,
        .increment_expressions = increment_expressions,
        .json_set_expressions = json_set_expressions,
        .where_expression = where_expression,
        .where_expressions = where_expressions,
        .where_any = where_any,
        .where_not = where_not,
    };
}

pub fn insertSourceConflictTargetFromClauseAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    target: ConflictTarget,
) !db_mod.types.RelationalRowsConflictTarget {
    return switch (target) {
        .any => .{ .kind = .any },
        .primary => .{ .kind = .primary },
        .unique => |unique| blk: {
            const constraint = binder.findUniqueConstraintByName(schema, unique.name) orelse return error.InvalidSqlCatalog;
            if (unique.where_json.len > 0 and constraint.where.len == 0) return error.UnsupportedSqlShape;
            if (unique.where_expressions.len > 0 and !expr_equal.relationalRowsExpressionConditionsEqual(constraint.where_expressions, unique.where_expressions)) return error.UnsupportedSqlShape;

            const name = try alloc.dupe(u8, unique.name);
            var name_transferred = false;
            errdefer if (!name_transferred) alloc.free(name);

            const predicates = try insertSourceUniquePredicatesFromConstraintAlloc(alloc, constraint.where);
            var predicates_transferred = false;
            errdefer if (!predicates_transferred) {
                freeRelationalChecks(alloc, predicates);
                if (predicates.len > 0) alloc.free(predicates);
            };

            const predicate_expressions = try cloneExpressionConditionsAlloc(alloc, constraint.where_expressions);
            var predicate_expressions_transferred = false;
            errdefer if (!predicate_expressions_transferred) {
                freeExpressionConditions(alloc, predicate_expressions);
                if (predicate_expressions.len > 0) alloc.free(predicate_expressions);
            };

            name_transferred = true;
            predicates_transferred = true;
            predicate_expressions_transferred = true;
            break :blk .{
                .kind = .unique,
                .unique_name = name,
                .unique_predicates = predicates,
                .unique_predicate_expressions = predicate_expressions,
            };
        },
    };
}

pub fn conflictTargetIdentityAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    insert_columns: []const []const u8,
    row: []const []const u8,
    target: ConflictTarget,
) ![]const u8 {
    return switch (target) {
        .any => return error.UnsupportedSqlShape,
        .primary => try conflictColumnIdentityAlloc(alloc, "primary", schema.primary_key.?.columns, insert_columns, row),
        .unique => |unique| blk: {
            const constraint = binder.findUniqueConstraintByName(schema, unique.name) orelse return error.InvalidSqlCatalog;
            break :blk try conflictUniqueConstraintIdentityAlloc(alloc, unique.name, schema, constraint, insert_columns, row);
        },
    };
}

pub fn conflictUniqueConstraintIdentityAlloc(
    alloc: std.mem.Allocator,
    label: []const u8,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
    insert_columns: []const []const u8,
    row: []const []const u8,
) ![]const u8 {
    const encoded_tuple = (try conflictUniqueConstraintTupleValueAlloc(alloc, schema, constraint, insert_columns, row)) orelse return error.UnsupportedSqlShape;
    defer alloc.free(encoded_tuple);
    return try std.fmt.allocPrint(alloc, "{f}:{f}", .{ std.json.fmt(label, .{}), std.json.fmt(encoded_tuple, .{}) });
}

fn conflictUniqueConstraintTupleValueAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
    insert_columns: []const []const u8,
    row: []const []const u8,
) !?[]u8 {
    if (constraint.columns.len == 0 and constraint.expressions.len == 0) return error.UnsupportedSqlShape;
    var selected_columns = try conflictUniqueConstraintSelectedColumnsAlloc(alloc, schema, constraint);
    defer selected_columns.deinit(alloc);
    const row_json = try conflictInsertedRowJsonAlloc(alloc, insert_columns, row);
    defer alloc.free(row_json);
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, row_json, selected_columns.items) catch return error.UnsupportedSqlShape;
    defer alloc.free(row_value);
    return db_mod.relational_store.uniqueConstraintTupleValueWithColumnsAlloc(alloc, row_value, constraint, selected_columns.items) catch return error.UnsupportedSqlShape;
}

fn conflictInsertedRowJsonAlloc(
    alloc: std.mem.Allocator,
    insert_columns: []const []const u8,
    row: []const []const u8,
) ![]const u8 {
    var row_object: std.Io.Writer.Allocating = .init(alloc);
    errdefer row_object.deinit();
    const writer = &row_object.writer;
    try writer.writeByte('{');
    var wrote = false;
    for (insert_columns, row) |column, value_json| {
        if (column.len == 0) return error.UnsupportedSqlShape;
        if (wrote) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(column, .{})});
        try writer.writeAll(value_json);
        wrote = true;
    }
    try writer.writeByte('}');
    return try row_object.toOwnedSlice();
}

const ConflictUniqueSelectedColumns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn);

fn conflictUniqueConstraintSelectedColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
) !ConflictUniqueSelectedColumns {
    var selected = ConflictUniqueSelectedColumns.empty;
    errdefer selected.deinit(alloc);
    for (constraint.columns) |column_name| {
        try appendConflictUniqueSelectedColumn(alloc, &selected, schema, column_name);
    }
    for (constraint.expressions) |expression| {
        try appendConflictUniqueExpressionColumns(alloc, &selected, schema, expression);
    }
    for (constraint.where) |predicate| {
        try appendConflictUniqueSelectedColumn(alloc, &selected, schema, predicate.field);
    }
    for (constraint.where_expressions) |condition| {
        try appendConflictUniqueExpressionConditionColumns(alloc, &selected, schema, condition);
    }
    return selected;
}

fn appendConflictUniqueSelectedColumn(
    alloc: std.mem.Allocator,
    selected: *ConflictUniqueSelectedColumns,
    schema: runtime_schema.TableSchema,
    field: []const u8,
) !void {
    if (conflictUniqueSelectedColumnsContain(selected.items, field)) return;
    const column = findRelationalColumnForConflictIdentity(schema.relational_columns, field) orelse return error.UnsupportedSqlShape;
    try selected.append(alloc, column);
}

fn appendConflictUniqueExpressionColumns(
    alloc: std.mem.Allocator,
    selected: *ConflictUniqueSelectedColumns,
    schema: runtime_schema.TableSchema,
    expression: runtime_schema.UniqueExpression,
) anyerror!void {
    switch (expression.op) {
        .lower, .upper, .md5 => try appendConflictUniqueSelectedColumn(alloc, selected, schema, expression.field),
        .expression => try appendConflictRowExpressionColumns(alloc, selected, schema, expression.expression orelse return error.UnsupportedSqlShape),
    }
}

fn appendConflictUniqueExpressionConditionColumns(
    alloc: std.mem.Allocator,
    selected: *ConflictUniqueSelectedColumns,
    schema: runtime_schema.TableSchema,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) anyerror!void {
    try appendConflictRowExpressionColumns(alloc, selected, schema, condition.lhs);
    for (condition.rhs) |expression| {
        try appendConflictRowExpressionColumns(alloc, selected, schema, expression);
    }
}

fn appendConflictRowExpressionColumns(
    alloc: std.mem.Allocator,
    selected: *ConflictUniqueSelectedColumns,
    schema: runtime_schema.TableSchema,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!void {
    if (expression.kind == .field) {
        if (expression.field_source != .row) return error.UnsupportedSqlShape;
        try appendConflictUniqueSelectedColumn(alloc, selected, schema, expression.field);
    }
    for (expression.operands) |operand| {
        try appendConflictRowExpressionColumns(alloc, selected, schema, operand);
    }
    for (expression.case_branches) |branch| {
        try appendConflictUniqueExpressionConditionColumns(alloc, selected, schema, branch.when);
        try appendConflictRowExpressionColumns(alloc, selected, schema, branch.then);
    }
    for (expression.case_else) |case_else| {
        try appendConflictRowExpressionColumns(alloc, selected, schema, case_else);
    }
}

fn conflictUniqueSelectedColumnsContain(columns: []const runtime_schema.RelationalColumn, field: []const u8) bool {
    return findRelationalColumnForConflictIdentity(columns, field) != null;
}

fn findRelationalColumnForConflictIdentity(columns: []const runtime_schema.RelationalColumn, field: []const u8) ?runtime_schema.RelationalColumn {
    for (columns) |column| {
        if (std.mem.eql(u8, column.path, field) or std.mem.eql(u8, column.name, field)) return column;
    }
    return null;
}

pub fn conflictColumnIdentityAlloc(
    alloc: std.mem.Allocator,
    label: []const u8,
    target_columns: []const []const u8,
    insert_columns: []const []const u8,
    row: []const []const u8,
) ![]const u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.print("{f}:[", .{std.json.fmt(label, .{})});
    for (target_columns, 0..) |target_column, i| {
        const value_json = expr_selector.conflictInsertedValueForColumn(insert_columns, row, target_column) orelse return error.UnsupportedSqlShape;
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(target_column, .{})});
        try writer.writeAll(value_json);
    }
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

pub fn conflictExpressionValueAlloc(
    alloc: std.mem.Allocator,
    expression: runtime_schema.UniqueExpression,
    insert_columns: []const []const u8,
    row: []const []const u8,
) ![]const u8 {
    if (expression.op == .expression) {
        const row_expression = expression.expression orelse return error.UnsupportedSqlShape;
        var row_object: std.Io.Writer.Allocating = .init(alloc);
        errdefer row_object.deinit();
        const writer = &row_object.writer;
        try writer.writeByte('{');
        var wrote = false;
        for (insert_columns, row) |column, value_json| {
            if (column.len == 0) return error.UnsupportedSqlShape;
            if (wrote) try writer.writeByte(',');
            try writer.print("{f}:", .{std.json.fmt(column, .{})});
            try writer.writeAll(value_json);
            wrote = true;
        }
        try writer.writeByte('}');
        const row_json = try row_object.toOwnedSlice();
        defer alloc.free(row_json);
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        return try relational_rows.expressionValueJsonAlloc(alloc, parsed.value, row_expression);
    }
    const value_json = expr_selector.conflictInsertedValueForColumn(insert_columns, row, expression.field) orelse return error.UnsupportedSqlShape;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    if (parsed.value != .string) return error.UnsupportedSqlShape;
    return switch (expression.op) {
        .lower => try std.ascii.allocLowerString(alloc, parsed.value.string),
        .upper => try std.ascii.allocUpperString(alloc, parsed.value.string),
        .md5 => try expr_text.md5HexTextAlloc(alloc, parsed.value.string),
        .expression => unreachable,
    };
}

pub fn writeUniqueExpressionIdentityJson(
    writer: *std.Io.Writer,
    expression: runtime_schema.UniqueExpression,
) !void {
    try writer.writeAll("{\"op\":");
    try writer.print("{f}", .{std.json.fmt(expr_type.uniqueExpressionOpToken(expression.op), .{})});
    switch (expression.op) {
        .lower, .upper, .md5 => try writer.print(",\"field\":{f}", .{std.json.fmt(expression.field, .{})}),
        .expression => {
            try writer.writeAll(",\"expression\":");
            try expr_type.writeRowExpressionJson(writer, expression.expression orelse return error.UnsupportedSqlShape);
        },
    }
    try writer.writeByte('}');
}

pub fn conflictExpressionIdentityAlloc(
    alloc: std.mem.Allocator,
    label: []const u8,
    expression: runtime_schema.UniqueExpression,
    insert_columns: []const []const u8,
    row: []const []const u8,
) ![]const u8 {
    const folded = try conflictExpressionValueAlloc(alloc, expression, insert_columns, row);
    defer alloc.free(folded);
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.print("{f}:[{{\"expression\":", .{std.json.fmt(label, .{})});
    try writeUniqueExpressionIdentityJson(writer, expression);
    try writer.print(",\"value\":{f}}}]", .{std.json.fmt(folded, .{})});
    return try out.toOwnedSlice();
}

pub fn conflictExcludedJsonObjectValueAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    source: []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
) ![]const u8 {
    _ = binder.relationalColumnForField(schema, source, null) orelse return error.InvalidSqlCatalog;
    const value_json = expr_selector.conflictInsertedValueForColumn(insert_columns, insert_values, source) orelse return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, value_json);
}

pub fn conflictExcludedValueJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    column: runtime_schema.RelationalColumn,
    source: []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
) ![]const u8 {
    const source_column = binder.relationalColumnForField(schema, source, null) orelse return error.InvalidSqlCatalog;
    if (source_column.field_type != column.field_type) return error.UnsupportedSqlShape;
    const value_json = expr_selector.conflictInsertedValueForColumn(insert_columns, insert_values, source) orelse return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, value_json);
}

pub fn conflictExcludedArrayElementValueJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    column: runtime_schema.RelationalColumn,
    source: []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
) ![]const u8 {
    const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
    const source_column = binder.relationalColumnForField(schema, source, null) orelse return error.InvalidSqlCatalog;
    if (source_column.field_type != item_type) return error.UnsupportedSqlShape;
    const insert_value = expr_selector.conflictInsertedValueForColumn(insert_columns, insert_values, source) orelse return error.UnsupportedSqlShape;
    try sql_value.validateSqlArrayElementValueJson(alloc, column, insert_value);
    return try alloc.dupe(u8, insert_value);
}

fn parseConflictCoalesceValueJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    try expr_token.parseCoalesceFunctionCallStart(tokens, pos);

    var selected: ?[]const u8 = null;
    errdefer if (selected) |value| alloc.free(value);
    var operands: usize = 0;
    while (true) {
        const value_json = try parseConflictCoalesceOperandJsonAlloc(alloc, tokens, pos, schema, params, column, insert_columns, insert_values, realtime_ns);
        var value_transferred = false;
        defer if (!value_transferred) alloc.free(value_json);
        operands += 1;
        if (selected == null and !std.mem.eql(u8, value_json, "null")) {
            selected = value_json;
            value_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    if (operands == 0) return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .rparen);

    if (selected) |value| {
        selected = null;
        return value;
    }
    return try alloc.dupe(u8, "null");
}

fn parseConflictJsonbBuildObjectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    try sql_value.parseJsonbBuildObjectFunctionCallStart(tokens, pos);
    if (parser.matchToken(tokens, pos, .rparen) != null) return try alloc.dupe(u8, "{}");

    var seen = std.StringHashMapUnmanaged(void).empty;
    defer seen.deinit(alloc);
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    while (true) {
        const key = try sql_value.parseJsonbBuildObjectKey(tokens, pos, params);
        const entry = try seen.getOrPut(alloc, key);
        if (entry.found_existing) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .comma);
        const value_json = try parseConflictJsonbBuildObjectValueAlloc(alloc, tokens, pos, schema, params, insert_columns, insert_values, realtime_ns);
        defer alloc.free(value_json);
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(key, .{})});
        try writer.writeAll(value_json);
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    try parser.expectToken(tokens, pos, .rparen);
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

pub fn parseConflictJsonbBuildObjectValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    if (sql_value.peekToJsonbFunctionCall(tokens, pos.*)) {
        try sql_value.parseToJsonbFunctionCallStart(tokens, pos);
        const value_json = try parseConflictJsonbBuildObjectValueAlloc(alloc, tokens, pos, schema, params, insert_columns, insert_values, realtime_ns);
        errdefer alloc.free(value_json);
        try parser.expectToken(tokens, pos, .rparen);
        return value_json;
    }
    if (pos.* < tokens.len and tokens[pos.*].kind == .identifier) {
        const token = tokens[pos.*];
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            pos.* += 1;
            return try conflictExcludedJsonObjectValueAlloc(alloc, schema, token.text["excluded.".len..], insert_columns, insert_values);
        }
    }
    return try sql_value.parseJsonValueAlloc(alloc, tokens, pos, params);
}

pub fn parseConflictCoalesceOperandJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    if (pos.* < tokens.len and tokens[pos.*].kind == .identifier) {
        const token = tokens[pos.*];
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            pos.* += 1;
            return try conflictExcludedValueJsonAlloc(alloc, schema, column, token.text["excluded.".len..], insert_columns, insert_values);
        }
    }
    return try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
}

pub fn parseConflictValueJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    if (sql_value.peekJsonbBuildObjectFunctionCall(tokens, pos.*)) {
        if (column.field_type != .json) return error.InvalidSqlCatalog;
        return try parseConflictJsonbBuildObjectAlloc(alloc, tokens, pos, schema, params, insert_columns, insert_values, realtime_ns);
    }
    if (expr_token.peekCoalesceFunctionCall(tokens, pos.*)) {
        return try parseConflictCoalesceValueJsonAlloc(alloc, tokens, pos, schema, params, column, insert_columns, insert_values, realtime_ns);
    }
    if (pos.* < tokens.len and tokens[pos.*].kind == .identifier) {
        const token = tokens[pos.*];
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            pos.* += 1;
            return try conflictExcludedValueJsonAlloc(alloc, schema, column, token.text["excluded.".len..], insert_columns, insert_values);
        }
    }
    return try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
}

pub fn parseConflictArrayElementValueJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    realtime_ns: u64,
) ![]const u8 {
    const item_type = column.array_item_type orelse return error.InvalidSqlCatalog;
    const element_column: runtime_schema.RelationalColumn = .{
        .name = column.name,
        .path = column.path,
        .field_type = item_type,
    };
    if (expr_token.peekCoalesceFunctionCall(tokens, pos.*)) {
        const value_json = try parseConflictCoalesceValueJsonAlloc(alloc, tokens, pos, schema, params, element_column, insert_columns, insert_values, realtime_ns);
        errdefer alloc.free(value_json);
        try sql_value.validateSqlArrayElementValueJson(alloc, column, value_json);
        return value_json;
    }
    if (pos.* < tokens.len and tokens[pos.*].kind == .identifier) {
        const token = tokens[pos.*];
        if (std.mem.startsWith(u8, token.text, "excluded.")) {
            pos.* += 1;
            return try conflictExcludedArrayElementValueJsonAlloc(alloc, schema, column, token.text["excluded.".len..], insert_columns, insert_values);
        }
    }
    const value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, pos, params);
    errdefer alloc.free(value_json);
    try sql_value.validateSqlArrayElementValueJson(alloc, column, value_json);
    return value_json;
}

pub fn parseJsonSetSqlValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    options: JsonSetSqlValueParserOptions,
) anyerror!JsonSetParsedValue {
    if (!sql_value.peekToJsonbFunctionCall(tokens, pos.*)) {
        return .{ .value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, pos, options.params) };
    }

    try sql_value.parseToJsonbFunctionCallStart(tokens, pos);
    if (grammar.peekStaticToJsonbValue(tokens, pos.*)) {
        const value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, pos, options.params);
        errdefer alloc.free(value_json);
        try parser.expectToken(tokens, pos, .rparen);
        return .{ .value_json = value_json };
    }

    const expression = if (options.insert_columns.len > 0)
        try parseConflictExpressionWithExpectedAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            options.schema,
            options.conflict_existing_qualifiers,
            column,
            options.insert_columns,
            null,
            options.type_context,
            options.defer_row_expression_field_validation,
            options.conflict_dispatch_options,
        )
    else
        try expr_row_parse.parseRowExpressionAlloc(
            alloc,
            tokens,
            pos,
            options.type_context,
            options.row_expression_hooks,
            options.arithmetic_hooks,
            options.variadic_hooks,
        );
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try parser.expectToken(tokens, pos, .rparen);
    expression_transferred = true;
    return .{ .expression = expression };
}

pub fn parseJoinedMutationJsonSetSqlValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    target_alias: []const u8,
    options: JoinedMutationJsonSetSqlValueParserOptions,
) anyerror!JsonSetParsedValue {
    if (!sql_value.peekToJsonbFunctionCall(tokens, pos.*)) {
        return .{ .value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, pos, options.params) };
    }

    try sql_value.parseToJsonbFunctionCallStart(tokens, pos);
    if (grammar.peekStaticToJsonbValue(tokens, pos.*)) {
        const value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, pos, options.params);
        errdefer alloc.free(value_json);
        try parser.expectToken(tokens, pos, .rparen);
        return .{ .value_json = value_json };
    }

    const target_qualifiers = [_][]const u8{target_alias};
    const source_qualifiers = [_][]const u8{options.pending_joined_source_alias orelse return error.UnsupportedSqlShape};
    const expression = try expr_row_parse.parseJoinedRowExpressionWithQualifiersAlloc(
        alloc,
        tokens,
        pos,
        target_qualifiers[0..],
        source_qualifiers[0..],
        options.row_expression_options,
    );
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    _ = column;
    try parser.expectToken(tokens, pos, .rparen);
    expression_transferred = true;
    return .{ .expression = expression };
}

fn jsonSetSqlValueOptionsWithInsertColumns(
    options: JsonSetSqlValueParserOptions,
    insert_columns: []const []const u8,
) JsonSetSqlValueParserOptions {
    var out = options;
    out.insert_columns = insert_columns;
    return out;
}

pub fn parseConflictIncrementAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    field: []const u8,
    column: runtime_schema.RelationalColumn,
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    options: ConflictIncrementParserOptions,
) !void {
    if (column.field_type != .numeric) return error.InvalidSqlCatalog;
    const source = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    defer alloc.free(source);
    if (!std.mem.eql(u8, source, field)) return error.UnsupportedSqlShape;
    const negated = if (parser.matchToken(tokens, pos, .plus) != null)
        false
    else if (parser.matchToken(tokens, pos, .minus) != null)
        true
    else
        return error.UnsupportedSqlShape;
    if (expr_token.peekCoalesceFunctionCall(tokens, pos.*)) {
        const expression = try parseConflictCoalesceExpressionAlloc(alloc, tokens, pos, column, options.insert_columns, column.field_type, options.assignment_options);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        const owned_field = try alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(owned_field);
        const final_expression = if (negated) try expr_build.buildUnaryNegativeExpressionAlloc(alloc, expression) else expression;
        var final_expression_transferred = !negated;
        errdefer if (!final_expression_transferred) freeExpression(alloc, final_expression);
        if (negated) expression_transferred = true;
        try increment_expr.append(alloc, .{
            .field = owned_field,
            .expression = final_expression,
        });
        field_transferred = true;
        final_expression_transferred = true;
        return;
    }

    const raw_value_json = try parseConflictValueJsonAlloc(
        alloc,
        tokens,
        pos,
        options.schema,
        options.params,
        column,
        options.insert_columns,
        options.insert_values,
        options.realtime_ns,
    );
    defer alloc.free(raw_value_json);
    const value_json = try normalizedIncrementJsonAlloc(alloc, raw_value_json, negated);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    const owned_field = try alloc.dupe(u8, field);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(owned_field);
    try increment.append(alloc, .{
        .field = owned_field,
        .value_json = value_json,
    });
    field_transferred = true;
    value_transferred = true;
}

pub fn parseIncrementAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const sql_value.SqlValue,
    field: []const u8,
    column: runtime_schema.RelationalColumn,
    realtime_ns: u64,
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
) !void {
    if (column.field_type != .numeric) return error.InvalidSqlCatalog;
    const source = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    defer alloc.free(source);
    if (!std.mem.eql(u8, source, field)) return error.UnsupportedSqlShape;
    const negated = if (parser.matchToken(tokens, pos, .plus) != null)
        false
    else if (parser.matchToken(tokens, pos, .minus) != null)
        true
    else
        return error.UnsupportedSqlShape;
    const raw_value_json = try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
    defer alloc.free(raw_value_json);
    const value_json = try normalizedIncrementJsonAlloc(alloc, raw_value_json, negated);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    const owned_field = try alloc.dupe(u8, field);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(owned_field);
    try increment.append(alloc, .{
        .field = owned_field,
        .value_json = value_json,
    });
    field_transferred = true;
    value_transferred = true;
}

pub fn parsePointWhereJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const sql_value.SqlValue,
    schema: runtime_schema.TableSchema,
    target_qualifiers: []const []const u8,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) ![]u8 {
    const primary_key = schema.primary_key orelse return error.InvalidSqlCatalog;
    var values = std.ArrayListUnmanaged(FieldJsonValue).empty;
    defer {
        freeFieldJsonValues(alloc, values.items);
        values.deinit(alloc);
    }

    while (true) {
        const parsed_field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        defer alloc.free(parsed_field);
        const field = try binder.normalizeTargetSelectorFieldAlloc(alloc, parsed_field, target_qualifiers);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
        const op_token_index = pos.*;
        const value_json = if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{ .allow_distinct = false })) |is_tail| blk: {
            if (is_tail.op != .is_null) return error.UnsupportedSqlShape;
            try expr_generated_validate.validateGeneratedIsTailPredicateIdentity(generated_expression_ast, tokens, op_token_index, is_tail);
            break :blk try alloc.dupe(u8, "null");
        } else blk: {
            try parser.expectToken(tokens, pos, .eq);
            try expr_generated_validate.validateGeneratedRelationalPredicateIdentity(generated_expression_ast, tokens, op_token_index, .eq);
            break :blk try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
        };
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        if (expr_selector.fieldValuesContain(values.items, field)) return error.UnsupportedSqlShape;
        try values.append(alloc, .{
            .field = field,
            .value_json = value_json,
        });
        field_transferred = true;
        value_transferred = true;
        if (!parser.matchKeywordTag(tokens, pos, .@"and")) break;
    }

    if (expr_selector.fieldValuesMatchColumns(values.items, primary_key.columns)) {
        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeAll("{\"primary\":");
        try expr_selector.writeFieldValuesObjectJson(writer, values.items, primary_key.columns);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    const unique_constraint = expr_selector.findUniqueConstraintByColumnSet(alloc, schema, values.items) orelse return error.UnsupportedSqlShape;

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.print("{{\"unique\":{{\"name\":{f},\"values\":", .{std.json.fmt(unique_constraint.name, .{})});
    try expr_selector.writeAllFieldValuesObjectJson(writer, values.items);
    try writer.writeAll("}}");
    return try out.toOwnedSlice();
}

fn pointSelectorTailComplete(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len) return true;
    if (tokens[pos].kind == .semicolon) return pos + 1 == tokens.len;
    return tokens[pos].matchesKeywordTag(.returning);
}

fn classifyParsedPointWhereAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    where_json: []const u8,
    schema: runtime_schema.TableSchema,
    resolver: ?relational_rows.UniqueSelectorResolver,
) !plan_mod.MutationSelectorKind {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, where_json, .{}) catch return error.UnsupportedSqlShape;
    defer parsed.deinit();
    const key = relational_rows.physicalPrimaryKeyFromWhereAlloc(alloc, table_name, schema, parsed.value, resolver, true) catch |err| switch (err) {
        error.UnsupportedRowsSelector => return .point,
        error.InvalidRowsRequest => return .source,
        else => return err,
    };
    if (key) |owned_key| alloc.free(owned_key);
    return .point;
}

pub fn classifyUpdateSelectorParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    resolver: ?relational_rows.UniqueSelectorResolver,
) !plan_mod.MutationSelectorKind {
    const tokens = parsed_sql.items();
    var pos: usize = 0;
    try parser.expectKeywordTag(tokens, &pos, .update);
    const target_table = try plan_mod.parseDmlTargetAliasAlloc(alloc, tokens, &pos);
    defer plan_mod.freeTableAlias(alloc, target_table);

    const where_index = parser.findTopLevelKeywordTagFromIndex(tokens, pos, .where) orelse return .source;
    pos = where_index + 1;
    const selector_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    const where_json = parsePointWhereJsonAlloc(alloc, tokens, &pos, params, schema, &selector_qualifiers, 0, null) catch |err| switch (err) {
        error.UnsupportedSqlShape => return .source,
        else => return err,
    };
    defer alloc.free(where_json);
    if (!pointSelectorTailComplete(tokens, pos)) return .source;
    return try classifyParsedPointWhereAlloc(alloc, target_table.name, where_json, schema, resolver);
}

pub fn classifyDeleteSelectorParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    resolver: ?relational_rows.UniqueSelectorResolver,
) !plan_mod.MutationSelectorKind {
    const tokens = parsed_sql.items();
    var pos: usize = 0;
    try parser.expectKeywordTag(tokens, &pos, .delete);
    try parser.expectKeywordTag(tokens, &pos, .from);
    const target_table = try plan_mod.parseDmlTargetAliasAlloc(alloc, tokens, &pos);
    defer plan_mod.freeTableAlias(alloc, target_table);

    const where_index = parser.findTopLevelKeywordTagFromIndex(tokens, pos, .where) orelse return .source;
    pos = where_index + 1;
    const selector_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    const where_json = parsePointWhereJsonAlloc(alloc, tokens, &pos, params, schema, &selector_qualifiers, 0, null) catch |err| switch (err) {
        error.UnsupportedSqlShape => return .source,
        else => return err,
    };
    defer alloc.free(where_json);
    if (!pointSelectorTailComplete(tokens, pos)) return .source;
    return try classifyParsedPointWhereAlloc(alloc, target_table.name, where_json, schema, resolver);
}

fn tableAliasFromGeneratedDmlTargetAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    target_range: generated_parser.GeneratedSqlTokenRange,
    target_alias_end: usize,
    target_alias_name_tokens: ?generated_parser.GeneratedSqlTokenRange,
) !plan_mod.TableAlias {
    if (target_range.start >= target_range.end or target_range.end > target_alias_end or target_alias_end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[target_range.start].kind != .identifier) return error.UnsupportedSqlShape;
    const name = try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[target_range.start].text);
    errdefer alloc.free(name);

    const alias = if (target_alias_name_tokens) |alias_range| blk: {
        if (alias_range.start >= alias_range.end or alias_range.end > target_alias_end) return error.UnsupportedSqlShape;
        if (alias_range.end != target_alias_end or alias_range.end != alias_range.start + 1) return error.UnsupportedSqlShape;
        if (tokens[alias_range.start].kind != .identifier) return error.UnsupportedSqlShape;
        break :blk try alloc.dupe(u8, tokens[alias_range.start].text);
    } else blk: {
        if (target_alias_end != target_range.end) return error.UnsupportedSqlShape;
        break :blk try alloc.dupe(u8, name);
    };
    errdefer alloc.free(alias);

    return .{ .name = name, .alias = alias };
}

fn generatedDmlTargetAliasEnd(
    tokens: []const Token,
    target_range: generated_parser.GeneratedSqlTokenRange,
    target_alias_tokens: ?generated_parser.GeneratedSqlTokenRange,
    target_alias_name_tokens: ?generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !usize {
    if (target_range.start >= target_range.end or target_range.end > end or end > tokens.len) return error.UnsupportedSqlShape;
    const alias = target_alias_tokens orelse {
        if (target_alias_name_tokens != null) return error.UnsupportedSqlShape;
        return target_range.end;
    };
    const alias_name = target_alias_name_tokens orelse return error.UnsupportedSqlShape;
    if (alias.start != target_range.end or alias.start >= alias.end or alias.end > end) return error.UnsupportedSqlShape;
    const expected_name = if (alias.end == target_range.end + 2 and
        tokens[target_range.end].matchesKeywordTag(.as) and
        tokens[target_range.end + 1].kind == .identifier)
    blk: {
        break :blk generated_parser.GeneratedSqlTokenRange{ .start = target_range.end + 1, .end = target_range.end + 2 };
    } else if (alias.end == target_range.end + 1 and
        tokens[target_range.end].kind == .identifier and
        !plan_mod.nextIsDmlTargetTailKeyword(tokens, target_range.end))
    blk: {
        break :blk alias;
    } else return error.UnsupportedSqlShape;
    if (alias_name.start != expected_name.start or alias_name.end != expected_name.end) return error.UnsupportedSqlShape;
    return alias.end;
}

fn generatedInsertSourceTargetAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?plan_mod.TableAlias {
    const ast = maybe_ast orelse return null;
    if (ast.kind != .insert_select) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast.*, end);
    if (start + 4 >= end or !tokens[start].matchesKeywordTag(.insert) or !tokens[start + 1].matchesKeywordTag(.into)) return error.UnsupportedSqlShape;
    if (pos.* != start + 2) return error.UnsupportedSqlShape;
    const target_start = try generatedInsertTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    const insert_columns = ast.insert_columns_tokens orelse return error.UnsupportedSqlShape;
    if (insert_columns.start != target_alias_end or insert_columns.start >= insert_columns.end or insert_columns.end > end) return error.UnsupportedSqlShape;
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    pos.* = target_alias_end;
    return target_table;
}

fn generatedMergeTargetAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?plan_mod.TableAlias {
    const ast = maybe_ast orelse return null;
    if (ast.kind != .merge) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast.*, end);
    if (start + 4 >= end or !tokens[start].matchesKeywordTag(.merge) or !tokens[start + 1].matchesKeywordTag(.into)) return error.UnsupportedSqlShape;
    if (pos.* != start + 2) return error.UnsupportedSqlShape;
    const target_start = generatedDmlOptionalOnlyTargetStart(tokens, start + 2, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedMergeTargetAliasEnd(tokens, ast.*, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    pos.* = target_alias_end;
    return target_table;
}

fn generatedMergeSourceAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?plan_mod.TableAlias {
    return try generatedJoinedDmlSourceAliasAlloc(alloc, tokens, pos, maybe_ast, .merge, .using);
}

fn generatedUpdateTargetAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?plan_mod.TableAlias {
    const ast = maybe_ast orelse return null;
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast.*, end);
    if (start >= end or !tokens[start].matchesKeywordTag(.update)) return error.UnsupportedSqlShape;
    if (pos.* != start + 1) return error.UnsupportedSqlShape;
    const target_start = try generatedUpdateTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const assignments_range = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments_range.start == 0 or assignments_range.start >= assignments_range.end or assignments_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[assignments_range.start - 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    _ = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, assignments_range.start - 1);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    pos.* = target_alias_end;
    return target_table;
}

fn generatedDeleteTargetAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?plan_mod.TableAlias {
    const ast = maybe_ast orelse return null;
    if (ast.kind != .delete) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast.*, end);
    if (start + 1 >= end or !tokens[start].matchesKeywordTag(.delete) or !tokens[start + 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    if (pos.* != start + 2) return error.UnsupportedSqlShape;
    const target_start = try generatedDeleteTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDeleteTargetAliasEnd(tokens, ast.*, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    pos.* = target_alias_end;
    return target_table;
}

fn generatedJoinedDmlSourceAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
    expected_kind: generated_parser.GeneratedSqlDmlKind,
    source_keyword: parser.TokenKeyword,
) !?plan_mod.TableAlias {
    const ast = maybe_ast orelse return null;
    if (ast.kind != expected_kind) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const source = ast.source_tokens orelse return error.UnsupportedSqlShape;
    if (source.start != pos.*) return error.UnsupportedSqlShape;
    if (source.start == 0 or source.start >= source.end or source.end > end) return error.UnsupportedSqlShape;
    if (!tokens[source.start - 1].matchesKeywordTag(source_keyword)) return error.UnsupportedSqlShape;
    const source_read = ast.source_read orelse return error.UnsupportedSqlShape;
    if (!std.meta.eql(source_read.source_tokens orelse return error.UnsupportedSqlShape, source)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodySingleSourceAlias(tokens, source_read);

    const source_table = source_read.source_table_tokens orelse return error.UnsupportedSqlShape;
    var table_start = source.start;
    if (tokens[table_start].matchesKeywordTag(.only)) table_start += 1;
    if (source_table.start != table_start or source_table.end != table_start + 1) return error.UnsupportedSqlShape;
    if (tokens[source_table.start].kind != .identifier) return error.UnsupportedSqlShape;

    const alias_end = try generatedDmlReadBodySingleSourceAliasEnd(
        tokens,
        source_table,
        source_read.source_alias_tokens,
        source_read.source_alias_name_tokens,
    );
    if (alias_end != source.end) return error.UnsupportedSqlShape;

    const name = try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[source_table.start].text);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    const alias = if (source_read.source_alias_name_tokens) |alias_name| alias: {
        if (alias_name.start >= alias_name.end or alias_name.end != alias_end or alias_name.end != alias_name.start + 1) return error.UnsupportedSqlShape;
        break :alias try alloc.dupe(u8, tokens[alias_name.start].text);
    } else try alloc.dupe(u8, name);
    var alias_transferred = false;
    errdefer if (!alias_transferred) alloc.free(alias);

    name_transferred = true;
    alias_transferred = true;
    pos.* = alias_end;
    return .{ .name = name, .alias = alias };
}

fn generatedDmlSemijoinSourceTableRange(
    tokens: []const Token,
    pos: usize,
    maybe_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?generated_parser.GeneratedSqlTokenRange {
    const ast = maybe_ast orelse return null;
    switch (ast.kind) {
        .update, .delete => {},
        else => return error.UnsupportedSqlShape,
    }
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const range = ast.semijoin_source_table_tokens orelse return error.UnsupportedSqlShape;
    if (range.start >= range.end or range.end > end) return error.UnsupportedSqlShape;
    const expected_start = if (pos < tokens.len and tokens[pos].matchesKeywordTag(.only)) pos + 1 else pos;
    if (range.start != expected_start or range.end != expected_start + 1) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .identifier) return error.UnsupportedSqlShape;
    return range;
}

fn validateGeneratedDmlSemijoinSourceTableAliasAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    source_table: plan_mod.TableAlias,
) !void {
    const name = try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[range.start].text);
    defer alloc.free(name);
    if (!std.mem.eql(u8, source_table.name, name)) return error.UnsupportedSqlShape;
}

fn generatedDmlSemijoinSubqueryExpression(
    tokens: []const Token,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !?*const generated_parser.GeneratedSqlExpressionAst {
    const expression = generated_expression_ast orelse return null;
    try generated_read_validate.validateGeneratedOptionalExpression(tokens, expression.tokens, expression.*);
    return switch (expression.kind) {
        .exists_subquery => blk: {
            if (expression.right_expression_kind != .subquery) return error.UnsupportedSqlShape;
            break :blk expression.right_expression orelse return error.UnsupportedSqlShape;
        },
        .in_list => blk: {
            if (expression.right_expression_kind != .subquery) return error.UnsupportedSqlShape;
            break :blk expression.right_expression orelse return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    };
}

fn generatedDmlSemijoinSubqueryWhereExpressionForClause(
    tokens: []const Token,
    where_keyword_index: usize,
    predicate_start: usize,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !?*const generated_parser.GeneratedSqlExpressionAst {
    const subquery = (try generatedDmlSemijoinSubqueryExpression(tokens, generated_expression_ast)) orelse return null;
    const where_range = subquery.subquery_where_tokens orelse return error.UnsupportedSqlShape;
    if (where_keyword_index >= tokens.len or !tokens[where_keyword_index].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
    if (where_range.start != predicate_start or where_range.start != where_keyword_index + 1) return error.UnsupportedSqlShape;
    const expression = subquery.subquery_where_expression orelse return error.UnsupportedSqlShape;
    if (subquery.subquery_where_expression_kind == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(expression.tokens orelse return error.UnsupportedSqlShape, where_range)) return error.UnsupportedSqlShape;
    return expression;
}

fn validateGeneratedDmlTargetAliasBoundary(
    tokens: []const Token,
    target_range: generated_parser.GeneratedSqlTokenRange,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
    expected_target_alias_end: usize,
) !usize {
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    if (target_alias_end != expected_target_alias_end) return error.UnsupportedSqlShape;
    return target_alias_end;
}

fn generatedUpdateTargetAliasEnd(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    target_range: generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !usize {
    const assignments_range = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments_range.start == 0 or assignments_range.start >= assignments_range.end or assignments_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[assignments_range.start - 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    _ = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, assignments_range.start - 1);
    return target_alias_end;
}

fn generatedDeleteTargetAliasEnd(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    target_range: generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !usize {
    const expected_target_alias_end = if (ast.source_tokens) |source_range| blk: {
        if (source_range.start == 0 or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[source_range.start - 1].matchesKeywordTag(.using)) return error.UnsupportedSqlShape;
        break :blk source_range.start - 1;
    } else if (ast.where_tokens) |where_range| blk: {
        if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
        break :blk where_range.start - 1;
    } else if (ast.returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0 or returning_range.start > returning_range.end or returning_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[returning_range.start - 1].matchesKeywordTag(.returning)) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else end;
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    _ = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, expected_target_alias_end);
    return target_alias_end;
}

fn generatedMergeTargetAliasEnd(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    target_range: generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !usize {
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    if (source_range.start == 0 or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[source_range.start - 1].matchesKeywordTag(.using)) return error.UnsupportedSqlShape;
    return try validateGeneratedDmlTargetAliasBoundary(tokens, target_range, ast, end, source_range.start - 1);
}

fn classifyGeneratedUpdateSelectorFromDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    resolver: ?relational_rows.UniqueSelectorResolver,
) !plan_mod.MutationSelectorKind {
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    if (ast.source_tokens != null) return .source;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    const target_start = try generatedUpdateTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedUpdateTargetAliasEnd(tokens, ast, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    defer plan_mod.freeTableAlias(alloc, target_table);

    const where_range = ast.where_tokens orelse return .source;
    if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
    const selector_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    var pos = where_range.start;
    const where_json = parsePointWhereJsonAlloc(alloc, tokens[0..where_range.end], &pos, params, schema, &selector_qualifiers, 0, null) catch |err| switch (err) {
        error.UnsupportedSqlShape => return .source,
        else => return err,
    };
    defer alloc.free(where_json);
    if (pos != where_range.end) return .source;
    return try classifyParsedPointWhereAlloc(alloc, target_table.name, where_json, schema, resolver);
}

fn classifyGeneratedDeleteSelectorFromDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    resolver: ?relational_rows.UniqueSelectorResolver,
) !plan_mod.MutationSelectorKind {
    if (ast.kind != .delete) return error.UnsupportedSqlShape;
    if (ast.source_tokens != null) return .source;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    const target_start = try generatedDeleteTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDeleteTargetAliasEnd(tokens, ast, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    defer plan_mod.freeTableAlias(alloc, target_table);

    const where_range = ast.where_tokens orelse return .source;
    if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
    const selector_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    var pos = where_range.start;
    const where_json = parsePointWhereJsonAlloc(alloc, tokens[0..where_range.end], &pos, params, schema, &selector_qualifiers, 0, null) catch |err| switch (err) {
        error.UnsupportedSqlShape => return .source,
        else => return err,
    };
    defer alloc.free(where_json);
    if (pos != where_range.end) return .source;
    return try classifyParsedPointWhereAlloc(alloc, target_table.name, where_json, schema, resolver);
}

pub fn parseConflictUpdateSetAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    conflict_existing_qualifiers: []const []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    hooks: ConflictUpdateSetAssignmentParserOptions,
) !void {
    if (parser.peekKind(tokens, pos.*, .lparen)) {
        return try parseConflictUpdateRowAssignmentAlloc(alloc, tokens, pos, schema, params, conflict_existing_qualifiers, insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update, hooks);
    }
    return try parseConflictUpdateAssignmentAlloc(alloc, tokens, pos, schema, params, conflict_existing_qualifiers, insert_columns, insert_values, patch, patch_expr, increment, increment_expr, json_set, array_update, hooks);
}

fn parseGeneratedConflictUpdateSetAssignmentsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    items: *const generated_parser.GeneratedSqlListAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    conflict_existing_qualifiers: []const []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    hooks: ConflictUpdateSetAssignmentParserOptions,
) !void {
    const first_tokens = items.first_tokens orelse return error.UnsupportedSqlShape;
    const last_tokens = items.last_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, .{ .start = first_tokens.start, .end = last_tokens.end }, items);
    if (pos.* != items.items[0].start) return error.UnsupportedSqlShape;
    for (items.items, 0..) |assignment, index| {
        if (assignment.start >= assignment.end or assignment.end > tokens.len) return error.UnsupportedSqlShape;
        pos.* = assignment.start;
        const use_generated_assignment_expression = try validateGeneratedDmlAssignmentExpressionMetadata(tokens, assignment, items.expressions[index]);
        var hooks_with_generated = hooks;
        hooks_with_generated.value.expression_options.assignment_options.generated_expression_ast = if (use_generated_assignment_expression) &items.expressions[index] else null;
        try parseConflictUpdateSetAssignmentAlloc(
            alloc,
            tokens[0..assignment.end],
            pos,
            schema,
            params,
            conflict_existing_qualifiers,
            insert_columns,
            insert_values,
            patch,
            patch_expr,
            increment,
            increment_expr,
            json_set,
            array_update,
            hooks_with_generated,
        );
        if (pos.* != assignment.end) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedUpdateAssignmentHookRange(
    tokens: []const Token,
    pos: usize,
    generated_dml_ast: ?*const generated_parser.GeneratedSqlDmlAst,
    generated_assignment_items: *const generated_parser.GeneratedSqlListAst,
) !generated_parser.GeneratedSqlTokenRange {
    const ast = generated_dml_ast orelse return error.UnsupportedSqlShape;
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    const assignments = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments.start != pos) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, assignments, generated_assignment_items);
    return assignments;
}

pub fn parseConflictClauseAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const sql_value.SqlValue,
    schema: runtime_schema.TableSchema,
    table_name: []const u8,
    conflict_existing_qualifiers: []const []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    type_context: expr_type.RowExpressionTypeContext,
    defer_row_expression_field_validation: bool,
    target_options: ConflictTargetParserOptions,
    assignment_hooks: ConflictUpdateSetAssignmentParserOptions,
    generated_assignment_items: ?*const generated_parser.GeneratedSqlListAst,
    generated_assignments_tokens: ?generated_parser.GeneratedSqlTokenRange,
    generated_action_tokens: ?generated_parser.GeneratedSqlTokenRange,
    generated_action_kind: ?generated_parser.GeneratedSqlConflictActionKind,
    condition_options: ConflictAssignmentExpressionParserOptions,
    dispatch_options: ConflictExpressionDispatchOptions,
) !ConflictClause {
    try parser.expectKeywordTag(tokens, pos, .conflict);
    if (generated_action_tokens != null and generated_action_kind == null) return error.UnsupportedSqlShape;
    if (generated_action_tokens == null and generated_action_kind != null) return error.UnsupportedSqlShape;
    if ((condition_options.generated_action_where_tokens != null or condition_options.generated_expression_ast != null) and
        generated_action_tokens == null)
    {
        return error.UnsupportedSqlShape;
    }
    if ((condition_options.generated_action_where_tokens == null) != (condition_options.generated_expression_ast == null)) {
        return error.UnsupportedSqlShape;
    }
    if ((generated_assignment_items != null or generated_assignments_tokens != null) and
        generated_action_tokens == null)
    {
        return error.UnsupportedSqlShape;
    }
    const target: ConflictTarget = blk: {
        if (generated_action_tokens != null and target_options.generated_target_tokens == null and parser.peekKeywordTag(tokens, pos.*, .do)) {
            const target_kind = target_options.generated_target_kind orelse return error.UnsupportedSqlShape;
            if (target_kind != .targetless) return error.UnsupportedSqlShape;
            const items = target_options.generated_target_items orelse return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(items);
            if (target_options.generated_where_tokens != null or target_options.generated_where_expression != null) return error.UnsupportedSqlShape;
            break :blk .any;
        }
        break :blk try parseConflictTargetAlloc(alloc, tokens, pos, schema, table_name, target_options);
    };
    errdefer freeConflictTarget(alloc, target);
    try parser.expectKeywordTag(tokens, pos, .do);

    const action_start = pos.*;
    if (parser.matchKeywordTag(tokens, pos, .nothing)) {
        if (generated_action_kind) |kind| {
            if (kind != .nothing) return error.UnsupportedSqlShape;
        }
        if (generated_action_tokens) |action| {
            if (action.start != action_start or action.end != pos.*) return error.UnsupportedSqlShape;
        }
        if (generated_assignment_items) |items| {
            try validateGeneratedDmlEmptyList(items);
        }
        if (generated_assignments_tokens != null) return error.UnsupportedSqlShape;
        if (condition_options.generated_action_where_tokens != null or condition_options.generated_expression_ast != null) return error.UnsupportedSqlShape;
        return .{
            .target = target,
            .action = .nothing,
        };
    }

    switch (target) {
        .any => return error.UnsupportedSqlShape,
        else => {},
    }
    try parser.expectKeywordTag(tokens, pos, .update);
    if (generated_action_kind) |kind| {
        if (kind != .update) return error.UnsupportedSqlShape;
    }
    try parser.expectKeywordTag(tokens, pos, .set);
    if ((generated_assignment_items == null) != (generated_assignments_tokens == null)) return error.UnsupportedSqlShape;
    if (generated_action_tokens) |action| {
        if (action.start != action_start or action.start + 2 > action.end) return error.UnsupportedSqlShape;
    }
    var patch = std.ArrayListUnmanaged(FieldJsonValue).empty;
    errdefer {
        freeFieldJsonValues(alloc, patch.items);
        patch.deinit(alloc);
    }
    var patch_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
    errdefer {
        freeFieldExpressionValues(alloc, patch_expr.items);
        patch_expr.deinit(alloc);
    }
    var increment = std.ArrayListUnmanaged(FieldJsonValue).empty;
    errdefer {
        freeFieldJsonValues(alloc, increment.items);
        increment.deinit(alloc);
    }
    var increment_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
    errdefer {
        freeFieldExpressionValues(alloc, increment_expr.items);
        increment_expr.deinit(alloc);
    }
    var json_set = std.ArrayListUnmanaged(JsonSetValue).empty;
    errdefer {
        freeJsonSetValues(alloc, json_set.items);
        json_set.deinit(alloc);
    }
    var array_update = std.ArrayListUnmanaged(ArrayTransformValue).empty;
    errdefer {
        freeArrayTransformValues(alloc, array_update.items);
        array_update.deinit(alloc);
    }
    var where_expression: ?db_mod.types.RelationalRowsExpressionCondition = null;
    errdefer if (where_expression) |condition| freeExpressionCondition(alloc, condition);
    var where_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, where_expressions.items);
        where_expressions.deinit(alloc);
    }
    var where_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, where_any.items);
        where_any.deinit(alloc);
    }
    var where_not = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, where_not.items);
        where_not.deinit(alloc);
    }
    const assignments_start = pos.*;
    if (generated_assignments_tokens) |assignments| {
        if (assignments.start != assignments_start or assignments.start >= assignments.end or assignments.end > tokens.len) return error.UnsupportedSqlShape;
    }
    if (generated_assignment_items) |items| {
        try parseGeneratedConflictUpdateSetAssignmentsAlloc(
            alloc,
            tokens,
            pos,
            items,
            schema,
            params,
            conflict_existing_qualifiers,
            insert_columns,
            insert_values,
            &patch,
            &patch_expr,
            &increment,
            &increment_expr,
            &json_set,
            &array_update,
            assignment_hooks,
        );
    } else {
        while (true) {
            try parseConflictUpdateSetAssignmentAlloc(
                alloc,
                tokens,
                pos,
                schema,
                params,
                conflict_existing_qualifiers,
                insert_columns,
                insert_values,
                &patch,
                &patch_expr,
                &increment,
                &increment_expr,
                &json_set,
                &array_update,
                assignment_hooks,
            );
            if (parser.matchToken(tokens, pos, .comma) == null) break;
        }
    }
    if (generated_assignments_tokens) |assignments| {
        if (pos.* != assignments.end) return error.UnsupportedSqlShape;
    }
    if (patch.items.len == 0 and patch_expr.items.len == 0 and increment.items.len == 0 and increment_expr.items.len == 0 and json_set.items.len == 0 and array_update.items.len == 0) return error.UnsupportedSqlShape;
    try validateSqlUpdateTargetPaths(schema, patch.items, patch_expr.items, increment.items, increment_expr.items, json_set.items, array_update.items);
    const generated_action_where_tokens = condition_options.generated_action_where_tokens;
    const action_where_keyword = pos.*;
    if (parser.matchKeywordTag(tokens, pos, .where)) {
        const scoped_tokens = if (generated_action_where_tokens) |where_tokens| blk: {
            if (where_tokens.start != action_where_keyword + 1 or where_tokens.start >= where_tokens.end or where_tokens.end > tokens.len) return error.UnsupportedSqlShape;
            break :blk tokens[0..where_tokens.end];
        } else tokens;
        try parseConflictActionWhereClause(
            alloc,
            scoped_tokens,
            pos,
            params,
            schema,
            conflict_existing_qualifiers,
            insert_columns,
            type_context,
            defer_row_expression_field_validation,
            &where_expression,
            &where_expressions,
            &where_any,
            &where_not,
            condition_options,
            dispatch_options,
        );
        if (generated_action_where_tokens) |where_tokens| {
            if (pos.* != where_tokens.end) return error.UnsupportedSqlShape;
        }
    } else if (generated_action_where_tokens != null) {
        return error.UnsupportedSqlShape;
    }
    if (generated_action_tokens) |action| {
        if (pos.* != action.end) return error.UnsupportedSqlShape;
    }

    return .{
        .target = target,
        .action = .update,
        .patch = try patch.toOwnedSlice(alloc),
        .patch_expr = try patch_expr.toOwnedSlice(alloc),
        .increment = try increment.toOwnedSlice(alloc),
        .increment_expr = try increment_expr.toOwnedSlice(alloc),
        .json_set = try json_set.toOwnedSlice(alloc),
        .array_update = try array_update.toOwnedSlice(alloc),
        .where_expression = where_expression,
        .where_expressions = try where_expressions.toOwnedSlice(alloc),
        .where_any = try where_any.toOwnedSlice(alloc),
        .where_not = try where_not.toOwnedSlice(alloc),
    };
}

pub fn parseConflictClauseWithContextAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: ConflictClauseParserOptions,
) !ConflictClause {
    const previous_context = options.context_hooks.get_context(options.context_hooks.ptr);
    var next_context = previous_context;
    next_context.conflict_existing_qualifiers = options.existing_qualifiers;
    next_context.joined_source_schema = options.joined_source_schema;
    options.context_hooks.set_context(options.context_hooks.ptr, next_context);
    defer options.context_hooks.set_context(options.context_hooks.ptr, previous_context);

    const type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr);
    const assignment_hooks = conflictUpdateSetAssignmentOptionsWithExistingQualifiers(options.assignment_hooks, options.existing_qualifiers);
    const condition_options = conflictAssignmentExpressionOptionsWithExistingQualifiers(options.condition_options, options.existing_qualifiers);
    const dispatch_options = conflictDispatchOptionsWithExistingQualifiers(options.dispatch_options, options.existing_qualifiers);
    return try parseConflictClauseAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        options.schema,
        options.table_name,
        options.existing_qualifiers,
        options.insert_columns,
        options.insert_values,
        type_context,
        options.defer_row_expression_field_validation,
        options.target_options,
        assignment_hooks,
        options.generated_assignment_items,
        options.generated_assignments_tokens,
        options.generated_action_tokens,
        options.generated_action_kind,
        condition_options,
        dispatch_options,
    );
}

fn conflictAssignmentExpressionOptionsWithExistingQualifiers(
    options: ConflictAssignmentExpressionParserOptions,
    conflict_existing_qualifiers: []const []const u8,
) ConflictAssignmentExpressionParserOptions {
    var out = options;
    out.conflict_existing_qualifiers = conflict_existing_qualifiers;
    out.dispatch_options = conflictDispatchOptionsWithExistingQualifiers(out.dispatch_options, conflict_existing_qualifiers);
    return out;
}

fn conflictUpdateSetAssignmentOptionsWithExistingQualifiers(
    hooks: ConflictUpdateSetAssignmentParserOptions,
    conflict_existing_qualifiers: []const []const u8,
) ConflictUpdateSetAssignmentParserOptions {
    var out = hooks;
    out.value.json_set.conflict_existing_qualifiers = conflict_existing_qualifiers;
    out.value.json_set.conflict_dispatch_options = conflictDispatchOptionsWithExistingQualifiers(
        out.value.json_set.conflict_dispatch_options,
        conflict_existing_qualifiers,
    );
    out.value.expression_options.assignment_options = conflictAssignmentExpressionOptionsWithExistingQualifiers(
        out.value.expression_options.assignment_options,
        conflict_existing_qualifiers,
    );
    return out;
}

fn conflictDispatchOptionsWithExistingQualifiers(
    hooks: ConflictExpressionDispatchOptions,
    conflict_existing_qualifiers: []const []const u8,
) ConflictExpressionDispatchOptions {
    var out = hooks;
    out.array_length.conflict_existing_qualifiers = conflict_existing_qualifiers;
    return out;
}

fn parseConflictUpdateRowAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    conflict_existing_qualifiers: []const []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    hooks: ConflictUpdateSetAssignmentParserOptions,
) !void {
    try parser.expectToken(tokens, pos, .lparen);
    var fields = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (fields.items) |field| {
            if (field.len != 0) alloc.free(field);
        }
        fields.deinit(alloc);
    }
    while (true) {
        const field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        try fields.append(alloc, field);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    if (fields.items.len == 0) return error.UnsupportedSqlShape;
    try grammar.validateSqlIdentifierListUnique(fields.items);
    try parser.expectToken(tokens, pos, .rparen);
    try parser.expectToken(tokens, pos, .eq);
    try expectConflictRowAssignmentRhsStart(tokens, pos);
    for (fields.items, 0..) |field, i| {
        const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
        try notePrimaryKeyAssignment(schema, field, hooks.primary_key_assignment);
        var field_transferred = false;
        try parseConflictUpdateAssignmentValueAlloc(
            alloc,
            tokens,
            pos,
            schema,
            params,
            conflict_existing_qualifiers,
            field,
            column,
            patch,
            patch_expr,
            increment,
            increment_expr,
            json_set,
            array_update,
            &field_transferred,
            .{
                .schema = hooks.value.schema,
                .params = hooks.value.params,
                .insert_columns = insert_columns,
                .insert_values = insert_values,
                .realtime_ns = hooks.value.realtime_ns,
                .json_set = jsonSetSqlValueOptionsWithInsertColumns(hooks.value.json_set, insert_columns),
                .expression_options = hooks.value.expression_options,
            },
        );
        if (field_transferred) fields.items[i] = "";
        if (i + 1 < fields.items.len) {
            try parser.expectToken(tokens, pos, .comma);
        }
    }
    try parser.expectToken(tokens, pos, .rparen);
}

fn expectConflictRowAssignmentRhsStart(tokens: []const Token, pos: *usize) !void {
    _ = parser.matchKeywordTag(tokens, pos, .row);
    try parser.expectToken(tokens, pos, .lparen);
}

fn parseConflictUpdateAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    conflict_existing_qualifiers: []const []const u8,
    insert_columns: []const []const u8,
    insert_values: []const []const u8,
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    hooks: ConflictUpdateSetAssignmentParserOptions,
) !void {
    const field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    var field_transferred = false;
    defer if (!field_transferred) alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    try notePrimaryKeyAssignment(schema, field, hooks.primary_key_assignment);
    try parser.expectToken(tokens, pos, .eq);
    parseConflictUpdateAssignmentValueAlloc(
        alloc,
        tokens,
        pos,
        schema,
        params,
        conflict_existing_qualifiers,
        field,
        column,
        patch,
        patch_expr,
        increment,
        increment_expr,
        json_set,
        array_update,
        &field_transferred,
        .{
            .schema = hooks.value.schema,
            .params = hooks.value.params,
            .insert_columns = insert_columns,
            .insert_values = insert_values,
            .realtime_ns = hooks.value.realtime_ns,
            .json_set = jsonSetSqlValueOptionsWithInsertColumns(hooks.value.json_set, insert_columns),
            .expression_options = hooks.value.expression_options,
        },
    ) catch |err| {
        return err;
    };
}

fn notePrimaryKeyAssignment(
    schema: runtime_schema.TableSchema,
    field: []const u8,
    policy: PrimaryKeyAssignmentPolicy,
) !void {
    const primary_key = schema.primary_key orelse return error.InvalidSqlCatalog;
    if (!binder.primaryKeyContains(primary_key, field)) return;
    switch (policy) {
        .none => {},
        .reject => return error.UnsupportedSqlShape,
        .mark_rewrite => |rewrite_identity| rewrite_identity.* = true,
        .allow_and_mark => |state| {
            if (!state.allow) return error.UnsupportedSqlShape;
            state.saw.* = true;
        },
    }
}

pub fn parseConflictUpdateAssignmentValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    conflict_existing_qualifiers: []const []const u8,
    field: []const u8,
    column: runtime_schema.RelationalColumn,
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    increment: *std.ArrayListUnmanaged(FieldJsonValue),
    increment_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    array_update: *std.ArrayListUnmanaged(ArrayTransformValue),
    field_transferred: *bool,
    hooks: ConflictUpdateAssignmentValueParserOptions,
) !void {
    if (parser.matchKeywordTag(tokens, pos, .jsonb_set)) {
        if (column.field_type != .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const json_field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        defer alloc.free(json_field);
        if (!std.mem.eql(u8, json_field, field)) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .comma);
        const path = try sql_value.parsePostgresJsonPathAlloc(alloc, tokens, pos, params);
        var path_transferred = false;
        errdefer if (!path_transferred) strings.freeStringSlice(alloc, path);
        try parser.expectToken(tokens, pos, .comma);
        const value = try parseJsonSetSqlValueAlloc(alloc, tokens, pos, column, hooks.json_set);
        var value_transferred = false;
        errdefer if (!value_transferred) freeJsonSetParsedValue(alloc, value);
        if (parser.matchToken(tokens, pos, .comma) != null) {
            if (!parser.matchKeywordTag(tokens, pos, .true) and !parser.matchKeywordTag(tokens, pos, .false)) return error.UnsupportedSqlShape;
        }
        try parser.expectToken(tokens, pos, .rparen);
        try json_set.append(alloc, .{
            .field = field,
            .path = path,
            .value_json = value.value_json,
            .expression = value.expression,
        });
        field_transferred.* = true;
        path_transferred = true;
        value_transferred = true;
        return;
    }

    if (grammar.peekArrayTransformSelfAssignment(tokens, pos.*, field)) {
        const op = grammar.matchArrayTransformUpdateOp(tokens, pos) orelse unreachable;
        if (column.field_type != .array) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const array_field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        defer alloc.free(array_field);
        if (!std.mem.eql(u8, array_field, field)) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .comma);
        const value_json = try parseConflictArrayElementValueJsonAlloc(
            alloc,
            tokens,
            pos,
            hooks.schema,
            hooks.params,
            column,
            hooks.insert_columns,
            hooks.insert_values,
            hooks.realtime_ns,
        );
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        try parser.expectToken(tokens, pos, .rparen);
        try array_update.append(alloc, .{
            .field = field,
            .op = op,
            .value_json = value_json,
        });
        field_transferred.* = true;
        value_transferred = true;
        return;
    }

    if (column.field_type == .json and pos.* + 1 < tokens.len and tokens[pos.*].kind == .identifier and tokens[pos.* + 1].kind == .pipe_concat) {
        const json_field_token = tokens[pos.*];
        pos.* += 1;
        if (!std.mem.eql(u8, json_field_token.text, field)) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .pipe_concat);
        const object_json = try sql_value.parseRequiredJsonDocumentValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(object_json);
        try appendJsonObjectConcatSetValuesAlloc(alloc, field, object_json, json_set);
        return;
    }

    if (expr_operator.peekConflictExistingFieldIncrement(tokens, pos.*, field, column)) {
        try parseConflictIncrementAssignmentAlloc(alloc, tokens, pos, field, column, increment, increment_expr, .{
            .schema = hooks.schema,
            .params = hooks.params,
            .insert_columns = hooks.insert_columns,
            .insert_values = hooks.insert_values,
            .realtime_ns = hooks.realtime_ns,
            .assignment_options = hooks.expression_options.assignment_options,
        });
        return;
    }

    if (column.field_type == .boolean and canParseConflictBooleanAssignmentExpression(alloc, tokens, pos.*, schema, conflict_existing_qualifiers, hooks.insert_columns)) {
        const expression = try parseConflictBooleanExpressionAlloc(alloc, tokens, pos, column, hooks.insert_columns, hooks.expression_options.type_context, hooks.expression_options.assignment_options);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try patch_expr.append(alloc, .{
            .field = field,
            .expression = expression,
        });
        field_transferred.* = true;
        expression_transferred = true;
        return;
    }

    if (canParseConflictAssignmentExpression(alloc, tokens, pos.*, schema, conflict_existing_qualifiers, hooks.insert_columns)) {
        const expression = try parseConflictAssignmentExpressionAlloc(alloc, tokens, pos, column, hooks.insert_columns, hooks.expression_options.assignment_options);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try patch_expr.append(alloc, .{
            .field = field,
            .expression = expression,
        });
        field_transferred.* = true;
        expression_transferred = true;
        return;
    }

    const rhs_start = pos.*;
    const value_json = try parseConflictValueJsonAlloc(
        alloc,
        tokens,
        pos,
        hooks.schema,
        hooks.params,
        column,
        hooks.insert_columns,
        hooks.insert_values,
        hooks.realtime_ns,
    );
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    try validateGeneratedDmlAssignmentRhsMetadata(tokens, rhs_start, pos.*, hooks.expression_options.assignment_options.generated_expression_ast);
    try patch.append(alloc, .{
        .field = field,
        .value_json = value_json,
    });
    field_transferred.* = true;
    value_transferred = true;
}

pub fn parseJoinedMutationAssignmentValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    target: []const u8,
    target_column: runtime_schema.RelationalColumn,
    target_alias: []const u8,
    pending_joined_source_alias: ?[]const u8,
    source_assignments: *std.ArrayListUnmanaged(JoinedMutationSourceAssignment),
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    target_transferred: *bool,
    options: JoinedMutationAssignmentValueParserOptions,
) !void {
    if (parser.matchKeywordTag(tokens, pos, .jsonb_set)) {
        if (target_column.field_type != .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const json_field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        defer alloc.free(json_field);
        if (!(try binder.joinedMutationTargetFieldMatches(alloc, json_field, target_alias, target))) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .comma);
        const path = try sql_value.parsePostgresJsonPathAlloc(alloc, tokens, pos, params);
        var path_transferred = false;
        errdefer if (!path_transferred) strings.freeStringSlice(alloc, path);
        try parser.expectToken(tokens, pos, .comma);
        var json_set_options = options.json_set;
        json_set_options.pending_joined_source_alias = pending_joined_source_alias;
        const value = try parseJoinedMutationJsonSetSqlValueAlloc(alloc, tokens, pos, target_column, target_alias, json_set_options);
        var value_transferred = false;
        errdefer if (!value_transferred) freeJsonSetParsedValue(alloc, value);
        if (parser.matchToken(tokens, pos, .comma) != null) {
            if (!parser.matchKeywordTag(tokens, pos, .true) and !parser.matchKeywordTag(tokens, pos, .false)) return error.UnsupportedSqlShape;
        }
        try parser.expectToken(tokens, pos, .rparen);
        try json_set.append(alloc, .{
            .field = target,
            .path = path,
            .value_json = value.value_json,
            .expression = value.expression,
        });
        target_transferred.* = true;
        path_transferred = true;
        value_transferred = true;
        return;
    }

    if (target_column.field_type == .json and pos.* + 1 < tokens.len and tokens[pos.*].kind == .identifier and tokens[pos.* + 1].kind == .pipe_concat) {
        const json_field = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        defer alloc.free(json_field);
        if (!(try binder.joinedMutationTargetFieldMatches(alloc, json_field, target_alias, target))) return error.UnsupportedSqlShape;
        try parser.expectToken(tokens, pos, .pipe_concat);
        const object_json = try sql_value.parseRequiredJsonDocumentValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(object_json);
        try appendJsonObjectConcatSetValuesAlloc(alloc, target, object_json, json_set);
        return;
    }

    if (target_column.field_type == .boolean and canParseJoinedBooleanAssignmentExpression(tokens, pos.*, schema, joined_source_schema, pending_joined_source_alias, target_alias)) {
        var assignment_expression_options = options.assignment_expression;
        assignment_expression_options.pending_joined_source_alias = pending_joined_source_alias;
        const expression = try parseJoinedMutationBooleanAssignmentExpressionAlloc(alloc, tokens, pos, target_alias, assignment_expression_options.type_context, assignment_expression_options);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try patch_expr.append(alloc, .{
            .field = target,
            .expression = expression,
        });
        target_transferred.* = true;
        expression_transferred = true;
        return;
    }

    if (canParseJoinedAssignmentExpression(tokens, pos.*, schema, joined_source_schema, target_alias)) {
        var assignment_expression_options = options.assignment_expression;
        assignment_expression_options.pending_joined_source_alias = pending_joined_source_alias;
        const expression = try parseJoinedMutationAssignmentExpressionAlloc(alloc, tokens, pos, target_column, target_alias, assignment_expression_options.type_context, assignment_expression_options);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try patch_expr.append(alloc, .{
            .field = target,
            .expression = expression,
        });
        target_transferred.* = true;
        expression_transferred = true;
        return;
    }

    if (pos.* < tokens.len and tokens[pos.*].kind == .identifier and expr_parse.identifierContainsQualifier(tokens[pos.*].text)) {
        const rhs_start = pos.*;
        const source = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
        defer plan_mod.freeQualifiedField(alloc, source);
        if (std.mem.eql(u8, source.qualifier, target_alias)) return error.UnsupportedSqlShape;
        const source_column = binder.relationalColumnForField(joined_source_schema orelse schema, source.field, null) orelse return error.InvalidSqlCatalog;
        if (source_column.field_type != target_column.field_type) return error.UnsupportedSqlShape;
        try validateGeneratedDmlAssignmentRhsMetadata(tokens, rhs_start, pos.*, options.assignment_expression.row_expression_options.generated_expression_ast);
        const field = try alloc.dupe(u8, target);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        const source_qualifier = try alloc.dupe(u8, source.qualifier);
        var source_qualifier_transferred = false;
        errdefer if (!source_qualifier_transferred) alloc.free(source_qualifier);
        const source_field = try alloc.dupe(u8, source.field);
        var source_field_transferred = false;
        errdefer if (!source_field_transferred) alloc.free(source_field);
        try source_assignments.append(alloc, .{
            .field = field,
            .source_qualifier = source_qualifier,
            .source_field = source_field,
        });
        field_transferred = true;
        source_qualifier_transferred = true;
        source_field_transferred = true;
        return;
    }

    const rhs_start = pos.*;
    const value_json = try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, target_column, realtime_ns);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    try validateGeneratedDmlAssignmentRhsMetadata(tokens, rhs_start, pos.*, options.assignment_expression.row_expression_options.generated_expression_ast);
    try patch.append(alloc, .{
        .field = target,
        .value_json = value_json,
    });
    target_transferred.* = true;
    value_transferred = true;
}

pub fn parseJoinedMutationSetAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    target_alias: []const u8,
    pending_joined_source_alias: ?[]const u8,
    source_assignments: *std.ArrayListUnmanaged(JoinedMutationSourceAssignment),
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    saw_primary_key_assignment: *bool,
    options: JoinedMutationAssignmentValueParserOptions,
) !void {
    if (parser.peekKind(tokens, pos.*, .lparen)) {
        return try parseJoinedMutationRowAssignmentAlloc(
            alloc,
            tokens,
            pos,
            schema,
            joined_source_schema,
            params,
            realtime_ns,
            target_alias,
            pending_joined_source_alias,
            source_assignments,
            patch,
            patch_expr,
            json_set,
            saw_primary_key_assignment,
            options,
        );
    }
    return try parseJoinedMutationScalarAssignmentAlloc(
        alloc,
        tokens,
        pos,
        schema,
        joined_source_schema,
        params,
        realtime_ns,
        target_alias,
        pending_joined_source_alias,
        source_assignments,
        patch,
        patch_expr,
        json_set,
        saw_primary_key_assignment,
        options,
    );
}

fn parseGeneratedJoinedMutationSetAssignmentsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    items: *const generated_parser.GeneratedSqlListAst,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    target_alias: []const u8,
    pending_joined_source_alias: ?[]const u8,
    source_assignments: *std.ArrayListUnmanaged(JoinedMutationSourceAssignment),
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    saw_primary_key_assignment: *bool,
    options: JoinedMutationAssignmentValueParserOptions,
) !void {
    const first_tokens = items.first_tokens orelse return error.UnsupportedSqlShape;
    const last_tokens = items.last_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, .{ .start = first_tokens.start, .end = last_tokens.end }, items);
    if (pos.* != items.items[0].start) return error.UnsupportedSqlShape;
    for (items.items, 0..) |assignment, index| {
        if (assignment.start >= assignment.end or assignment.end > tokens.len) return error.UnsupportedSqlShape;
        pos.* = assignment.start;
        const use_generated_assignment_expression = try validateGeneratedDmlAssignmentExpressionMetadata(tokens, assignment, items.expressions[index]);
        var options_with_generated = options;
        options_with_generated.assignment_expression.row_expression_options.generated_expression_ast = if (use_generated_assignment_expression) &items.expressions[index] else null;
        options_with_generated.assignment_expression.row_expression_options.require_exact_generated_expression = use_generated_assignment_expression;
        options_with_generated.assignment_expression.boolean_expression_options.generated_expression_ast = if (use_generated_assignment_expression) &items.expressions[index] else null;
        options_with_generated.assignment_expression.boolean_expression_options.require_exact_generated_expression = use_generated_assignment_expression;
        try parseJoinedMutationSetAssignmentAlloc(
            alloc,
            tokens[0..assignment.end],
            pos,
            schema,
            joined_source_schema,
            params,
            realtime_ns,
            target_alias,
            pending_joined_source_alias,
            source_assignments,
            patch,
            patch_expr,
            json_set,
            saw_primary_key_assignment,
            options_with_generated,
        );
        if (pos.* != assignment.end) return error.UnsupportedSqlShape;
    }
}

fn parseJoinedMutationRowAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    target_alias: []const u8,
    pending_joined_source_alias: ?[]const u8,
    source_assignments: *std.ArrayListUnmanaged(JoinedMutationSourceAssignment),
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    saw_primary_key_assignment: *bool,
    options: JoinedMutationAssignmentValueParserOptions,
) !void {
    try parser.expectToken(tokens, pos, .lparen);
    var targets = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (targets.items) |target| {
            if (target.len != 0) alloc.free(target);
        }
        targets.deinit(alloc);
    }
    while (true) {
        const target = try parseJoinedMutationTargetFieldAlloc(alloc, tokens, pos, target_alias);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);
        try targets.append(alloc, target);
        target_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    if (targets.items.len == 0) return error.UnsupportedSqlShape;
    try grammar.validateSqlIdentifierListUnique(targets.items);
    try parser.expectToken(tokens, pos, .rparen);
    try parser.expectToken(tokens, pos, .eq);
    _ = parser.matchKeywordTag(tokens, pos, .row);
    try parser.expectToken(tokens, pos, .lparen);

    const primary_key = schema.primary_key orelse return error.InvalidSqlCatalog;
    for (targets.items, 0..) |target, i| {
        const target_column = binder.relationalColumnForField(schema, target, null) orelse return error.InvalidSqlCatalog;
        if (binder.primaryKeyContains(primary_key, target)) saw_primary_key_assignment.* = true;
        var target_transferred = false;
        try parseJoinedMutationAssignmentValueAlloc(
            alloc,
            tokens,
            pos,
            schema,
            joined_source_schema,
            params,
            realtime_ns,
            target,
            target_column,
            target_alias,
            pending_joined_source_alias,
            source_assignments,
            patch,
            patch_expr,
            json_set,
            &target_transferred,
            options,
        );
        if (target_transferred) targets.items[i] = "";
        if (i + 1 < targets.items.len) {
            try parser.expectToken(tokens, pos, .comma);
        }
    }
    try parser.expectToken(tokens, pos, .rparen);
}

fn parseJoinedMutationScalarAssignmentAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    target_alias: []const u8,
    pending_joined_source_alias: ?[]const u8,
    source_assignments: *std.ArrayListUnmanaged(JoinedMutationSourceAssignment),
    patch: *std.ArrayListUnmanaged(FieldJsonValue),
    patch_expr: *std.ArrayListUnmanaged(FieldExpressionValue),
    json_set: *std.ArrayListUnmanaged(JsonSetValue),
    saw_primary_key_assignment: *bool,
    options: JoinedMutationAssignmentValueParserOptions,
) !void {
    const target = try parseJoinedMutationTargetFieldAlloc(alloc, tokens, pos, target_alias);
    var target_transferred = false;
    defer if (!target_transferred) alloc.free(target);
    const target_column = binder.relationalColumnForField(schema, target, null) orelse return error.InvalidSqlCatalog;
    const primary_key = schema.primary_key orelse return error.InvalidSqlCatalog;
    if (binder.primaryKeyContains(primary_key, target)) saw_primary_key_assignment.* = true;
    try parser.expectToken(tokens, pos, .eq);
    try parseJoinedMutationAssignmentValueAlloc(
        alloc,
        tokens,
        pos,
        schema,
        joined_source_schema,
        params,
        realtime_ns,
        target,
        target_column,
        target_alias,
        pending_joined_source_alias,
        source_assignments,
        patch,
        patch_expr,
        json_set,
        &target_transferred,
        options,
    );
}

pub fn parseMergeTargetFieldOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    target_table: TableAlias,
) ![]const u8 {
    const identifier = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    errdefer alloc.free(identifier);
    if (std.mem.indexOfScalar(u8, identifier, '.')) |dot| {
        if (dot == 0 or dot + 1 >= identifier.len) return error.UnsupportedSqlShape;
        const qualifier = identifier[0..dot];
        if (!grammar.rowClaimTargetAllowed(alloc, qualifier, &.{ target_table.name, target_table.alias })) return error.UnsupportedSqlShape;
        const field = try alloc.dupe(u8, identifier[dot + 1 ..]);
        alloc.free(identifier);
        return field;
    }
    return identifier;
}

pub fn parseMergeQualifiedSourceMappingAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    target_table: TableAlias,
    source_table: TableAlias,
) !MergeFieldMapping {
    const lhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedField(alloc, lhs);
    try parser.expectToken(tokens, pos, .eq);
    const rhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedField(alloc, rhs);
    const lhs_is_target = grammar.rowClaimTargetAllowed(alloc, lhs.qualifier, &.{ target_table.name, target_table.alias });
    const lhs_is_source = grammar.rowClaimTargetAllowed(alloc, lhs.qualifier, &.{ source_table.name, source_table.alias });
    const rhs_is_target = grammar.rowClaimTargetAllowed(alloc, rhs.qualifier, &.{ target_table.name, target_table.alias });
    const rhs_is_source = grammar.rowClaimTargetAllowed(alloc, rhs.qualifier, &.{ source_table.name, source_table.alias });
    if (lhs_is_target and rhs_is_source) {
        try binder.validateMergeFields(schema, joined_source_schema, lhs.field, rhs.field);
        const target_field = try alloc.dupe(u8, lhs.field);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target_field);
        const source_field = try alloc.dupe(u8, rhs.field);
        var source_transferred = false;
        errdefer if (!source_transferred) alloc.free(source_field);
        target_transferred = true;
        source_transferred = true;
        return .{
            .target_field = target_field,
            .source_field = source_field,
        };
    }
    if (lhs_is_source and rhs_is_target) {
        try binder.validateMergeFields(schema, joined_source_schema, rhs.field, lhs.field);
        const target_field = try alloc.dupe(u8, rhs.field);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target_field);
        const source_field = try alloc.dupe(u8, lhs.field);
        var source_transferred = false;
        errdefer if (!source_transferred) alloc.free(source_field);
        target_transferred = true;
        source_transferred = true;
        return .{
            .target_field = target_field,
            .source_field = source_field,
        };
    }
    return error.UnsupportedSqlShape;
}

pub fn parseMergeMatchFieldsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    target_table: TableAlias,
    source_table: TableAlias,
) ![]const MergeFieldMapping {
    try parser.expectKeywordTag(tokens, pos, .on);
    var match_fields = std.ArrayListUnmanaged(MergeFieldMapping).empty;
    errdefer {
        freeMergeFieldMappingValues(alloc, match_fields.items);
        match_fields.deinit(alloc);
    }
    while (true) {
        const mapping = try parseMergeQualifiedSourceMappingAlloc(alloc, tokens, pos, schema, joined_source_schema, target_table, source_table);
        try match_fields.append(alloc, mapping);
        if (!parser.matchKeywordTag(tokens, pos, .@"and")) break;
    }
    if (match_fields.items.len == 0) return error.UnsupportedSqlShape;
    return try match_fields.toOwnedSlice(alloc);
}

pub fn parseMergeMutationClausesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    target_table: TableAlias,
    source_table: TableAlias,
    ctes_len: usize,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    condition_options: MergeArmConditionParserOptions,
    assignment_options: MergeAssignmentParserOptions,
    generated_merge_arms: ?*const generated_parser.GeneratedSqlMergeArmListAst,
    returning_hooks: expr_projection.ReturningProjectionParserOptions,
) !ParsedMergeMutationClauses {
    if (generated_merge_arms) |arms| try validateGeneratedMergeArmListForHook(arms.*);
    const match_fields = try parseMergeMatchFieldsAlloc(alloc, tokens, pos, schema, joined_source_schema, target_table, source_table);
    var clauses = ParsedMergeMutationClauses{ .match_fields = match_fields };
    errdefer clauses.deinit(alloc);

    var matched_arms = std.ArrayListUnmanaged(MergeMatchedArm).empty;
    errdefer {
        freeMergeMatchedArmValues(alloc, matched_arms.items);
        matched_arms.deinit(alloc);
    }
    var not_matched_arms = std.ArrayListUnmanaged(MergeNotMatchedArm).empty;
    errdefer {
        freeMergeNotMatchedArmValues(alloc, not_matched_arms.items);
        not_matched_arms.deinit(alloc);
    }

    while (parser.peekKeywordTag(tokens, pos.*, .when)) {
        const arm_start = pos.*;
        _ = parser.matchKeywordTag(tokens, pos, .when);
        if (parser.matchKeywordTag(tokens, pos, .matched)) {
            const generated_arm = generatedMergeArmForStart(generated_merge_arms, arm_start, true) orelse if (generated_merge_arms != null) return error.UnsupportedSqlShape else null;
            const arm = try parseMergeMatchedArmAlloc(
                alloc,
                tokens,
                pos,
                schema,
                joined_source_schema,
                target_table,
                source_table,
                params,
                realtime_ns,
                condition_options,
                assignment_options,
                generated_arm,
            );
            var arm_transferred = false;
            errdefer if (!arm_transferred) freeMergeMatchedArmValue(alloc, arm);
            try matched_arms.append(alloc, arm);
            arm_transferred = true;
        } else if (parser.matchKeywordTag(tokens, pos, .not)) {
            const generated_arm = generatedMergeArmForStart(generated_merge_arms, arm_start, false) orelse if (generated_merge_arms != null) return error.UnsupportedSqlShape else null;
            const arm = try parseMergeNotMatchedArmAlloc(
                alloc,
                tokens,
                pos,
                schema,
                joined_source_schema,
                target_table,
                source_table,
                params,
                realtime_ns,
                condition_options,
                assignment_options,
                generated_arm,
            );
            var arm_transferred = false;
            errdefer if (!arm_transferred) freeMergeNotMatchedArmValue(alloc, arm);
            try not_matched_arms.append(alloc, arm);
            arm_transferred = true;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (matched_arms.items.len == 0 and not_matched_arms.items.len == 0) return error.UnsupportedSqlShape;
    if (generated_merge_arms) |arms| {
        const parsed_arm_count = matched_arms.items.len + not_matched_arms.items.len;
        if (parsed_arm_count != arms.count or matched_arms.items.len != arms.matched_count or not_matched_arms.items.len != arms.not_matched_count) return error.UnsupportedSqlShape;
    }

    clauses.matched_arms = try matched_arms.toOwnedSlice(alloc);
    matched_arms = .empty;
    clauses.not_matched_arms = try not_matched_arms.toOwnedSlice(alloc);
    not_matched_arms = .empty;

    if (parser.matchKeywordTag(tokens, pos, .returning)) {
        if ((generated_merge_arms == null) != (returning_hooks.generated_returning_items == null)) return error.UnsupportedSqlShape;
        const returning_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        clauses.returning = try expr_projection.parseReturningProjectionAlloc(alloc, tokens, pos, schema, &returning_qualifiers, returning_hooks);
    }
    if (ctes_len == 0) {
        if (parser.matchToken(tokens, pos, .semicolon) != null and pos.* != tokens.len) return error.UnsupportedSqlShape;
        if (pos.* != tokens.len) return error.UnsupportedSqlShape;
    }

    return clauses;
}

fn validateGeneratedMergeArmListForHook(arms: generated_parser.GeneratedSqlMergeArmListAst) !void {
    if (arms.count == 0 or arms.items.len != arms.count) return error.UnsupportedSqlShape;
    if (arms.first_tokens == null or arms.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(arms.first_tokens.?, arms.items[0].tokens)) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(arms.last_tokens.?, arms.items[arms.count - 1].tokens)) return error.UnsupportedSqlShape;
    var expected_start = arms.items[0].tokens.start;
    var matched_count: usize = 0;
    var not_matched_count: usize = 0;
    for (arms.items) |arm| {
        if (arm.tokens.start != expected_start or arm.tokens.start >= arm.tokens.end) return error.UnsupportedSqlShape;
        if (arm.action_tokens.start <= arm.tokens.start or arm.action_tokens.start >= arm.action_tokens.end or arm.action_tokens.end != arm.tokens.end) return error.UnsupportedSqlShape;
        if (arm.predicate_tokens) |predicate| {
            if (predicate.start <= arm.tokens.start or predicate.start >= predicate.end or predicate.end >= arm.action_tokens.start) return error.UnsupportedSqlShape;
            if (!generatedDmlTokenRangeEql(arm.predicate_expression.tokens orelse return error.UnsupportedSqlShape, predicate)) return error.UnsupportedSqlShape;
        } else {
            try generated_read_validate.validateGeneratedOptionalExpression(&.{}, null, arm.predicate_expression);
        }
        if (arm.assignments_tokens) |assignments| {
            if (assignments.start < arm.action_tokens.start or assignments.start >= assignments.end or assignments.end > arm.action_tokens.end) return error.UnsupportedSqlShape;
        }
        if (arm.insert_columns_tokens) |columns| {
            if (columns.start <= arm.action_tokens.start or columns.start >= columns.end or columns.end >= arm.action_tokens.end) return error.UnsupportedSqlShape;
        }
        if (arm.insert_values_tokens) |values| {
            if (values.start <= arm.action_tokens.start or values.start >= values.end or values.end > arm.action_tokens.end) return error.UnsupportedSqlShape;
        }
        try validateGeneratedMergeArmActionPayloadForHook(arm);
        if (arm.matched) {
            matched_count += 1;
        } else {
            not_matched_count += 1;
        }
        expected_start = arm.tokens.end;
    }
    if (matched_count != arms.matched_count or not_matched_count != arms.not_matched_count) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlNonEmptyListShape(list: *const generated_parser.GeneratedSqlListAst) !void {
    if (list.count == 0 or list.items.len != list.count) return error.UnsupportedSqlShape;
    if (list.expression_items.len != list.count or list.expressions.len != list.count) return error.UnsupportedSqlShape;
    if (list.alias_items.len != list.count or list.alias_name_items.len != list.count) return error.UnsupportedSqlShape;
    if (list.direction_items.len != list.count or list.directions.len != list.count) return error.UnsupportedSqlShape;
    if (list.order_using_operator_items.len != list.count or list.nulls_order_items.len != list.count or list.nulls_orders.len != list.count) return error.UnsupportedSqlShape;
    if (list.first_tokens == null or list.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.first_tokens.?, list.items[0])) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.last_tokens.?, list.items[list.count - 1])) return error.UnsupportedSqlShape;
}

fn validateGeneratedMergeArmActionPayloadForHook(arm: generated_parser.GeneratedSqlMergeArmAst) !void {
    switch (arm.action_kind) {
        .update => {
            if (!arm.matched or arm.assignments_tokens == null) return error.UnsupportedSqlShape;
            if (arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlNonEmptyListShape(&arm.assignment_items);
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
        .delete => {
            if (!arm.matched) return error.UnsupportedSqlShape;
            if (arm.assignments_tokens != null or arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
        .insert => {
            if (arm.matched or arm.assignments_tokens != null) return error.UnsupportedSqlShape;
            if (arm.insert_columns_tokens == null or arm.insert_values_tokens == null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            try validateGeneratedDmlNonEmptyListShape(&arm.insert_column_items);
            try validateGeneratedDmlNonEmptyListShape(&arm.insert_value_items);
            if (arm.insert_column_items.count != arm.insert_value_items.count) return error.UnsupportedSqlShape;
        },
        .do_nothing => {
            if (arm.assignments_tokens != null or arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
    }
}

fn generatedMergeArmForStart(
    maybe_arms: ?*const generated_parser.GeneratedSqlMergeArmListAst,
    start: usize,
    matched: bool,
) ?*const generated_parser.GeneratedSqlMergeArmAst {
    const arms = maybe_arms orelse return null;
    for (arms.items) |*arm| {
        if (arm.tokens.start == start) {
            if (arm.matched != matched) return null;
            return arm;
        }
    }
    return null;
}

pub fn parseMergeArmPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    target_table: TableAlias,
    source_table: TableAlias,
    allow_target: bool,
    params: []const sql_value.SqlValue,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !MergeArmPredicate {
    const lhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedField(alloc, lhs);
    const lhs_is_target = grammar.rowClaimTargetAllowed(alloc, lhs.qualifier, &.{ target_table.name, target_table.alias });
    const lhs_is_source = grammar.rowClaimTargetAllowed(alloc, lhs.qualifier, &.{ source_table.name, source_table.alias });
    if (lhs_is_target == lhs_is_source) return error.UnsupportedSqlShape;
    const side: MergePredicateSide = if (lhs_is_target) .target else .source;
    if (side == .target and !allow_target) return error.UnsupportedSqlShape;

    const column = switch (side) {
        .target => binder.relationalColumnForField(schema, lhs.field, null) orelse return error.InvalidSqlCatalog,
        .source => blk: {
            const source_schema = joined_source_schema orelse schema;
            break :blk binder.relationalColumnForField(source_schema, lhs.field, null) orelse return error.InvalidSqlCatalog;
        },
    };

    const op_token_index = pos.*;
    const op: runtime_schema.RelationalCheckOp = if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
        .allow_distinct = false,
        .allow_boolean_unknown = true,
        .allow_boolean_literal = true,
    })) |is_tail| blk: {
        try expr_generated_validate.validateGeneratedIsTailPredicateIdentity(generated_expression_ast, tokens, op_token_index, is_tail);
        switch (is_tail.kind) {
            .distinct_comparison => unreachable,
            .null_test => {},
            .boolean_unknown => {
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                break :blk is_tail.op;
            },
            .boolean_literal => {
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                const value_json = try alloc.dupe(u8, sql_value.booleanJson(is_tail.boolean_value));
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                const field = try alloc.dupe(u8, lhs.field);
                var field_transferred = false;
                errdefer if (!field_transferred) alloc.free(field);
                field_transferred = true;
                value_transferred = true;
                return MergeArmPredicate{
                    .side = side,
                    .field = field,
                    .op = .eq,
                    .value_json = value_json,
                };
            },
        }
        break :blk is_tail.op;
    } else try expr_operator.parseComparisonOp(tokens, pos);
    try expr_generated_validate.validateGeneratedRelationalPredicateIdentity(generated_expression_ast, tokens, op_token_index, op);
    const value_json = if (op == .is_null or op == .is_not_null)
        null
    else
        try sql_value.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
    var value_transferred = false;
    errdefer if (!value_transferred) if (value_json) |value| alloc.free(value);
    const field = try alloc.dupe(u8, lhs.field);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    field_transferred = true;
    value_transferred = true;
    return MergeArmPredicate{
        .side = side,
        .field = field,
        .op = op,
        .value_json = value_json,
    };
}

pub fn parseMergeAssignmentExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    target_table: TableAlias,
    source_table: TableAlias,
    options: MergeAssignmentExpressionParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const default_start = pos.*;
    if (parser.matchKeywordTag(tokens, pos, .default)) {
        try validateGeneratedDmlAssignmentRhsMetadata(tokens, default_start, pos.*, options.row_expression_options.generated_expression_ast);
        const default_value = column.default_value orelse return error.UnsupportedSqlShape;
        const value_json = try relational_rows.relationalDefaultValueJsonWithContextAlloc(alloc, default_value, options.default_context);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        value_transferred = true;
        return .{
            .kind = .value,
            .value_json = value_json,
        };
    }

    const expression = try expr_row_parse.parseJoinedRowExpressionWithTableQualifiersAlloc(
        alloc,
        tokens,
        pos,
        target_table,
        source_table,
        options.row_expression_options,
    );
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try validateMutationAssignmentExpressionType(options.type_context, column, expression, .{ .validate_json = true });
    expression_transferred = true;
    return expression;
}

pub fn parseJoinedMutationAssignmentExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    target_alias: []const u8,
    type_context: expr_type.RowExpressionTypeContext,
    options: JoinedMutationAssignmentExpressionParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const target_qualifiers = [_][]const u8{target_alias};
    const source_qualifiers = [_][]const u8{options.pending_joined_source_alias orelse return error.UnsupportedSqlShape};
    const expression = try expr_row_parse.parseJoinedRowExpressionWithQualifiersAlloc(
        alloc,
        tokens,
        pos,
        target_qualifiers[0..],
        source_qualifiers[0..],
        options.row_expression_options,
    );
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try validateMutationAssignmentExpressionType(type_context, column, expression, .{});
    expression_transferred = true;
    return expression;
}

pub fn parseJoinedMutationBooleanAssignmentExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    target_alias: []const u8,
    type_context: expr_type.RowExpressionTypeContext,
    options: JoinedMutationAssignmentExpressionParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const target_qualifiers = [_][]const u8{target_alias};
    const source_qualifiers = [_][]const u8{options.pending_joined_source_alias orelse return error.UnsupportedSqlShape};
    const expression = try expr_row_parse.parseJoinedBooleanRowExpressionWithQualifiersAlloc(
        alloc,
        tokens,
        pos,
        target_qualifiers[0..],
        source_qualifiers[0..],
        options.boolean_expression_options,
    );
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try type_context.validateBooleanRowExpression(expression);
    expression_transferred = true;
    return expression;
}

pub fn parseConflictAssignmentExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    options: ConflictAssignmentExpressionParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const start = pos.*;
    var expression = try parseConflictExpressionWithExpectedAndGeneratedAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        options.schema,
        options.conflict_existing_qualifiers,
        column,
        insert_columns,
        column.field_type,
        options.type_context,
        options.defer_row_expression_field_validation,
        options.dispatch_options,
        options.generated_expression_ast,
    );
    var expression_owned = true;
    errdefer if (expression_owned) freeExpression(alloc, expression);
    if (expr_operator.peekArithmeticOperator(tokens, pos.*)) |_| {
        try options.type_context.validateNumericOrDatetimeRowExpression(expression);
        expression_owned = false;
        expression = try parseConflictArithmeticExpressionRestAlloc(alloc, tokens, pos, expression, column, insert_columns, 0, options);
        expression_owned = true;
        try options.type_context.validateNumericRowExpression(expression);
    }
    if (parser.peekKind(tokens, pos.*, .pipe_concat)) {
        if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidSqlCatalog;
        expression_owned = false;
        expression = try parseConflictPipeConcatExpressionRestAlloc(alloc, tokens, pos, expression, column, insert_columns, options);
        expression_owned = true;
        try options.type_context.validateTextRowExpression(expression);
    }
    if (expr_type.sqlExpressionIsInterval(expression)) return error.UnsupportedSqlShape;
    if (column.field_type == .datetime) {
        try options.type_context.validateNumericOrDatetimeRowExpression(expression);
    } else if (column.field_type == .numeric) {
        try options.type_context.validateNumericRowExpression(expression);
    }
    try expr_generated_validate.validateGeneratedRowExpressionIdentityStrict(tokens, start, pos.*, expression, options.generated_expression_ast);
    expression_owned = false;
    return expression;
}

pub fn parseConflictRowExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    column: runtime_schema.RelationalColumn,
    insert_columns: []const []const u8,
    expected_type: ?runtime_schema.AntflyType,
    options: ConflictAssignmentExpressionParserOptions,
) anyerror!db_mod.types.RelationalRowsExpression {
    var expression = try parseConflictExpressionWithExpectedAndGeneratedAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        options.schema,
        options.conflict_existing_qualifiers,
        column,
        insert_columns,
        expected_type,
        options.type_context,
        options.defer_row_expression_field_validation,
        options.dispatch_options,
        options.generated_expression_ast,
    );
    var expression_owned = true;
    errdefer if (expression_owned) freeExpression(alloc, expression);
    if (expr_operator.peekArithmeticOperator(tokens, pos.*)) |_| {
        try options.type_context.validateNumericOrDatetimeRowExpression(expression);
        expression_owned = false;
        expression = try parseConflictArithmeticExpressionRestAlloc(alloc, tokens, pos, expression, column, insert_columns, 0, options);
        expression_owned = true;
        try options.type_context.validateNumericRowExpression(expression);
    }
    if (parser.peekKind(tokens, pos.*, .pipe_concat)) {
        expression_owned = false;
        expression = try parseConflictPipeConcatExpressionRestAlloc(alloc, tokens, pos, expression, column, insert_columns, options);
        expression_owned = true;
        try options.type_context.validateTextRowExpression(expression);
    }
    expression_owned = false;
    return expression;
}

pub fn parseConflictExpressionWithExpectedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const sql_value.SqlValue,
