    const published_write = parsed_sql.writeStatementIncludingGeneratedAst() orelse return error.UnsupportedSqlShape;
    switch (parsed_sql.statement) {
        .write => |statement| {
            if (statement.kind != published_write.kind or statement.recursive != published_write.recursive) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
    const write_kind = published_write.kind;
    if (dml_ast.cte_recursive != published_write.recursive) return error.UnsupportedSqlShape;
    if (!generatedDmlAstMatchesWriteKind(dml_ast.kind, write_kind)) return error.UnsupportedSqlShape;
    if (dml_ast.cte_recursive) {
        return try lowerRecursiveWritePlanFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options, write_kind);
    }
    if (dml_ast.kind == .insert_values) {
        return .{ .insert = try insertValuesFromGeneratedDmlAstWithFunctionBindingsAlloc(alloc, parsed_sql.items(), dml_ast, schema, params, options, function_bindings) };
    }
    if (dml_ast.kind == .insert_select) {
        return .{ .insert_source = try insertSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options) };
    }
    if (dml_ast.kind == .update) {
        switch (write_kind) {
            .update => switch (try classifyGeneratedUpdateSelectorFromDmlAstAlloc(alloc, parsed_sql.items(), dml_ast, schema, params, options.unique_resolver)) {
                .point => return .{ .update = try updatePointFromGeneratedDmlAstAlloc(alloc, parsed_sql.items(), dml_ast, schema, params, options) },
                .source => return .{ .update_source = try updateSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options, write_kind) },
            },
            .update_source => return .{ .update_source = try updateSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options, write_kind) },
            .update_joined_source => return .{ .update_joined_source = try updateJoinedSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options) },
            else => return error.UnsupportedSqlShape,
        }
    }
    if (dml_ast.kind == .delete) {
        switch (write_kind) {
            .delete => switch (try classifyGeneratedDeleteSelectorFromDmlAstAlloc(alloc, parsed_sql.items(), dml_ast, schema, params, options.unique_resolver)) {
                .point => return .{ .delete = try deletePointFromGeneratedDmlAstAlloc(alloc, parsed_sql.items(), dml_ast, schema, params, options) },
                .source => return .{ .delete_source = try deleteSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options, write_kind) },
            },
            .delete_source => return .{ .delete_source = try deleteSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options, write_kind) },
            .delete_joined_source => return .{ .delete_joined_source = try deleteJoinedSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options) },
            else => return error.UnsupportedSqlShape,
        }
    }
    if (dml_ast.kind == .truncate) {
        if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
        const options_row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
        var row_claim = try mutationRowClaimAlloc(alloc, options_row_claim, false);
        errdefer if (row_claim.owner_id.len > 0) alloc.free(row_claim.owner_id);
        if (row_claim.txn_id == null) return error.UnsupportedRowsQuery;
        var syntax = try truncateSyntaxFromGeneratedDmlAstAlloc(alloc, parsed_sql.items(), dml_ast);
        var lowered = try truncateMutationSourceFromSyntaxAlloc(alloc, &syntax, schema, row_claim);
        row_claim.owner_id = "";
        lowered.sync_level = options.sync_level;
        return .{ .truncate_source = lowered };
    }
    if (dml_ast.kind == .merge) {
        return .{ .merge_mutation = try mergeMutationFromGeneratedDmlAstAlloc(alloc, parsed_sql, dml_ast, schema, params, options) };
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadSourceBodyAst(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    const source_read = ast.source_read orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyLayout(tokens, source_range, source_read);
}

fn parsedSourceReadStartsWithSelect(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
) bool {
    return range.start < range.end and
        range.end <= tokens.len and
        tokens[range.start].matchesKeywordTag(.select);
}

fn validateGeneratedDmlReadBodyLayout(
    tokens: []const Token,
    body_range: generated_parser.GeneratedSqlTokenRange,
    body_read: generated_parser.GeneratedSqlDmlReadBodyAst,
) !void {
    if (body_range.start >= body_range.end or body_range.end > tokens.len) return error.UnsupportedSqlShape;
    if (body_read.tokens.start != body_range.start or body_read.tokens.end != body_range.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodySpans(tokens, body_range, body_read);
    if (body_read.wrapper_projection_star) return error.UnsupportedSqlShape;
    switch (body_read.kind) {
        .query, .aggregate, .join, .lateral, .window => if (body_read.set_operation_tokens != null) return error.UnsupportedSqlShape,
        .set_operation => if (body_read.set_operation_tokens == null) return error.UnsupportedSqlShape,
        .cte => return error.UnsupportedSqlShape,
    }
    if (!parsedSourceReadStartsWithSelect(tokens, body_range)) return error.UnsupportedSqlShape;
    const projection_range = body_read.projection_tokens orelse return error.UnsupportedSqlShape;
    if (projection_range.start <= body_range.start or projection_range.end > body_range.end or projection_range.start >= projection_range.end) return error.UnsupportedSqlShape;
    var previous_end = projection_range.end;
    if (body_read.source_tokens) |source_range| {
        if (source_range.start != projection_range.end + 1 or source_range.end > body_range.end or source_range.start >= source_range.end) return error.UnsupportedSqlShape;
        if (source_range.start == 0 or !tokens[source_range.start - 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
        previous_end = source_range.end;
        try validateGeneratedDmlReadBodySystemTimePayload(
            tokens,
            body_read.source_tokens,
            body_read.source_system_time_tokens,
            body_read.source_system_time_sequence_tokens,
        );
        try validateGeneratedDmlReadBodyTableFunctionPayloads(
            tokens,
            body_read.source_tokens,
            body_read.source_antfly_function_items,
            body_read.source_antfly_function_count,
            body_read.source_graph_function_items,
            body_read.source_graph_function_count,
        );
        try validateGeneratedDmlReadBodySingleSourceAlias(tokens, body_read);
    } else if (body_read.source_table_tokens != null or
        body_read.source_alias_tokens != null or
        body_read.source_alias_name_tokens != null or
        body_read.source_system_time_tokens != null or
        body_read.source_system_time_sequence_tokens != null or
        body_read.source_antfly_function_items.len != 0 or
        body_read.source_antfly_function_count != 0 or
        body_read.source_graph_function_items.len != 0 or
        body_read.source_graph_function_count != 0)
    {
        return error.UnsupportedSqlShape;
    }
    if (body_read.where_tokens) |where_range| {
        if (where_range.start <= previous_end or where_range.end > body_range.end or where_range.start >= where_range.end) return error.UnsupportedSqlShape;
        if (where_range.start == 0 or !tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
        previous_end = where_range.end;
    }
    if (body_read.set_operation_tokens) |set_operation_range| {
        if (set_operation_range.start != previous_end or set_operation_range.end > body_range.end or set_operation_range.start >= set_operation_range.end) return error.UnsupportedSqlShape;
        if (body_read.kind != .set_operation) return error.UnsupportedSqlShape;
        if (!tokens[set_operation_range.start].matchesKeywordTag(.@"union") and
            !tokens[set_operation_range.start].matchesKeywordTag(.intersect) and
            !tokens[set_operation_range.start].matchesKeywordTag(.except))
        {
            return error.UnsupportedSqlShape;
        }
        previous_end = set_operation_range.end;
    } else if (body_read.kind == .set_operation) {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlReadBodyTail(tokens, body_range, previous_end);
}

fn validateGeneratedDmlReadBodyTail(
    tokens: []const Token,
    body_range: generated_parser.GeneratedSqlTokenRange,
    tail_start: usize,
) !void {
    if (tail_start == body_range.end) return;
    if (tail_start > body_range.end or tail_start >= tokens.len) return error.UnsupportedSqlShape;
    if (tokens[tail_start].matchesKeywordTag(.group)) {
        if (tail_start + 1 < body_range.end and tokens[tail_start + 1].matchesKeywordTag(.by)) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[tail_start].matchesKeywordTag(.having) or
        tokens[tail_start].matchesKeywordTag(.window) or
        tokens[tail_start].matchesKeywordTag(.order) or
        tokens[tail_start].matchesKeywordTag(.limit) or
        tokens[tail_start].matchesKeywordTag(.offset) or
        tokens[tail_start].matchesKeywordTag(.fetch))
    {
        return;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadBodySpans(
    tokens: []const Token,
    body_range: generated_parser.GeneratedSqlTokenRange,
    body_read: generated_parser.GeneratedSqlDmlReadBodyAst,
) !void {
    if (body_range.start >= body_range.end or body_range.end > tokens.len) return error.UnsupportedSqlShape;
    const first = tokens[body_range.start];
    const last = tokens[body_range.end - 1];
    if (body_read.statement_span.start != first.source_start or body_read.statement_span.end != last.source_end) return error.UnsupportedSqlShape;
    if (body_read.command_span.start != first.source_start or body_read.command_span.end != first.source_end) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadBodySystemTimePayload(
    tokens: []const Token,
    maybe_source: ?generated_parser.GeneratedSqlTokenRange,
    maybe_system_time: ?generated_parser.GeneratedSqlTokenRange,
    maybe_sequence: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    const system_time = maybe_system_time orelse {
        if (maybe_sequence != null) return error.UnsupportedSqlShape;
        return;
    };
    const source = maybe_source orelse return error.UnsupportedSqlShape;
    const sequence = maybe_sequence orelse return error.UnsupportedSqlShape;
    if (source.start >= source.end or source.end > tokens.len) return error.UnsupportedSqlShape;
    if (system_time.start < source.start or system_time.end != source.end or system_time.end > tokens.len) return error.UnsupportedSqlShape;
    if (system_time.end != system_time.start + 5 and system_time.end != system_time.start + 6) return error.UnsupportedSqlShape;
    if (!tokens[system_time.start].matchesKeywordTag(.@"for")) return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(tokens[system_time.start + 1].text, "system_time")) return error.UnsupportedSqlShape;
    if (!tokens[system_time.start + 2].matchesKeywordTag(.as)) return error.UnsupportedSqlShape;
    if (!tokens[system_time.start + 3].matchesKeywordTag(.of)) return error.UnsupportedSqlShape;
    if (sequence.start != system_time.start + 4 or sequence.end != system_time.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodySystemTimePayloadValue(tokens, sequence);
}

fn validateGeneratedDmlReadBodySystemTimePayloadValue(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (range.end == range.start + 1) {
        switch (tokens[range.start].kind) {
            .number => if (std.mem.indexOfAny(u8, tokens[range.start].text, ".eE+-") != null) return error.UnsupportedSqlShape,
            .string => {},
            else => return error.UnsupportedSqlShape,
        }
        return;
    }
    if (range.end == range.start + 2 and tokens[range.start + 1].kind == .string) {
        if (!generatedDmlReadBodySystemTimePayloadTypeToken(tokens[range.start])) return error.UnsupportedSqlShape;
        return;
    }
    return error.UnsupportedSqlShape;
}

fn generatedDmlReadBodySystemTimePayloadTypeToken(token: Token) bool {
    const keyword = token.keyword orelse return false;
    return keyword == .date or keyword == .timestamp or std.ascii.eqlIgnoreCase(token.text, "timestamptz");
}

fn validateGeneratedDmlReadBodyTableFunctionPayloads(
    tokens: []const Token,
    maybe_source: ?generated_parser.GeneratedSqlTokenRange,
    antfly_items: []const generated_parser.GeneratedSqlAntflyTableFunctionAst,
    antfly_count: usize,
    graph_items: []const generated_parser.GeneratedSqlGraphTableFunctionAst,
    graph_count: usize,
) !void {
    if (antfly_items.len != antfly_count or graph_items.len != graph_count) return error.UnsupportedSqlShape;
    if (antfly_items.len == 0 and graph_items.len == 0) return;
    const source = maybe_source orelse return error.UnsupportedSqlShape;
    if (source.start >= source.end or source.end > tokens.len) return error.UnsupportedSqlShape;
    for (antfly_items) |item| try validateGeneratedDmlReadBodyAntflyFunctionPayload(tokens, source, item);
    for (graph_items) |item| try validateGeneratedDmlReadBodyGraphFunctionPayload(tokens, source, antfly_items, item);
}

fn validateGeneratedDmlReadBodyAntflyFunctionPayload(
    tokens: []const Token,
    source: generated_parser.GeneratedSqlTokenRange,
    item: generated_parser.GeneratedSqlAntflyTableFunctionAst,
) !void {
    try validateGeneratedDmlReadBodyNestedRange(tokens, source, item.tokens);
    try validateGeneratedDmlReadBodyNestedRange(tokens, item.tokens, item.name_tokens);
    try validateGeneratedDmlReadBodyNestedRange(tokens, item.tokens, item.argument_tokens);
    if (item.argument_count != item.argument_items.len) return error.UnsupportedSqlShape;
    if (item.tokens.end < item.tokens.start + 3) return error.UnsupportedSqlShape;
    if (!std.meta.eql(item.name_tokens, generated_parser.GeneratedSqlTokenRange{ .start = item.tokens.start, .end = item.tokens.start + 1 })) return error.UnsupportedSqlShape;
    if (!std.meta.eql(item.argument_tokens, generated_parser.GeneratedSqlTokenRange{ .start = item.tokens.start + 2, .end = item.tokens.end - 1 })) return error.UnsupportedSqlShape;
    if (tokens[item.tokens.start + 1].kind != .lparen or tokens[item.tokens.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    if (generatedDmlReadBodyAntflyFunctionKindForToken(tokens[item.name_tokens.start]) != item.kind) return error.UnsupportedSqlShape;
    if (item.argument_items.len == 0) {
        if (item.argument_tokens.start != item.argument_tokens.end) return error.UnsupportedSqlShape;
        return;
    }
    var expected_start: usize = item.argument_tokens.start;
    for (item.argument_items, 0..) |argument, index| {
        if (argument.tokens.start != expected_start) return error.UnsupportedSqlShape;
        try validateGeneratedDmlReadBodyNestedRange(tokens, item.argument_tokens, argument.tokens);
        try validateGeneratedDmlReadBodyNestedRange(tokens, argument.tokens, argument.name_tokens);
        try validateGeneratedDmlReadBodyNestedRange(tokens, argument.tokens, argument.operator_tokens);
        try validateGeneratedDmlReadBodyNestedRange(tokens, argument.tokens, argument.value_tokens);
        if (!std.meta.eql(argument.name_tokens, generated_parser.GeneratedSqlTokenRange{ .start = argument.tokens.start, .end = argument.tokens.start + 1 })) return error.UnsupportedSqlShape;
        if (argument.operator_tokens.start != argument.name_tokens.end or argument.operator_tokens.end > argument.value_tokens.start) return error.UnsupportedSqlShape;
        if (argument.value_tokens.end != argument.tokens.end) return error.UnsupportedSqlShape;
        if (argument.value_tokens.start >= argument.value_tokens.end) return error.UnsupportedSqlShape;
        if (tokens[argument.name_tokens.start].kind != .identifier) return error.UnsupportedSqlShape;
        if (tokens[argument.operator_tokens.start].kind != .eq) return error.UnsupportedSqlShape;
        if (argument.operator_tokens.end == argument.operator_tokens.start + 2 and tokens[argument.operator_tokens.start + 1].kind != .gt) return error.UnsupportedSqlShape;
        if (argument.operator_tokens.end != argument.operator_tokens.start + 1 and argument.operator_tokens.end != argument.operator_tokens.start + 2) return error.UnsupportedSqlShape;
        for (item.argument_items[0..index]) |previous| {
            if (std.ascii.eqlIgnoreCase(tokens[previous.name_tokens.start].text, tokens[argument.name_tokens.start].text)) {
                return error.UnsupportedSqlShape;
            }
        }
        if (index + 1 < item.argument_items.len) {
            if (argument.tokens.end >= item.argument_tokens.end or tokens[argument.tokens.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = argument.tokens.end + 1;
        } else {
            expected_start = argument.tokens.end;
        }
    }
    if (expected_start != item.argument_tokens.end) return error.UnsupportedSqlShape;
}

fn generatedDmlReadBodyAntflyFunctionKindForToken(token: Token) ?generated_parser.GeneratedSqlAntflyTableFunctionKind {
    if (token.matchesQualifiedKeywordTag("antfly", .full_text_search)) return .full_text_search;
    if (token.matchesQualifiedKeywordTag("antfly", .semantic_search)) return .semantic_search;
    if (token.matchesQualifiedKeywordTag("antfly", .vector_search)) return .vector_search;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_traverse)) return .graph_traverse;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_neighbors)) return .graph_neighbors;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_shortest_path)) return .graph_shortest_path;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_k_shortest_paths)) return .graph_k_shortest_paths;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_match)) return .graph_match;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_metric)) return .graph_metric;
    if (token.matchesQualifiedKeywordTag("antfly", .graph_metric_rerank)) return .graph_metric_rerank;
    if (token.matchesQualifiedKeywordTag("antfly", .hybrid_search)) return .hybrid_search;
    return null;
}

fn generatedDmlReadBodyGraphFunctionKindFromAntfly(kind: generated_parser.GeneratedSqlAntflyTableFunctionKind) ?generated_parser.GeneratedSqlGraphTableFunctionKind {
    return switch (kind) {
        .graph_traverse => .traverse,
        .graph_neighbors => .neighbors,
        .graph_shortest_path => .shortest_path,
        .graph_k_shortest_paths => .k_shortest_paths,
        .graph_match => .match,
        .graph_metric => .metric,
        .graph_metric_rerank => .metric_rerank,
        else => null,
    };
}

fn validateGeneratedDmlReadBodyGraphFunctionPayload(
    tokens: []const Token,
    source: generated_parser.GeneratedSqlTokenRange,
    antfly_items: []const generated_parser.GeneratedSqlAntflyTableFunctionAst,
    item: generated_parser.GeneratedSqlGraphTableFunctionAst,
) !void {
    try validateGeneratedDmlReadBodyNestedRangeNoTokens(source, item.tokens);
    try validateGeneratedDmlReadBodyNestedRangeNoTokens(item.tokens, item.name_tokens);
    try validateGeneratedDmlReadBodyNestedRangeNoTokens(item.tokens, item.argument_tokens);
    if (item.tokens.end < item.tokens.start + 3) return error.UnsupportedSqlShape;
    if (!std.meta.eql(item.name_tokens, generated_parser.GeneratedSqlTokenRange{ .start = item.tokens.start, .end = item.tokens.start + 1 })) return error.UnsupportedSqlShape;
    if (!std.meta.eql(item.argument_tokens, generated_parser.GeneratedSqlTokenRange{ .start = item.tokens.start + 2, .end = item.tokens.end - 1 })) return error.UnsupportedSqlShape;
    var matching_antfly_item: ?generated_parser.GeneratedSqlAntflyTableFunctionAst = null;
    for (antfly_items) |antfly_item| {
        if (!std.meta.eql(antfly_item.tokens, item.tokens)) continue;
        if (!std.meta.eql(antfly_item.name_tokens, item.name_tokens)) continue;
        if (!std.meta.eql(antfly_item.argument_tokens, item.argument_tokens)) continue;
        if (generatedDmlReadBodyGraphFunctionKindFromAntfly(antfly_item.kind) != item.kind) continue;
        matching_antfly_item = antfly_item;
        break;
    }
    const antfly_item = matching_antfly_item orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyGraphSemanticPayload(tokens, item, antfly_item);
}

fn validateGeneratedDmlReadBodyGraphValueRange(
    argument_tokens: generated_parser.GeneratedSqlTokenRange,
    maybe_value: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    const value = maybe_value orelse return;
    try validateGeneratedDmlReadBodyNestedRangeNoTokens(argument_tokens, value);
}

fn validateGeneratedDmlReadBodyGraphSemanticPayload(
    tokens: []const Token,
    graph_item: generated_parser.GeneratedSqlGraphTableFunctionAst,
    antfly_item: generated_parser.GeneratedSqlAntflyTableFunctionAst,
) !void {
    if (graph_item.argument_count != antfly_item.argument_count) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.table_name_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "table_name", "table" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.index_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "index", "graph_index" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.start_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "start", "start_node" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.start_result_ref_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "start_result_ref", "result_ref" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.target_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "target", "target_node" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.target_result_ref_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{"target_result_ref"}));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.pattern_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{"pattern"}));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.return_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "return", "return_aliases" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.metric_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "metric", "graph_metric" }));
    try validateGeneratedDmlReadBodyGraphSemanticValue(tokens, graph_item.argument_tokens, graph_item.query_value_tokens, try generatedDmlReadBodyAntflyArgumentValueByNames(tokens, antfly_item, &.{ "query", "text" }));

    switch (graph_item.kind) {
        .traverse, .neighbors => {
            if (graph_item.index_value_tokens == null or (graph_item.start_value_tokens == null and graph_item.start_result_ref_value_tokens == null)) return error.UnsupportedSqlShape;
        },
        .shortest_path, .k_shortest_paths => {
            if (graph_item.index_value_tokens == null or
                (graph_item.start_value_tokens == null and graph_item.start_result_ref_value_tokens == null) or
                (graph_item.target_value_tokens == null and graph_item.target_result_ref_value_tokens == null))
            {
                return error.UnsupportedSqlShape;
            }
        },
        .match => {
            if (graph_item.index_value_tokens == null or
                (graph_item.start_value_tokens == null and graph_item.start_result_ref_value_tokens == null) or
                graph_item.pattern_value_tokens == null)
            {
                return error.UnsupportedSqlShape;
            }
        },
        .metric, .metric_rerank => {
            if (graph_item.index_value_tokens == null or graph_item.metric_value_tokens == null) return error.UnsupportedSqlShape;
        },
    }
}

fn validateGeneratedDmlReadBodyGraphSemanticValue(
    tokens: []const Token,
    argument_tokens: generated_parser.GeneratedSqlTokenRange,
    actual: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    if (actual == null and expected == null) return;
    const actual_value = actual orelse return error.UnsupportedSqlShape;
    const expected_value = expected orelse return error.UnsupportedSqlShape;
    if (!std.meta.eql(actual_value, expected_value)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyNestedRange(tokens, argument_tokens, actual_value);
}

fn generatedDmlReadBodyAntflyArgumentValueByNames(
    tokens: []const Token,
    item: generated_parser.GeneratedSqlAntflyTableFunctionAst,
    names: []const []const u8,
) !?generated_parser.GeneratedSqlTokenRange {
    var value: ?generated_parser.GeneratedSqlTokenRange = null;
    for (item.argument_items) |argument| {
        if (argument.name_tokens.start >= argument.name_tokens.end or argument.name_tokens.start >= tokens.len) continue;
        for (names) |name| {
            if (std.ascii.eqlIgnoreCase(tokens[argument.name_tokens.start].text, name)) {
                if (value != null) return error.UnsupportedSqlShape;
                value = argument.value_tokens;
            }
        }
    }
    return value;
}

fn validateGeneratedDmlReadBodyNestedRange(
    tokens: []const Token,
    outer: generated_parser.GeneratedSqlTokenRange,
    inner: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (outer.start >= outer.end or outer.end > tokens.len) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyNestedRangeNoTokens(outer, inner);
}

fn validateGeneratedDmlReadBodyNestedRangeNoTokens(
    outer: generated_parser.GeneratedSqlTokenRange,
    inner: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (inner.start < outer.start or inner.end > outer.end or inner.start >= inner.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadBodySingleSourceAlias(
    tokens: []const Token,
    body_read: generated_parser.GeneratedSqlDmlReadBodyAst,
) !void {
    const source = body_read.source_tokens orelse {
        if (body_read.source_table_tokens != null or
            body_read.source_alias_tokens != null or
            body_read.source_alias_name_tokens != null or
            body_read.source_system_time_tokens != null or
            body_read.source_system_time_sequence_tokens != null)
        {
            return error.UnsupportedSqlShape;
        }
        return;
    };
    if (source.start >= source.end or source.end > tokens.len) return error.UnsupportedSqlShape;
    const source_table = body_read.source_table_tokens orelse {
        if (body_read.source_alias_tokens != null or
            body_read.source_alias_name_tokens != null or
            body_read.source_system_time_tokens != null or
            body_read.source_system_time_sequence_tokens != null)
        {
            return error.UnsupportedSqlShape;
        }
        if (!generatedDmlReadBodySourceLooksLikeSingleTableSource(tokens, source)) return;
        return error.UnsupportedSqlShape;
    };

    var expected_table_start = source.start;
    if (tokens[expected_table_start].matchesKeywordTag(.only)) expected_table_start += 1;
    if (source_table.start != expected_table_start or source_table.end != expected_table_start + 1 or source_table.end > source.end) return error.UnsupportedSqlShape;
    if (tokens[source_table.start].kind != .identifier) return error.UnsupportedSqlShape;
    const alias_end = try generatedDmlReadBodySingleSourceAliasEnd(
        tokens,
        source_table,
        body_read.source_alias_tokens,
        body_read.source_alias_name_tokens,
    );
    const source_body_end = if (body_read.source_system_time_tokens) |system_time| system_time.start else source.end;
    if (alias_end != source_body_end) return error.UnsupportedSqlShape;
}

fn generatedDmlReadBodySingleSourceAliasEnd(
    tokens: []const Token,
    source_table: generated_parser.GeneratedSqlTokenRange,
    source_alias_tokens: ?generated_parser.GeneratedSqlTokenRange,
    source_alias_name_tokens: ?generated_parser.GeneratedSqlTokenRange,
) !usize {
    if (source_table.start >= source_table.end or source_table.end > tokens.len) return error.UnsupportedSqlShape;
    const alias = source_alias_tokens orelse {
        if (source_alias_name_tokens != null) return error.UnsupportedSqlShape;
        return source_table.end;
    };
    const alias_name = source_alias_name_tokens orelse return error.UnsupportedSqlShape;
    if (alias.start != source_table.end or alias.start >= alias.end or alias.end > tokens.len) return error.UnsupportedSqlShape;
    const expected_name = if (alias.end == source_table.end + 2 and
        tokens[source_table.end].matchesKeywordTag(.as) and
        tokens[source_table.end + 1].kind == .identifier)
    blk: {
        break :blk generated_parser.GeneratedSqlTokenRange{ .start = source_table.end + 1, .end = source_table.end + 2 };
    } else if (alias.end == source_table.end + 1 and
        tokens[source_table.end].kind == .identifier and
        !plan_mod.nextIsJoinClauseKeyword(tokens, source_table.end))
    blk: {
        break :blk alias;
    } else return error.UnsupportedSqlShape;
    if (alias_name.start != expected_name.start or alias_name.end != expected_name.end) return error.UnsupportedSqlShape;
    return alias.end;
}

fn generatedDmlReadBodySourceLooksLikeSingleTableSource(
    tokens: []const Token,
    source: generated_parser.GeneratedSqlTokenRange,
) bool {
    if (source.start >= source.end or source.end > tokens.len) return false;
    var table_start = source.start;
    if (tokens[table_start].matchesKeywordTag(.only)) table_start += 1;
    if (table_start >= source.end or tokens[table_start].kind != .identifier) return false;

    const table_end = table_start + 1;
    if (table_end == source.end) return true;
    if (table_end + 2 == source.end and
        tokens[table_end].matchesKeywordTag(.as) and
        tokens[table_end + 1].kind == .identifier)
    {
        return true;
    }
    if (table_end + 1 == source.end and
        tokens[table_end].kind == .identifier and
        !plan_mod.nextIsJoinClauseKeyword(tokens, table_end))
    {
        return true;
    }
    return false;
}

fn validateGeneratedDmlReadSourceBodyAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    _ = alloc;
    try validateGeneratedDmlReadSourceBodyAst(parsed_sql.items(), ast);
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    const source_read = ast.source_read orelse return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyReadAst(parsed_sql.items(), source_range, source_read);
}

fn validateGeneratedDmlReadBodyReadAst(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    read_body: generated_parser.GeneratedSqlDmlReadBodyAst,
) !void {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (read_body.tokens.start != range.start or read_body.tokens.end != range.end) return error.UnsupportedSqlShape;
    if (read_body.wrapper_projection_star) return error.UnsupportedSqlShape;
    const read_ast = read_body.read_ast orelse return error.UnsupportedSqlShape;
    if (read_ast.kind != read_body.kind) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.projection_tokens, read_ast.projection_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_tokens, read_ast.source_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_table_tokens, read_ast.source_table_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_alias_tokens, read_ast.source_alias_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_alias_name_tokens, read_ast.source_alias_name_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_system_time_tokens, read_ast.source_system_time_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.source_system_time_sequence_tokens, read_ast.source_system_time_sequence_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.where_tokens, read_ast.where_tokens);
    try validateGeneratedDmlReadBodyLocalRange(range, read_body.set_operation_tokens, read_ast.set_operation_tokens);
    try validateGeneratedDmlReadBodyTableFunctionMirrors(range, read_body, read_ast);
    try lowering_context.validateGeneratedReadAstForStatement(tokens[range.start..range.end], read_ast);
}

fn validateGeneratedDmlReadBodyLocalRange(
    body_range: generated_parser.GeneratedSqlTokenRange,
    absolute_range: ?generated_parser.GeneratedSqlTokenRange,
    local_range: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    if (absolute_range == null or local_range == null) {
        if (absolute_range == null and local_range == null) return;
        return error.UnsupportedSqlShape;
    }
    const absolute = absolute_range.?;
    const local = local_range.?;
    if (absolute.start < body_range.start or absolute.end > body_range.end or absolute.start > absolute.end) return error.UnsupportedSqlShape;
    if (local.start != absolute.start - body_range.start or local.end != absolute.end - body_range.start) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadBodyRequiredLocalRange(
    body_range: generated_parser.GeneratedSqlTokenRange,
    absolute: generated_parser.GeneratedSqlTokenRange,
    local: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (absolute.start < body_range.start or absolute.end > body_range.end or absolute.start >= absolute.end) return error.UnsupportedSqlShape;
    if (local.start != absolute.start - body_range.start or local.end != absolute.end - body_range.start) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlReadBodyTableFunctionMirrors(
    body_range: generated_parser.GeneratedSqlTokenRange,
    read_body: generated_parser.GeneratedSqlDmlReadBodyAst,
    read_ast: *const generated_parser.GeneratedSqlReadAst,
) !void {
    if (read_body.source_antfly_function_count != read_ast.source_antfly_function_count or
        read_body.source_antfly_function_items.len != read_ast.source_antfly_function_items.len or
        read_body.source_graph_function_count != read_ast.source_graph_function_count or
        read_body.source_graph_function_items.len != read_ast.source_graph_function_items.len)
    {
        return error.UnsupportedSqlShape;
    }
    for (read_body.source_antfly_function_items, read_ast.source_antfly_function_items) |absolute, local| {
        try validateGeneratedDmlReadBodyAntflyFunctionMirror(body_range, absolute, local);
    }
    for (read_body.source_graph_function_items, read_ast.source_graph_function_items) |absolute, local| {
        try validateGeneratedDmlReadBodyGraphFunctionMirror(body_range, absolute, local);
    }
}

fn validateGeneratedDmlReadBodyAntflyFunctionMirror(
    body_range: generated_parser.GeneratedSqlTokenRange,
    absolute: generated_parser.GeneratedSqlAntflyTableFunctionAst,
    local: generated_parser.GeneratedSqlAntflyTableFunctionAst,
) !void {
    if (absolute.kind != local.kind or
        absolute.argument_count != local.argument_count or
        absolute.argument_items.len != local.argument_items.len)
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.tokens, local.tokens);
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.name_tokens, local.name_tokens);
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.argument_tokens, local.argument_tokens);
    for (absolute.argument_items, local.argument_items) |absolute_argument, local_argument| {
        try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute_argument.tokens, local_argument.tokens);
        try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute_argument.name_tokens, local_argument.name_tokens);
        try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute_argument.operator_tokens, local_argument.operator_tokens);
        try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute_argument.value_tokens, local_argument.value_tokens);
    }
}

fn validateGeneratedDmlReadBodyGraphFunctionMirror(
    body_range: generated_parser.GeneratedSqlTokenRange,
    absolute: generated_parser.GeneratedSqlGraphTableFunctionAst,
    local: generated_parser.GeneratedSqlGraphTableFunctionAst,
) !void {
    if (absolute.kind != local.kind or absolute.argument_count != local.argument_count) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.tokens, local.tokens);
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.name_tokens, local.name_tokens);
    try validateGeneratedDmlReadBodyRequiredLocalRange(body_range, absolute.argument_tokens, local.argument_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.table_name_value_tokens, local.table_name_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.index_value_tokens, local.index_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.start_value_tokens, local.start_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.start_result_ref_value_tokens, local.start_result_ref_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.target_value_tokens, local.target_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.target_result_ref_value_tokens, local.target_result_ref_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.pattern_value_tokens, local.pattern_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.return_value_tokens, local.return_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.metric_value_tokens, local.metric_value_tokens);
    try validateGeneratedDmlReadBodyLocalRange(body_range, absolute.query_value_tokens, local.query_value_tokens);
}

fn lowerRecursiveWritePlanFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    write_kind: sql_statement_kind.SqlWriteStatementKind,
) !plan_mod.LoweredWritePlan {
    if (!ast.cte_recursive) return error.UnsupportedSqlShape;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    _ = try generatedDmlCommandStart(tokens, ast, end);
    try validateGeneratedRecursiveDmlCtePayloadAlloc(parsed_sql, ast, end);
    switch (ast.kind) {
        .insert_select => {
            if (write_kind != .insert_source) return error.UnsupportedSqlShape;
            try validateGeneratedInsertSourceRanges(tokens, ast, end);
            try validateGeneratedDmlReadSourceBodyAlloc(alloc, parsed_sql, ast);
            return .{ .recursive_insert_source = try recursiveInsertSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, ast, schema, params, options, end) };
        },
        .update => {
            switch (write_kind) {
                .update, .update_source => try validateGeneratedUpdateSourceRanges(tokens, ast, end),
                .update_joined_source => {
                    if (ast.source_tokens != null) {
                        try validateGeneratedUpdateJoinedRanges(tokens, ast, end);
                        try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);
                    } else {
                        try validateGeneratedUpdateSourceRanges(tokens, ast, end);
                    }
                },
                else => return error.UnsupportedSqlShape,
            }
            if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
            const source_schema = options.joined_source_schema orelse schema;
            if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
            const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
            if (row_claim.txn_id == null) return error.UnsupportedRowsQuery;
            return .{ .recursive_update_joined_source = try recursiveJoinedMutationSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, ast, schema, source_schema, params, row_claim, options.sync_level, .update, end) };
        },
        .delete => {
            switch (write_kind) {
                .delete, .delete_source => try validateGeneratedDeleteSourceRanges(tokens, ast, end),
                .delete_joined_source => {
                    if (ast.source_tokens != null) {
                        try validateGeneratedDeleteJoinedRanges(tokens, ast, end);
                        try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);
                    } else {
                        try validateGeneratedDeleteSourceRanges(tokens, ast, end);
                    }
                },
                else => return error.UnsupportedSqlShape,
            }
            if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
            const source_schema = options.joined_source_schema orelse schema;
            if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
            const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
            if (row_claim.txn_id == null) return error.UnsupportedRowsQuery;
            return .{ .recursive_delete_joined_source = try recursiveJoinedMutationSourceFromGeneratedDmlAstAlloc(alloc, parsed_sql, ast, schema, source_schema, params, row_claim, options.sync_level, .delete, end) };
        },
        .merge => {
            if (write_kind != .merge) return error.UnsupportedSqlShape;
            try validateGeneratedMergeRanges(tokens, ast, end);
            try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);
            if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
            const source_schema = options.joined_source_schema orelse schema;
            if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
            return .{ .recursive_merge_mutation = try recursiveMergeMutationFromGeneratedDmlAstAlloc(alloc, parsed_sql, ast, schema, source_schema, params, options.sync_level, end) };
        },
        .insert_values, .truncate => return error.UnsupportedSqlShape,
    }
}

fn recursiveInsertSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    end: usize,
) !plan_mod.LoweredRecursiveInsertSource {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const source_schema = options.insert_source_schema orelse schema;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
    const unique_resolver = options.unique_resolver orelse return error.UnsupportedRowsSelector;
    const tokens = parsed_sql.items();
    const start = try generatedDmlCommandStart(tokens, ast, end);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = source_schema,
        .insert_source_allows_different_table = true,
        .params = params,
        .unique_resolver = unique_resolver,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlFinalStatementReturningItems(&ast),
        .generated_assignment_items = &ast.conflict_assignment_items,
        .generated_conflict_assignments_tokens = ast.conflict_assignments_tokens,
        .generated_insert_column_items = &ast.insert_column_items,
        .generated_conflict_target_tokens = ast.conflict_target_tokens,
        .generated_conflict_target_kind = ast.conflict_target_kind,
        .generated_conflict_target_items = &ast.conflict_target_items,
        .generated_conflict_target_where_tokens = ast.conflict_target_where_tokens,
        .generated_conflict_target_where_expression = if (ast.conflict_target_where_tokens != null) &ast.conflict_target_where_expression else null,
        .generated_conflict_action_tokens = ast.conflict_action_tokens,
        .generated_conflict_action_kind = ast.conflict_action_kind,
        .generated_conflict_action_where_tokens = ast.conflict_action_where_tokens,
        .generated_conflict_action_where_expression = if (ast.conflict_action_where_tokens != null) &ast.conflict_action_where_expression else null,
    };
    var recursive = try plan_mod.parseRecursiveCteProducerAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        parser_context.ParserState.ContextAccessors.recursiveCteParserHooks(&parser_state),
    );
    errdefer recursive.deinit(alloc);
    if (parser.matchToken(tokens, &parser_state.pos, .comma) != null) return error.UnsupportedSqlShape;
    if (parser_state.pos != start) return error.UnsupportedSqlShape;

    var base_table_name: ?[]const u8 = try alloc.dupe(u8, recursive.anchor.table_name);
    defer if (base_table_name) |name| alloc.free(name);
    const recursive_ctes = [_]db_mod.types.RelationalRowsCte{.{
        .name = recursive.cte_name,
        .query = recursive.anchor.plan.query,
    }};
    var insert_source = parseInsertSourceWithCtesAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        parser_context.ParserState.ContextAccessors.insertSourceParserHooks(&parser_state),
        .{
            .ctes = recursive_ctes[0..],
            .base_table_name = &base_table_name,
        },
    ) catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer insert_source.deinit(alloc);
    if (!std.mem.eql(u8, insert_source.insert_source.req.source.source_cte, recursive.cte_name)) return error.UnsupportedSqlShape;
    if (insert_source.ctes.len != 0) return error.UnsupportedSqlShape;
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    insert_source.sync_level = options.sync_level;

    return .{
        .recursive = recursive,
        .insert_source = insert_source,
    };
}

fn recursiveJoinedMutationSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    row_claim: db_mod.types.RowClaimRequest,
    sync_level: db_mod.types.SyncLevel,
    kind: RecursiveJoinedMutationSourceKind,
    end: usize,
) !plan_mod.LoweredRecursiveJoinedMutationSource {
    const tokens = parsed_sql.items();
    const start = try generatedDmlCommandStart(tokens, ast, end);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = source_schema,
        .params = params,
        .mutation_claim = row_claim,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlFinalStatementReturningItems(&ast),
        .generated_assignment_items = if (kind == .update) &ast.assignment_items else null,
    };
    var recursive = try plan_mod.parseRecursiveCteProducerAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        parser_context.ParserState.ContextAccessors.recursiveCteParserHooks(&parser_state),
    );
    errdefer recursive.deinit(alloc);
    if (parser.matchToken(tokens, &parser_state.pos, .comma) != null) return error.UnsupportedSqlShape;
    if (parser_state.pos != start) return error.UnsupportedSqlShape;

    var base_table_name: ?[]const u8 = try alloc.dupe(u8, recursive.anchor.table_name);
    defer if (base_table_name) |name| alloc.free(name);
    const recursive_ctes = [_]db_mod.types.RelationalRowsCte{.{
        .name = recursive.cte_name,
        .query = recursive.anchor.plan.query,
    }};
    var mutation = switch (kind) {
        .update => parseUpdateJoinedMutationSourceWithCtesAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            try parser_context.ParserState.ContextAccessors.updateJoinedMutationSourceParserOptions(&parser_state, recursive_ctes[0..], &base_table_name),
        ),
        .delete => parseDeleteJoinedMutationSourceWithCtesAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            try parser_context.ParserState.ContextAccessors.deleteJoinedMutationSourceParserOptions(&parser_state, recursive_ctes[0..], &base_table_name),
        ),
    } catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer mutation.deinit(alloc);
    if (!recursiveJoinedMutationSourceUsesCte(mutation.mutation.req, recursive.cte_name)) return error.UnsupportedSqlShape;
    if (mutation.mutation.req.ctes.len == 0) return error.UnsupportedSqlShape;
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    mutation.sync_level = sync_level;

    return .{
        .recursive = recursive,
        .mutation = mutation,
    };
}

fn recursiveMergeMutationFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
