    var recursive = try plan_mod.parseRecursiveCteProducerAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        parser_context.ParserState.ContextAccessors.recursiveCteParserHooks(&parser_state),
    );
    errdefer recursive.deinit(alloc);
    if (parser.matchToken(tokens, &parser_state.pos, .comma) != null) return error.UnsupportedSqlShape;
    if (parser_state.pos != start) return error.UnsupportedSqlShape;

    var base_table_name: ?[]const u8 = try alloc.dupe(u8, recursive.anchor.table_name);
    defer if (base_table_name) |name| alloc.free(name);
    const recursive_ctes = [_]db_mod.types.RelationalRowsCte{.{
        .name = recursive.cte_name,
        .query = recursive.anchor.plan.query,
    }};
    var merge = parseMergeMutationBodyAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        parser_context.ParserState.ContextAccessors.mergeMutationParserOptions(&parser_state),
        .{
            .ctes = recursive_ctes[0..],
            .base_table_name = &base_table_name,
        },
    ) catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer merge.deinit(alloc);
    if (!std.mem.eql(u8, merge.source.source_cte, recursive.cte_name)) return error.UnsupportedSqlShape;
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    merge.sync_level = sync_level;

    return .{
        .recursive = recursive,
        .merge = merge,
    };
}

fn validateGeneratedRecursiveDmlCtePayloadAlloc(
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    if (!ast.cte_recursive) return error.UnsupportedSqlShape;
    const tokens = parsed_sql.items();
    const cte_tokens = ast.cte_tokens orelse return error.UnsupportedSqlShape;
    const cte_prefix = ast.cte_prefix orelse return error.UnsupportedSqlShape;
    if (cte_tokens.start != 1 or cte_tokens.end >= end or cte_tokens.start >= cte_tokens.end) return error.UnsupportedSqlShape;
    if (cte_prefix.tokens.start != cte_tokens.start or cte_prefix.tokens.end != cte_tokens.end) return error.UnsupportedSqlShape;
    const cte_list_tokens = cte_prefix.list_tokens;
    if (cte_list_tokens.start <= cte_tokens.start or cte_list_tokens.end != cte_tokens.end or cte_list_tokens.start >= cte_list_tokens.end) return error.UnsupportedSqlShape;
    if (cte_prefix.count == 0 or !cte_prefix.recursive) return error.UnsupportedSqlShape;
    if (cte_prefix.items.len != cte_prefix.count) return error.UnsupportedSqlShape;
    if (cte_prefix.items.len == 0) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(cte_prefix.first_name_tokens, cte_prefix.items[0].name_tokens) or
        !generatedDmlTokenRangeEql(cte_prefix.first_body_tokens, cte_prefix.items[0].body_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlCteBodyBoundaryMirror(tokens, cte_prefix.items[0], cte_prefix.first_body_read, cte_prefix.first_body_dml);
    const last = cte_prefix.items[cte_prefix.items.len - 1];
    if (!generatedDmlTokenRangeEql(cte_prefix.last_name_tokens, last.name_tokens) or
        !generatedDmlTokenRangeEql(cte_prefix.last_body_tokens, last.body_tokens))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlCteBodyBoundaryMirror(tokens, last, cte_prefix.last_body_read, cte_prefix.last_body_dml);
    var previous_end = cte_list_tokens.start;
    for (cte_prefix.items, 0..) |item, item_index| {
        if (item.name_tokens.start != previous_end or
            item.name_tokens.end > cte_list_tokens.end or
            item.name_tokens.start >= item.name_tokens.end)
        {
            return error.UnsupportedSqlShape;
        }
        if (item.body_tokens.start <= item.name_tokens.end or
            item.body_tokens.end > cte_list_tokens.end or
            item.body_tokens.start >= item.body_tokens.end)
        {
            return error.UnsupportedSqlShape;
        }
        const item_end = try validateGeneratedRecursiveDmlCteItemLayout(tokens, cte_list_tokens, item);
        if (item_index + 1 < cte_prefix.items.len) {
            if (item_end >= cte_list_tokens.end or tokens[item_end].kind != .comma) return error.UnsupportedSqlShape;
            previous_end = item_end + 1;
        } else if (item_end != cte_list_tokens.end) {
            return error.UnsupportedSqlShape;
        }
        const body_read = item.body_read orelse return error.UnsupportedSqlShape;
        if (item.body_dml != null) return error.UnsupportedSqlShape;
        try validateGeneratedDmlReadBodyLayout(tokens, item.body_tokens, body_read);
        try validateGeneratedDmlReadBodyReadAst(tokens, item.body_tokens, body_read);
    }
}

fn validateGeneratedRecursiveDmlCteItemLayout(
    tokens: []const Token,
    cte_list_tokens: generated_parser.GeneratedSqlTokenRange,
    item: generated_parser.GeneratedSqlDmlCteItemAst,
) !usize {
    if (item.name_tokens.end != item.name_tokens.start + 1 or item.name_tokens.end > cte_list_tokens.end) return error.UnsupportedSqlShape;
    if (tokens[item.name_tokens.start].kind != .identifier) return error.UnsupportedSqlShape;

    var index = item.name_tokens.end;
    if (index < cte_list_tokens.end and tokens[index].kind == .lparen) {
        const close = parser.findMatchingRParenIndex(tokens, index) orelse return error.UnsupportedSqlShape;
        if (close >= item.body_tokens.start) return error.UnsupportedSqlShape;
        index = close + 1;
    }
    if (index >= item.body_tokens.start or !tokens[index].matchesKeywordTag(.as)) return error.UnsupportedSqlShape;
    index += 1;
    if (index < item.body_tokens.start and tokens[index].matchesKeywordTag(.materialized)) {
        index += 1;
    } else if (index + 1 < item.body_tokens.start and tokens[index].matchesKeywordTag(.not) and tokens[index + 1].matchesKeywordTag(.materialized)) {
        index += 2;
    }
    if (index + 1 != item.body_tokens.start or tokens[index].kind != .lparen) return error.UnsupportedSqlShape;
    if (item.body_tokens.end >= cte_list_tokens.end or tokens[item.body_tokens.end].kind != .rparen) return error.UnsupportedSqlShape;
    return item.body_tokens.end + 1;
}

fn generatedDmlTokenRangeEql(a: generated_parser.GeneratedSqlTokenRange, b: generated_parser.GeneratedSqlTokenRange) bool {
    return a.start == b.start and a.end == b.end;
}

fn validateGeneratedDmlListItemsRange(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    list: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (list.count == 0 or list.items.len != list.count) return error.UnsupportedSqlShape;
    if (list.expression_items.len != list.count or list.expressions.len != list.count) return error.UnsupportedSqlShape;
    if (list.alias_items.len != list.count or list.alias_name_items.len != list.count) return error.UnsupportedSqlShape;
    if (list.direction_items.len != list.count or list.directions.len != list.count) return error.UnsupportedSqlShape;
    if (list.order_using_operator_items.len != list.count or list.nulls_order_items.len != list.count or list.nulls_orders.len != list.count) return error.UnsupportedSqlShape;
    if (list.first_tokens == null or list.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.first_tokens.?, list.items[0])) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.last_tokens.?, list.items[list.count - 1])) return error.UnsupportedSqlShape;
    var expected_start = range.start;
    for (list.items, 0..) |item, index| {
        if (item.start != expected_start or item.start >= item.end or item.end > range.end) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(list.expression_items[index], item)) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(list.expressions[index].tokens orelse return error.UnsupportedSqlShape, item)) return error.UnsupportedSqlShape;
        if (list.alias_items[index] != null or
            list.alias_name_items[index] != null or
            list.direction_items[index] != null or
            list.directions[index] != null or
            list.order_using_operator_items[index] != null or
            list.nulls_order_items[index] != null or
            list.nulls_orders[index] != null)
        {
            return error.UnsupportedSqlShape;
        }
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, item, list.expressions[index]);
        expected_start = item.end;
        if (index + 1 < list.count) {
            if (expected_start >= range.end or tokens[expected_start].kind != .comma) return error.UnsupportedSqlShape;
            expected_start += 1;
        }
    }
    if (expected_start != range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlCommaPrefixedIdentifierListItemsRange(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    list: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (list.count == 0 or list.items.len != list.count) return error.UnsupportedSqlShape;
    if (list.expression_items.len != list.count or list.expressions.len != list.count) return error.UnsupportedSqlShape;
    if (list.alias_items.len != list.count or list.alias_name_items.len != list.count) return error.UnsupportedSqlShape;
    if (list.direction_items.len != list.count or list.directions.len != list.count) return error.UnsupportedSqlShape;
    if (list.order_using_operator_items.len != list.count or list.nulls_order_items.len != list.count or list.nulls_orders.len != list.count) return error.UnsupportedSqlShape;
    if (list.first_tokens == null or list.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.first_tokens.?, list.items[0])) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(list.last_tokens.?, list.items[list.count - 1])) return error.UnsupportedSqlShape;
    var expected_comma = range.start;
    for (list.items, 0..) |item, index| {
        if (expected_comma >= range.end or tokens[expected_comma].kind != .comma) return error.UnsupportedSqlShape;
        if (item.start != expected_comma + 1 or item.start >= item.end or item.end > range.end) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(list.expression_items[index], item)) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(list.expressions[index].tokens orelse return error.UnsupportedSqlShape, item)) return error.UnsupportedSqlShape;
        if (list.alias_items[index] != null or
            list.alias_name_items[index] != null or
            list.direction_items[index] != null or
            list.directions[index] != null or
            list.order_using_operator_items[index] != null or
            list.nulls_order_items[index] != null or
            list.nulls_orders[index] != null)
        {
            return error.UnsupportedSqlShape;
        }
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, item, list.expressions[index]);
        expected_comma = item.end;
    }
    if (expected_comma != range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlEmptyList(list: *const generated_parser.GeneratedSqlListAst) !void {
    if (list.count != 0 or
        list.first_tokens != null or
        list.last_tokens != null or
        list.items.len != 0 or
        list.expression_items.len != 0 or
        list.alias_items.len != 0 or
        list.alias_name_items.len != 0 or
        list.direction_items.len != 0 or
        list.directions.len != 0 or
        list.order_using_operator_items.len != 0 or
        list.nulls_order_items.len != 0 or
        list.nulls_orders.len != 0 or
        list.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedDmlReturningItemsRange(
    tokens: []const Token,
    returning_tokens: ?generated_parser.GeneratedSqlTokenRange,
    returning_items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (returning_tokens) |range| {
        if (range.start == 0 or
            range.start >= range.end or
            range.end > tokens.len or
            !tokens[range.start - 1].matchesKeywordTag(.returning))
        {
            return error.UnsupportedSqlShape;
        }
        try generated_read_validate.validateGeneratedProjectionListForClause(tokens, range, returning_items.*);
    } else {
        try validateGeneratedDmlEmptyList(returning_items);
    }
}

fn validateGeneratedDmlReturningHookRange(
    tokens: []const Token,
    pos: usize,
    generated_dml_ast: ?*const generated_parser.GeneratedSqlDmlAst,
    generated_returning_items: ?*const generated_parser.GeneratedSqlListAst,
) !?generated_parser.GeneratedSqlTokenRange {
    const ast = generated_dml_ast orelse {
        if (generated_returning_items != null) return error.UnsupportedSqlShape;
        return null;
    };
    const returning_items = generated_returning_items orelse return error.UnsupportedSqlShape;
    const range = ast.returning_tokens orelse return error.UnsupportedSqlShape;
    if (range.start != pos) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReturningItemsRange(tokens, range, returning_items);
    return range;
}

fn validateGeneratedDmlNoConflictMetadata(ast: generated_parser.GeneratedSqlDmlAst) !void {
    if (ast.conflict_tokens != null or
        ast.conflict_target_tokens != null or
        ast.conflict_target_kind != null or
        ast.conflict_action_tokens != null or
        ast.conflict_action_kind != null or
        ast.conflict_assignments_tokens != null or
        ast.conflict_target_where_tokens != null or
        ast.conflict_action_where_tokens != null)
    {
        return error.UnsupportedSqlShape;
    }
    try generated_read_validate.validateGeneratedOptionalExpression(&.{}, null, ast.conflict_target_where_expression);
    try generated_read_validate.validateGeneratedOptionalExpression(&.{}, null, ast.conflict_action_where_expression);
    try validateGeneratedDmlEmptyList(&ast.conflict_target_items);
    try validateGeneratedDmlEmptyList(&ast.conflict_assignment_items);
}

fn generatedDmlTopLevelReturningItems(ast: *const generated_parser.GeneratedSqlDmlAst) ?*const generated_parser.GeneratedSqlListAst {
    if (ast.returning_tokens == null or ast.cte_tokens != null) return null;
    return &ast.returning_items;
}

fn generatedDmlFinalStatementReturningItems(ast: *const generated_parser.GeneratedSqlDmlAst) ?*const generated_parser.GeneratedSqlListAst {
    if (ast.returning_tokens == null) return null;
    return &ast.returning_items;
}

fn generatedDmlTopLevelOnConflictKeyword(tokens: []const Token, start: usize, end: usize) ?usize {
    if (start >= end or end > tokens.len) return null;
    var depth: usize = 0;
    var index = start;
    while (index + 2 < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .semicolon => if (depth == 0) return null,
            else => {},
        }
        if (depth != 0 or !tokens[index].matchesKeywordTag(.on) or !tokens[index + 1].matchesKeywordTag(.conflict)) continue;
        if (tokens[index + 2].kind == .lparen or tokens[index + 2].matchesKeywordTag(.on) or tokens[index + 2].matchesKeywordTag(.do)) return index;
    }
    return null;
}

fn generatedDmlConflictKeywordFromAst(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    search_start: usize,
    end: usize,
) !?usize {
    const actual_conflict = generatedDmlTopLevelOnConflictKeyword(tokens, search_start, end);
    if (ast.conflict_tokens) |conflict_range| {
        if (conflict_range.start == 0 or conflict_range.start > conflict_range.end or conflict_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[conflict_range.start - 1].matchesKeywordTag(.on) or !tokens[conflict_range.start].matchesKeywordTag(.conflict)) return error.UnsupportedSqlShape;
        const conflict_start = conflict_range.start - 1;
        if (actual_conflict == null or actual_conflict.? != conflict_start) return error.UnsupportedSqlShape;
        return conflict_start;
    }
    if (actual_conflict != null) return error.UnsupportedSqlShape;
    return null;
}

fn validateGeneratedInsertConflictMetadata(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    conflict_range: generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !void {
    if (ast.kind != .insert_values and ast.kind != .insert_select) return error.UnsupportedSqlShape;
    if (conflict_range.start == 0 or conflict_range.start >= conflict_range.end or conflict_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[conflict_range.start - 1].matchesKeywordTag(.on) or !tokens[conflict_range.start].matchesKeywordTag(.conflict)) return error.UnsupportedSqlShape;

    var cursor = conflict_range.start + 1;
    const target_kind = ast.conflict_target_kind orelse return error.UnsupportedSqlShape;
    switch (target_kind) {
        .targetless => {
            if (ast.conflict_target_tokens != null or ast.conflict_target_where_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&ast.conflict_target_items);
        },
        .inference => {
            const target = ast.conflict_target_tokens orelse return error.UnsupportedSqlShape;
            if (target.start != cursor or target.end > conflict_range.end or tokens[target.start].kind != .lparen) return error.UnsupportedSqlShape;
            const close = parser.findMatchingRParenIndex(tokens, target.start) orelse return error.UnsupportedSqlShape;
            if (close >= conflict_range.end or target.end != close + 1) return error.UnsupportedSqlShape;
            try validateGeneratedDmlListItemsRange(tokens, .{ .start = target.start + 1, .end = target.end - 1 }, &ast.conflict_target_items);
            cursor = target.end;
        },
        .constraint => {
            const target = ast.conflict_target_tokens orelse return error.UnsupportedSqlShape;
            if (target.start != cursor or target.end > conflict_range.end) return error.UnsupportedSqlShape;
            if (target.end != target.start + 3 or
                !tokens[target.start].matchesKeywordTag(.on) or
                !tokens[target.start + 1].matchesKeywordTag(.constraint) or
                tokens[target.start + 2].kind != .identifier)
            {
                return error.UnsupportedSqlShape;
            }
            try validateGeneratedDmlEmptyList(&ast.conflict_target_items);
            cursor = target.end;
        },
    }

    if (ast.conflict_target_where_tokens) |where| {
        if (target_kind != .inference) return error.UnsupportedSqlShape;
        if (where.start != cursor + 1 or where.start >= where.end or where.end > conflict_range.end) return error.UnsupportedSqlShape;
        if (!tokens[cursor].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(ast.conflict_target_where_expression.tokens orelse return error.UnsupportedSqlShape, where)) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, where, ast.conflict_target_where_expression);
        const do_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..conflict_range.end], where.end, .do) orelse return error.UnsupportedSqlShape;
        if (do_index != where.end) return error.UnsupportedSqlShape;
        cursor = do_index;
    } else {
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.conflict_target_where_expression);
    }

    if (cursor >= conflict_range.end or !tokens[cursor].matchesKeywordTag(.do)) return error.UnsupportedSqlShape;
    const action = ast.conflict_action_tokens orelse return error.UnsupportedSqlShape;
    if (action.start != cursor + 1 or action.start >= action.end or action.end != conflict_range.end) return error.UnsupportedSqlShape;
    const action_kind = ast.conflict_action_kind orelse return error.UnsupportedSqlShape;
    switch (action_kind) {
        .nothing => {
            if (!tokens[action.start].matchesKeywordTag(.nothing)) return error.UnsupportedSqlShape;
            if (action.end != action.start + 1 or ast.conflict_assignments_tokens != null or ast.conflict_action_where_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&ast.conflict_assignment_items);
            try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.conflict_action_where_expression);
            return;
        },
        .update => {
            if (target_kind == .targetless) return error.UnsupportedSqlShape;
            if (!tokens[action.start].matchesKeywordTag(.update) or action.start + 1 >= action.end or !tokens[action.start + 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
        },
    }
    if (!tokens[action.start].matchesKeywordTag(.update) or action.start + 1 >= action.end or !tokens[action.start + 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    const assignments = ast.conflict_assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments.start != action.start + 2 or assignments.start >= assignments.end or assignments.end > action.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, assignments, &ast.conflict_assignment_items);
    if (parser.findTopLevelKeywordTagFromIndex(tokens[0..action.end], assignments.start, .where)) |where_index| {
        if (assignments.end != where_index) return error.UnsupportedSqlShape;
        const where = ast.conflict_action_where_tokens orelse return error.UnsupportedSqlShape;
        if (where.start != where_index + 1 or where.start >= where.end or where.end != action.end) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(ast.conflict_action_where_expression.tokens orelse return error.UnsupportedSqlShape, where)) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, where, ast.conflict_action_where_expression);
    } else {
        if (assignments.end != action.end or ast.conflict_action_where_tokens != null) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.conflict_action_where_expression);
    }
}

fn insertValuesFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredInsert {
    return try insertValuesFromGeneratedDmlAstWithFunctionBindingsAlloc(alloc, tokens, ast, schema, params, options, .{});
}

fn insertValuesFromGeneratedDmlAstWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !plan_mod.LoweredInsert {
    if (ast.kind != .insert_values) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    if (ast.source_tokens != null) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 4 >= end or !tokens[start].matchesKeywordTag(.insert) or !tokens[start + 1].matchesKeywordTag(.into)) return error.UnsupportedSqlShape;
    const target_start = try generatedInsertTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    var table_transferred = false;
    errdefer if (!table_transferred) plan_mod.freeTableAlias(alloc, target_table);
    const table_name = target_table.name;
    const returning_start = if (ast.returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0 or returning_range.start > returning_range.end or returning_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[returning_range.start - 1].matchesKeywordTag(.returning)) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else null;
    const conflict_start = try generatedDmlConflictKeywordFromAst(tokens, ast, target_alias_end, end);
    const body_end = conflict_start orelse returning_start orelse end;
    const actual_returning_keyword = parser.findTopLevelKeywordTagFromIndex(tokens[0..end], target_alias_end, .returning);
    if (actual_returning_keyword) |actual_returning| {
        if (returning_start == null or returning_start.? != actual_returning) return error.UnsupportedSqlShape;
    } else if (returning_start != null) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReturningItemsRange(tokens, ast.returning_tokens, &ast.returning_items);
    if (returning_start) |returning| {
        if (conflict_start) |conflict| {
            if (conflict >= returning) return error.UnsupportedSqlShape;
        }
    }
    if (ast.conflict_tokens) |conflict_range| {
        if (conflict_range.start == 0 or conflict_range.start > conflict_range.end or conflict_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[conflict_range.start - 1].matchesKeywordTag(.on) or !tokens[conflict_range.start].matchesKeywordTag(.conflict)) return error.UnsupportedSqlShape;
        if (ast.returning_tokens) |returning_range| {
            if (conflict_range.end != returning_range.start - 1) return error.UnsupportedSqlShape;
        } else if (conflict_range.end != end) return error.UnsupportedSqlShape;
        try validateGeneratedInsertConflictMetadata(tokens, ast, conflict_range, end);
    } else {
        try validateGeneratedDmlNoConflictMetadata(ast);
    }

    var columns: []const []const u8 = &.{};
    var owns_columns = false;
    errdefer if (owns_columns) {
        for (columns) |column| alloc.free(column);
        alloc.free(columns);
    };
    var column_specs = std.ArrayListUnmanaged(InsertColumnSpec).empty;
    defer column_specs.deinit(alloc);
    var rows: []const []const []const u8 = &.{};
    var owns_rows = false;
    errdefer if (owns_rows) {
        freeInsertValueRows(alloc, rows);
        alloc.free(rows);
    };
    var default_row = [_][]const u8{};
    var default_rows = [_][]const []const u8{default_row[0..]};
    if (ast.default_values) {
        if (ast.insert_columns_tokens != null or ast.values_tokens != null) return error.UnsupportedSqlShape;
        if (body_end != target_alias_end + 2 or !tokens[target_alias_end].matchesKeywordTag(.default) or !tokens[target_alias_end + 1].matchesKeywordTag(.values)) return error.UnsupportedSqlShape;
        rows = default_rows[0..];
    } else {
        const column_range = ast.insert_columns_tokens orelse return error.UnsupportedSqlShape;
        if (column_range.start != target_alias_end) return error.UnsupportedSqlShape;
        columns = try generatedInsertColumnsAlloc(alloc, tokens, column_range, &ast.insert_column_items, schema, &column_specs);
        owns_columns = true;
        try validateSqlInsertColumnsUnique(schema, columns);

        const values_range = ast.values_tokens orelse return error.UnsupportedSqlShape;
        if (values_range.start == 0 or values_range.start >= values_range.end or values_range.end > end) return error.UnsupportedSqlShape;
        if (values_range.start != column_range.end + 1) return error.UnsupportedSqlShape;
        if (!tokens[values_range.start - 1].matchesKeywordTag(.values)) return error.UnsupportedSqlShape;
        if (values_range.end != body_end) return error.UnsupportedSqlShape;
        rows = try generatedInsertValueRowsAlloc(alloc, tokens, values_range, &ast.insert_value_rows, columns, column_specs.items, schema, params);
        owns_rows = true;
    }
    var conflicts = std.ArrayListUnmanaged(ConflictClause).empty;
    errdefer {
        freeConflictClauses(alloc, conflicts.items);
        conflicts.deinit(alloc);
    }
    var conflict_where = false;
    if (ast.conflict_tokens) |conflict_range| {
        const parser_context = @import("parser_context.zig");
        var parser_state = parser_context.ParserState{
            .alloc = alloc,
            .tokens = tokens,
            .schema = schema,
            .params = params,
            .unique_resolver = options.unique_resolver,
            .default_context = options.default_context,
            .function_bindings = function_bindings,
            .generated_assignment_items = &ast.conflict_assignment_items,
            .generated_conflict_assignments_tokens = ast.conflict_assignments_tokens,
            .generated_conflict_target_tokens = ast.conflict_target_tokens,
            .generated_conflict_target_kind = ast.conflict_target_kind,
            .generated_conflict_target_items = &ast.conflict_target_items,
            .generated_conflict_target_where_tokens = ast.conflict_target_where_tokens,
            .generated_conflict_target_where_expression = if (ast.conflict_target_where_tokens != null) &ast.conflict_target_where_expression else null,
            .generated_conflict_action_tokens = ast.conflict_action_tokens,
            .generated_conflict_action_kind = ast.conflict_action_kind,
            .generated_conflict_action_where_tokens = ast.conflict_action_where_tokens,
            .generated_conflict_action_where_expression = if (ast.conflict_action_where_tokens != null) &ast.conflict_action_where_expression else null,
        };
        const insert_options = parser_context.ParserState.ContextAccessors.insertParserOptions(&parser_state);
        const conflict_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        const scoped_tokens = tokens[0..conflict_range.end];
        var after_conflict_pos: ?usize = null;
        for (rows) |row| {
            var conflict_pos = conflict_range.start;
            const conflict = try parseInsertConflictClauseAlloc(
                alloc,
                scoped_tokens,
                &conflict_pos,
                table_name,
                &conflict_qualifiers,
                columns,
                row,
                insert_options,
            );
            var conflict_transferred = false;
            errdefer if (!conflict_transferred) freeConflictClause(alloc, conflict);
            if (conflict.where_expression != null or conflict.where_expressions.len != 0 or conflict.where_any.len != 0 or conflict.where_not.len != 0) conflict_where = true;
            try conflicts.append(alloc, conflict);
            conflict_transferred = true;
            if (conflict_pos != conflict_range.end) return error.UnsupportedSqlShape;
            if (after_conflict_pos) |expected_pos| {
                if (conflict_pos != expected_pos) return error.UnsupportedSqlShape;
            } else {
                after_conflict_pos = conflict_pos;
            }
        }
        try rejectDuplicateConflictUpdateTargets(alloc, schema, columns, rows, conflicts.items);
    }
    var returning: plan_mod.ReturningProjection = .{};
    errdefer returning.deinit(alloc);
    if (ast.returning_tokens) |returning_range| {
        const parser_context = @import("parser_context.zig");
        var parser_state = parser_context.ParserState{
            .alloc = alloc,
            .tokens = tokens,
            .schema = schema,
            .params = params,
            .function_bindings = function_bindings,
        };
        parser_state.pos = returning_range.start;
        const returning_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        returning = generatedReturningProjectionAlloc(
            alloc,
            tokens,
            returning_range,
            schema,
            &returning_qualifiers,
            &parser_state.pos,
            &ast.returning_items,
            parser_context.ParserState.ContextAccessors.returningProjectionParserOptions(&parser_state),
        ) catch |err| {
            std.log.err("generated insert values returning parse failed table={s} err={}", .{ table_name, err });
            return err;
        };
    }
    const returning_expression_count = returning.expressions.len;
    const returning_all = returning.returnsAll();

    const body_json = try insertBodyJsonAlloc(alloc, columns, rows, conflicts.items, returning);
    defer alloc.free(body_json);
    var batch = if (conflicts.items.len != 0)
        parseRowsBatchRequestWithWriteOptionsAlloc(alloc, table_name, body_json, schema, options.unique_resolver orelse return error.UnsupportedRowsSelector, options.default_context) catch |err| {
            std.log.err("generated insert values rows batch parse failed table={s} err={} body={s}", .{ table_name, err, body_json });
            return err;
        }
    else
        parseRowsBatchRequestWithWriteOptionsAlloc(alloc, table_name, body_json, schema, null, options.default_context) catch |err| {
            std.log.err("generated insert values rows batch parse failed table={s} err={} body={s}", .{ table_name, err, body_json });
            return err;
        };
    errdefer batch.deinit(alloc);
    batch.req.sync_level = options.sync_level;

    if (owns_columns) {
        for (columns) |column| alloc.free(column);
        alloc.free(columns);
        owns_columns = false;
    }
    if (owns_rows) {
        freeInsertValueRows(alloc, rows);
        alloc.free(rows);
        owns_rows = false;
    }
    freeConflictClauses(alloc, conflicts.items);
    conflicts.deinit(alloc);

    const owned_table_name = target_table.name;
    alloc.free(target_table.alias);
    table_transferred = true;
    const owned_returning = returning;
    returning = .{};
    return .{
        .table_name = owned_table_name,
        .batch = batch,
        .sync_level = options.sync_level,
        .returning = owned_returning,
        .returning_expression_count = returning_expression_count,
        .returning_all = returning_all,
        .conflict_where = conflict_where,
    };
}

fn insertSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredInsertSource {
    if (ast.kind != .insert_select) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const unique_resolver = options.unique_resolver orelse return error.UnsupportedRowsSelector;
    const source_schema = options.insert_source_schema orelse schema;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedInsertSourceRanges(tokens, ast, end);
    try validateGeneratedDmlReadSourceBodyAlloc(alloc, parsed_sql, ast);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = options.insert_source_schema,
        .insert_source_allows_different_table = options.insert_source_schema != null,
        .params = params,
        .unique_resolver = unique_resolver,
        .default_context = options.default_context,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
        .generated_assignment_items = &ast.conflict_assignment_items,
        .generated_conflict_assignments_tokens = ast.conflict_assignments_tokens,
        .generated_insert_column_items = &ast.insert_column_items,
        .generated_conflict_target_tokens = ast.conflict_target_tokens,
        .generated_conflict_target_kind = ast.conflict_target_kind,
        .generated_conflict_target_items = &ast.conflict_target_items,
        .generated_conflict_target_where_tokens = ast.conflict_target_where_tokens,
        .generated_conflict_target_where_expression = if (ast.conflict_target_where_tokens != null) &ast.conflict_target_where_expression else null,
        .generated_conflict_action_tokens = ast.conflict_action_tokens,
        .generated_conflict_action_kind = ast.conflict_action_kind,
        .generated_conflict_action_where_tokens = ast.conflict_action_where_tokens,
        .generated_conflict_action_where_expression = if (ast.conflict_action_where_tokens != null) &ast.conflict_action_where_expression else null,
    };
    var lowered = blk: {
        if (!parser.peekKeywordTag(tokens, parser_state.pos, .with)) {
            break :blk parseInsertSourceWithCtesAlloc(alloc, tokens, &parser_state.pos, parser_context.ParserState.ContextAccessors.insertSourceParserHooks(&parser_state), .{
                .ctes = &.{},
                .base_table_name = null,
            });
        }

        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        var ctes = try plan_mod.parseCtesForPlanAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            &base_table_name,
            parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
        );
        errdefer plan_mod.freePlanCtes(alloc, ctes);

        parser_state.generated_returning_items = generatedDmlFinalStatementReturningItems(&ast);
        var lowered_with_ctes = try parseInsertSourceWithCtesAlloc(alloc, tokens, &parser_state.pos, parser_context.ParserState.ContextAccessors.insertSourceParserHooks(&parser_state), .{
            .ctes = ctes,
            .base_table_name = &base_table_name,
        });
        errdefer lowered_with_ctes.deinit(alloc);
        lowered_with_ctes.ctes = ctes;
        ctes = &.{};
        break :blk lowered_with_ctes;
    } catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn validateGeneratedInsertSourceRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 5 >= end or !tokens[start].matchesKeywordTag(.insert) or !tokens[start + 1].matchesKeywordTag(.into)) return error.UnsupportedSqlShape;
    const target_start = try generatedInsertTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const column_range = ast.insert_columns_tokens orelse return error.UnsupportedSqlShape;
    if (column_range.start != target_range.end or column_range.end <= column_range.start + 1 or column_range.end > end) return error.UnsupportedSqlShape;
    if (tokens[column_range.start].kind != .lparen or tokens[column_range.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    if (ast.values_tokens != null or ast.default_values) return error.UnsupportedSqlShape;
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    if (source_range.start != column_range.end or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[source_range.start].matchesKeywordTag(.select)) return error.UnsupportedSqlShape;

    const returning_keyword = if (ast.returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0 or returning_range.start > returning_range.end or returning_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[returning_range.start - 1].matchesKeywordTag(.returning)) return error.UnsupportedSqlShape;
        if (returning_range.end != end) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else null;
    const conflict_start = try generatedDmlConflictKeywordFromAst(tokens, ast, source_range.start, end);
    const actual_returning_keyword = parser.findTopLevelKeywordTagFromIndex(tokens[0..end], source_range.start, .returning);
    if (actual_returning_keyword) |actual_returning| {
        if (returning_keyword == null or returning_keyword.? != actual_returning) return error.UnsupportedSqlShape;
    } else if (returning_keyword != null) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReturningItemsRange(tokens, ast.returning_tokens, &ast.returning_items);
    if (ast.conflict_tokens) |conflict_range| {
        if (conflict_range.start == 0 or conflict_range.start > conflict_range.end or conflict_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[conflict_range.start - 1].matchesKeywordTag(.on) or !tokens[conflict_range.start].matchesKeywordTag(.conflict)) return error.UnsupportedSqlShape;
        if (conflict_start == null or conflict_start.? != conflict_range.start - 1) return error.UnsupportedSqlShape;
        if (source_range.end != conflict_range.start - 1) return error.UnsupportedSqlShape;
        if (returning_keyword) |returning_start| {
            if (conflict_range.end != returning_start) return error.UnsupportedSqlShape;
        } else if (conflict_range.end != end) return error.UnsupportedSqlShape;
        try validateGeneratedInsertConflictMetadata(tokens, ast, conflict_range, end);
    } else if (returning_keyword) |returning_start| {
        try validateGeneratedDmlNoConflictMetadata(ast);
        if (source_range.end != returning_start) return error.UnsupportedSqlShape;
    } else {
        try validateGeneratedDmlNoConflictMetadata(ast);
        if (source_range.end != end) return error.UnsupportedSqlShape;
    }
}

fn generatedInsertTargetTableStart(tokens: []const Token, start: usize, end: usize) !usize {
    if (start + 2 >= end) return error.UnsupportedSqlShape;
    if (tokens[start + 2].matchesKeywordTag(.only)) {
        if (start + 3 >= end) return error.UnsupportedSqlShape;
        return start + 3;
    }
    return start + 2;
}

fn generatedUpdateTargetTableStart(tokens: []const Token, start: usize, end: usize) !usize {
    if (start + 1 >= end) return error.UnsupportedSqlShape;
    if (tokens[start + 1].matchesKeywordTag(.only)) {
        if (start + 2 >= end) return error.UnsupportedSqlShape;
        return start + 2;
    }
    return start + 1;
}

fn generatedDeleteTargetTableStart(tokens: []const Token, start: usize, end: usize) !usize {
    if (start + 2 >= end or !tokens[start + 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    if (tokens[start + 2].matchesKeywordTag(.only)) {
        if (start + 3 >= end) return error.UnsupportedSqlShape;
        return start + 3;
    }
    return start + 2;
}

fn generatedDmlOptionalOnlyTargetStart(tokens: []const Token, start: usize, end: usize) usize {
    return if (start < end and tokens[start].matchesKeywordTag(.only)) start + 1 else start;
}

fn validateGeneratedDmlRelationSourceBody(
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    try validateGeneratedDmlRelationSourceBodyAst(parsed_sql.items(), ast);
}

fn validateGeneratedDmlRelationSourceBodyAst(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    const source_read = ast.source_read orelse return error.UnsupportedSqlShape;
    if (source_range.start >= source_range.end or source_range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!source_read.wrapper_projection_star) return error.UnsupportedSqlShape;
    if (source_read.read_ast != null) return error.UnsupportedSqlShape;
    if (source_read.tokens.start != source_range.start or source_read.tokens.end != source_range.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodySpans(tokens, source_range, source_read);
    const read_source_range = source_read.source_tokens orelse return error.UnsupportedSqlShape;
    if (read_source_range.start != source_range.start or read_source_range.end != source_range.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReadBodySystemTimePayload(
        tokens,
        source_read.source_tokens,
        source_read.source_system_time_tokens,
        source_read.source_system_time_sequence_tokens,
    );
    try validateGeneratedDmlReadBodyTableFunctionPayloads(
        tokens,
        source_read.source_tokens,
        source_read.source_antfly_function_items,
        source_read.source_antfly_function_count,
        source_read.source_graph_function_items,
        source_read.source_graph_function_count,
    );
    try validateGeneratedDmlReadBodySingleSourceAlias(tokens, source_read);
    if (source_read.projection_tokens != null or source_read.where_tokens != null or source_read.set_operation_tokens != null) return error.UnsupportedSqlShape;
    if (source_read.kind != generatedDmlRelationSourceReadKind(tokens, source_range)) return error.UnsupportedSqlShape;
}

fn generatedDmlRelationSourceReadKind(
    tokens: []const Token,
    source_range: generated_parser.GeneratedSqlTokenRange,
) generated_parser.GeneratedSqlReadKind {
    var index = source_range.start;
    while (index < source_range.end) : (index += 1) {
        if (tokens[index].matchesKeywordTag(.lateral)) return .lateral;
    }
    index = source_range.start;
    while (index < source_range.end) : (index += 1) {
        if (tokens[index].matchesKeywordTag(.join)) return .join;
    }
    return .query;
}

fn updateSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    write_kind: sql_statement_kind.SqlWriteStatementKind,
) !plan_mod.LoweredMutationSource {
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    if (write_kind == .update_joined_source) return error.UnsupportedSqlShape;
    if (ast.source_tokens != null) return error.UnsupportedSqlShape;
    const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedUpdateSourceRanges(tokens, ast, end);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .params = params,
        .unique_resolver = options.unique_resolver,
        .default_context = options.default_context,
        .mutation_claim = row_claim,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
        .generated_assignment_items = &ast.assignment_items,
        .generated_dml_ast = &ast,
    };
    var lowered = try parser_context.ParserState.ContextAccessors.parseUpdateMutationSource(&parser_state);
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn deleteSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    write_kind: sql_statement_kind.SqlWriteStatementKind,
) !plan_mod.LoweredMutationSource {
    if (ast.kind != .delete) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    if (write_kind == .delete_joined_source) return error.UnsupportedSqlShape;
    if (ast.source_tokens != null) return error.UnsupportedSqlShape;
    const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedDeleteSourceRanges(tokens, ast, end);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .params = params,
        .unique_resolver = options.unique_resolver,
        .default_context = options.default_context,
        .mutation_claim = row_claim,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
    };
    var lowered = try parser_context.ParserState.ContextAccessors.parseDeleteMutationSource(&parser_state);
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn generatedDmlParserConsumedStatement(tokens: []const Token, end: usize, pos: usize) bool {
    if (pos == end) return true;
    return end < tokens.len and
        tokens[end].kind == .semicolon and
        pos == end + 1;
}

fn validateGeneratedUpdateSourceRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 3 >= end or !tokens[start].matchesKeywordTag(.update)) return error.UnsupportedSqlShape;
    const target_start = try generatedUpdateTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const assignments_range = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments_range.start == 0 or assignments_range.start >= assignments_range.end or assignments_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[assignments_range.start - 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, assignments_range, &ast.assignment_items);
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    _ = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, assignments_range.start - 1);
    try validateGeneratedDmlTailRanges(tokens, end, assignments_range.end, ast.where_tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);
    try validateGeneratedDmlMutationTailMetadata(tokens, end, assignments_range.end, ast);
}

fn validateGeneratedDeleteSourceRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 2 >= end or !tokens[start].matchesKeywordTag(.delete) or !tokens[start + 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    const target_start = try generatedDeleteTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDmlTargetAliasEnd(tokens, target_range, ast.target_alias_tokens, ast.target_alias_name_tokens, end);
    const tail_start = if (ast.where_tokens) |where_range| blk: {
        if (where_range.start == 0) return error.UnsupportedSqlShape;
        break :blk where_range.start - 1;
    } else if (ast.returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else end;
    const after_portion = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, tail_start);
    try validateGeneratedDmlTailRanges(tokens, end, after_portion, ast.where_tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);
    try validateGeneratedDmlMutationTailMetadata(tokens, end, after_portion, ast);
}

fn generatedDmlOptionalTemporalPortionEnd(tokens: []const Token, start: usize, stop: usize) !usize {
    if (start > stop or stop > tokens.len) return error.UnsupportedSqlShape;
    if (start == stop) return start;
    if (start + 6 >= stop) return error.UnsupportedSqlShape;
    if (!tokens[start].matchesKeywordTag(.@"for")) return error.UnsupportedSqlShape;
    if (!tokens[start + 1].matchesKeywordTag(.portion)) return error.UnsupportedSqlShape;
    if (!tokens[start + 2].matchesKeywordTag(.of)) return error.UnsupportedSqlShape;
    if (tokens[start + 3].kind != .identifier) return error.UnsupportedSqlShape;
    if (!tokens[start + 4].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;

    var depth: usize = 0;
    var to_index: ?usize = null;
    var cursor = start + 5;
    while (cursor < stop) : (cursor += 1) {
        switch (tokens[cursor].kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return error.UnsupportedSqlShape;
                depth -= 1;
            },
            else => {},
        }
        if (depth == 0 and tokens[cursor].matchesKeywordTag(.to)) {
            to_index = cursor;
            break;
        }
    }

    const to = to_index orelse return error.UnsupportedSqlShape;
    if (to == start + 5 or to + 1 >= stop) return error.UnsupportedSqlShape;
    return stop;
}

fn validateGeneratedDmlTailRanges(
    tokens: []const Token,
    end: usize,
    tail_start: usize,
    where_tokens: ?generated_parser.GeneratedSqlTokenRange,
    returning_tokens: ?generated_parser.GeneratedSqlTokenRange,
    returning_items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (tail_start > end) return error.UnsupportedSqlShape;
    const returning_keyword = if (returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0 or returning_range.start > returning_range.end or returning_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[returning_range.start - 1].matchesKeywordTag(.returning)) return error.UnsupportedSqlShape;
        if (returning_range.end != end) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else null;
    const actual_returning_keyword = parser.findTopLevelKeywordTagFromIndex(tokens[0..end], tail_start, .returning);
    if (actual_returning_keyword) |actual_returning| {
        if (returning_keyword == null or returning_keyword.? != actual_returning) return error.UnsupportedSqlShape;
    } else if (returning_keyword != null) return error.UnsupportedSqlShape;
    if (where_tokens) |where_range| {
        if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
        if (where_range.start - 1 < tail_start) return error.UnsupportedSqlShape;
        if (returning_keyword) |returning_start| {
            if (where_range.end != returning_start) return error.UnsupportedSqlShape;
        } else if (where_range.end != end) return error.UnsupportedSqlShape;
    } else if (returning_keyword) |returning_start| {
        if (tail_start != returning_start) return error.UnsupportedSqlShape;
    } else if (tail_start != end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlReturningItemsRange(tokens, returning_tokens, returning_items);
}

fn generatedDmlWhereExpressionRange(
    tokens: []const Token,
    end: usize,
    ast: generated_parser.GeneratedSqlDmlAst,
) !?generated_parser.GeneratedSqlTokenRange {
    const where_range = ast.where_tokens orelse {
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.where_expression);
        return null;
    };
    if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
    const tail_end = if (ast.returning_tokens) |returning_range| blk: {
        if (returning_range.start == 0 or returning_range.start > returning_range.end or returning_range.end > end) return error.UnsupportedSqlShape;
        break :blk returning_range.start - 1;
    } else end;
    if (tail_end < where_range.start or tail_end > where_range.end) return error.UnsupportedSqlShape;
    const order_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], where_range.start, .order);
    const limit_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], where_range.start, .limit);
    const offset_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], where_range.start, .offset);
    const fetch_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], where_range.start, .fetch);
    const row_lock_index = generatedDmlMutationRowLockStart(tokens, where_range.start, tail_end);
    const predicate_end = firstOptionalIndex(&[_]?usize{ order_index, limit_index, offset_index, fetch_index, row_lock_index }) orelse tail_end;
    if (predicate_end <= where_range.start) return error.UnsupportedSqlShape;
    return .{ .start = where_range.start, .end = predicate_end };
}

fn validateGeneratedDmlWhereExpressionMetadata(
    tokens: []const Token,
    end: usize,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    switch (ast.kind) {
        .update, .delete => {
            const expression_range = try generatedDmlWhereExpressionRange(tokens, end, ast);
            try generated_read_validate.validateGeneratedOptionalExpression(tokens, expression_range, ast.where_expression);
        },
        else => try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.where_expression),
    }
}

fn generatedDmlWhereExpressionForClause(
    tokens: []const Token,
    where_keyword_index: usize,
    where_body_start: usize,
    generated_dml_ast: ?*const generated_parser.GeneratedSqlDmlAst,
) !?*const generated_parser.GeneratedSqlExpressionAst {
    const ast = generated_dml_ast orelse return null;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const range = (try generatedDmlWhereExpressionRange(tokens, end, ast.*)) orelse return error.UnsupportedSqlShape;
    if (where_keyword_index + 1 != range.start or where_body_start != range.start) return error.UnsupportedSqlShape;
    return &ast.where_expression;
}

fn validateGeneratedDmlPaginationExpressionMetadata(
    tokens: []const Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
    expected_range: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (!generatedDmlTokenRangeEql(expression.tokens orelse return error.UnsupportedSqlShape, expected_range)) return error.UnsupportedSqlShape;
    try generated_read_validate.validateGeneratedOptionalExpression(tokens, expected_range, expression);
    switch (expression.kind) {
        .token_range => {},
        .unary_positive => {
            const operator_tokens = expression.operator_tokens orelse return error.UnsupportedSqlShape;
            if (operator_tokens.start != expected_range.start or operator_tokens.end != expected_range.start + 1) return error.UnsupportedSqlShape;
            if (operator_tokens.end > tokens.len or tokens[operator_tokens.start].kind != .plus) return error.UnsupportedSqlShape;
            const right_tokens = expression.right_tokens orelse return error.UnsupportedSqlShape;
            if (right_tokens.start != operator_tokens.end or right_tokens.end != expected_range.end) return error.UnsupportedSqlShape;
            const right_expression = expression.right_expression orelse return error.UnsupportedSqlShape;
            if (right_expression.kind != .token_range) return error.UnsupportedSqlShape;
            if (!generatedDmlTokenRangeEql(right_expression.tokens orelse return error.UnsupportedSqlShape, right_tokens)) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedDmlLimitAllRangeLayout(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range.end != range.start + 1 or range.end > tokens.len or !tokens[range.start].matchesKeywordTag(.all)) {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedDmlFetchRangeLayout(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    fetch_count_tokens: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range.start + 3 > range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start].matchesKeywordTag(.first) and !tokens[range.start].matchesKeywordTag(.next)) return error.UnsupportedSqlShape;
    if (!tokens[range.end - 1].matchesKeywordTag(.only)) return error.UnsupportedSqlShape;
    const row_index = range.end - 2;
    if (!tokens[row_index].matchesKeywordTag(.row) and !tokens[row_index].matchesKeywordTag(.rows)) return error.UnsupportedSqlShape;
    if (fetch_count_tokens) |count_tokens| {
        if (count_tokens.start != range.start + 1 or count_tokens.end != row_index) return error.UnsupportedSqlShape;
    } else if (row_index != range.start + 1) {
        return error.UnsupportedSqlShape;
    }
}

fn generatedDmlMutationRowLockModeStartsAt(tokens: []const Token, index: usize, end: usize) bool {
    if (index >= end) return false;
    if (tokens[index].matchesKeywordTag(.update) or tokens[index].matchesKeywordTag(.share)) return true;
    if (index + 2 < end and
        tokens[index].matchesKeywordTag(.no) and
        tokens[index + 1].matchesKeywordTag(.key) and
        tokens[index + 2].matchesKeywordTag(.update))
    {
        return true;
    }
    return index + 1 < end and
        tokens[index].matchesKeywordTag(.key) and
        tokens[index + 1].matchesKeywordTag(.share);
}

fn generatedDmlMutationRowLockStart(tokens: []const Token, start: usize, end: usize) ?usize {
    if (start >= end or end > tokens.len) return null;
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => {},
        }
        if (depth != 0 or !tokens[index].matchesKeywordTag(.@"for")) continue;
        if (generatedDmlMutationRowLockModeStartsAt(tokens, index + 1, end)) return index;
    }
    return null;
}

fn firstOptionalIndex(indexes: []const ?usize) ?usize {
    var first: ?usize = null;
    for (indexes) |maybe_index| {
        const index = maybe_index orelse continue;
        if (first == null or index < first.?) first = index;
    }
    return first;
}

fn validateGeneratedDmlMutationRowLockClauseLayout(
    tokens: []const Token,
    lock_tokens: generated_parser.GeneratedSqlTokenRange,
    mode: ?generated_parser.GeneratedSqlRowLockMode,
    wait_policy: ?generated_parser.GeneratedSqlRowLockWaitPolicy,
) !void {
    const generated_mode = mode orelse return error.UnsupportedSqlShape;
    const generated_wait_policy = wait_policy orelse return error.UnsupportedSqlShape;
    if (lock_tokens.start >= lock_tokens.end or lock_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[lock_tokens.start].matchesKeywordTag(.@"for")) return error.UnsupportedSqlShape;

    var cursor = lock_tokens.start + 1;
    if (cursor >= lock_tokens.end) return error.UnsupportedSqlShape;
    const parsed_mode: generated_parser.GeneratedSqlRowLockMode = if (tokens[cursor].matchesKeywordTag(.update)) blk: {
        cursor += 1;
        break :blk .update;
    } else if (tokens[cursor].matchesKeywordTag(.share)) blk: {
        cursor += 1;
        break :blk .share;
    } else if (cursor + 2 < lock_tokens.end and
        tokens[cursor].matchesKeywordTag(.no) and
        tokens[cursor + 1].matchesKeywordTag(.key) and
        tokens[cursor + 2].matchesKeywordTag(.update))
    blk: {
        cursor += 3;
        break :blk .no_key_update;
    } else if (cursor + 1 < lock_tokens.end and
        tokens[cursor].matchesKeywordTag(.key) and
        tokens[cursor + 1].matchesKeywordTag(.share))
    blk: {
        cursor += 2;
        break :blk .key_share;
    } else return error.UnsupportedSqlShape;
    if (parsed_mode != generated_mode) return error.UnsupportedSqlShape;

    if (cursor < lock_tokens.end and tokens[cursor].matchesKeywordTag(.of)) {
        cursor += 1;
        if (cursor >= lock_tokens.end) return error.UnsupportedSqlShape;
        var saw_target = false;
        var previous_was_comma = true;
        while (cursor < lock_tokens.end and
            !tokens[cursor].matchesKeywordTag(.nowait) and
            !tokens[cursor].matchesKeywordTag(.skip))
        {
            if (tokens[cursor].kind == .comma) {
                if (previous_was_comma) return error.UnsupportedSqlShape;
                previous_was_comma = true;
            } else {
                saw_target = true;
                previous_was_comma = false;
            }
            cursor += 1;
        }
        if (!saw_target or previous_was_comma) return error.UnsupportedSqlShape;
    }

    var parsed_wait_policy = generated_parser.GeneratedSqlRowLockWaitPolicy.wait;
    if (cursor < lock_tokens.end) {
        if (tokens[cursor].matchesKeywordTag(.nowait)) {
            parsed_wait_policy = .nowait;
            cursor += 1;
        } else if (cursor + 1 < lock_tokens.end and
            tokens[cursor].matchesKeywordTag(.skip) and
            tokens[cursor + 1].matchesKeywordTag(.locked))
        {
            parsed_wait_policy = .skip_locked;
            cursor += 2;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (cursor != lock_tokens.end) return error.UnsupportedSqlShape;
    if (parsed_wait_policy != generated_wait_policy) return error.UnsupportedSqlShape;
}

fn validateGeneratedDmlEmptyOrderMetadata(list: generated_parser.GeneratedSqlListAst) !void {
    if (list.count != 0 or
        list.items.len != 0 or
        list.expression_items.len != 0 or
        list.expressions.len != 0 or
        list.alias_items.len != 0 or
        list.alias_name_items.len != 0 or
        list.direction_items.len != 0 or
        list.directions.len != 0 or
        list.order_using_operator_items.len != 0 or
        list.nulls_order_items.len != 0 or
        list.nulls_orders.len != 0 or
        list.first_tokens != null or
        list.last_tokens != null)
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedDmlMutationTailMetadata(
    tokens: []const Token,
    end: usize,
    tail_start: usize,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    if (tail_start > end or end > tokens.len) return error.UnsupportedSqlShape;
    const returning_keyword = if (ast.returning_tokens) |returning_range| returning_range.start - 1 else end;
    const tail_end = returning_keyword;
    if (tail_end < tail_start or tail_end > end) return error.UnsupportedSqlShape;

    const order_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], tail_start, .order);
    const limit_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], tail_start, .limit);
    const offset_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], tail_start, .offset);
    const fetch_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..tail_end], tail_start, .fetch);
    const row_lock_index = generatedDmlMutationRowLockStart(tokens, tail_start, tail_end);

    if (order_index) |idx| {
        if (idx + 1 >= tail_end or !tokens[idx + 1].matchesKeywordTag(.by)) return error.UnsupportedSqlShape;
        const range = ast.mutation_order_tokens orelse return error.UnsupportedSqlShape;
        const expected_end = firstOptionalIndex(&[_]?usize{ limit_index, offset_index, fetch_index, row_lock_index }) orelse tail_end;
        if (range.start != idx + 2 or range.end != expected_end or range.start >= range.end) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOrderListForClause(tokens, range, ast.mutation_order_items);
    } else {
        if (ast.mutation_order_tokens != null) return error.UnsupportedSqlShape;
        try validateGeneratedDmlEmptyOrderMetadata(ast.mutation_order_items);
    }

    if (limit_index) |idx| {
        const range = ast.mutation_limit_tokens orelse return error.UnsupportedSqlShape;
        const expected_end = firstOptionalIndex(&[_]?usize{ offset_index, fetch_index, row_lock_index }) orelse tail_end;
        if (range.start != idx + 1 or range.end != expected_end or range.start >= range.end) return error.UnsupportedSqlShape;
        if (ast.mutation_limit_all) {
            try validateGeneratedDmlLimitAllRangeLayout(tokens, range);
            try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.mutation_limit_expression);
        } else {
            try validateGeneratedDmlPaginationExpressionMetadata(tokens, ast.mutation_limit_expression, range);
        }
    } else {
        if (ast.mutation_limit_tokens != null or ast.mutation_limit_all) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.mutation_limit_expression);
    }

    if (offset_index) |idx| {
        const range = ast.mutation_offset_tokens orelse return error.UnsupportedSqlShape;
        const expected_end = firstOptionalIndex(&[_]?usize{ fetch_index, row_lock_index }) orelse tail_end;
        if (range.start != idx + 1 or range.end != expected_end or range.start >= range.end) return error.UnsupportedSqlShape;
        const expression_range = ast.mutation_offset_expression.tokens orelse return error.UnsupportedSqlShape;
        if (expression_range.start != range.start or expression_range.end > range.end) return error.UnsupportedSqlShape;
        if (expression_range.end != range.end) {
            if (expression_range.end + 1 != range.end) return error.UnsupportedSqlShape;
            if (!tokens[expression_range.end].matchesKeywordTag(.row) and !tokens[expression_range.end].matchesKeywordTag(.rows)) return error.UnsupportedSqlShape;
        }
        try validateGeneratedDmlPaginationExpressionMetadata(tokens, ast.mutation_offset_expression, expression_range);
    } else {
        if (ast.mutation_offset_tokens != null) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.mutation_offset_expression);
    }

    if (fetch_index) |idx| {
        const range = ast.mutation_fetch_tokens orelse return error.UnsupportedSqlShape;
        const expected_end = row_lock_index orelse tail_end;
        if (range.start != idx + 1 or range.end != expected_end or range.start >= range.end) return error.UnsupportedSqlShape;
        try validateGeneratedDmlFetchRangeLayout(tokens, range, ast.mutation_fetch_count_tokens);
        if (ast.mutation_fetch_count_tokens) |count_range| {
            try validateGeneratedDmlPaginationExpressionMetadata(tokens, ast.mutation_fetch_count_expression, count_range);
        } else {
            try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.mutation_fetch_count_expression);
        }
    } else {
        if (ast.mutation_fetch_tokens != null or ast.mutation_fetch_count_tokens != null) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, ast.mutation_fetch_count_expression);
    }

    if (row_lock_index) |idx| {
        const range = ast.mutation_row_lock_tokens orelse return error.UnsupportedSqlShape;
        if (range.start != idx or range.end != tail_end) return error.UnsupportedSqlShape;
        try validateGeneratedDmlMutationRowLockClauseLayout(tokens, range, ast.mutation_row_lock_mode, ast.mutation_row_lock_wait_policy);
    } else if (ast.mutation_row_lock_tokens != null or ast.mutation_row_lock_mode != null or ast.mutation_row_lock_wait_policy != null) {
        return error.UnsupportedSqlShape;
    }
}

fn updateJoinedSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredJoinedMutationSource {
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const source_schema = options.joined_source_schema orelse schema;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
    const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
    if (row_claim.txn_id == null) return error.UnsupportedRowsQuery;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedUpdateJoinedRanges(tokens, ast, end);
    if (ast.source_tokens != null) {
        try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);
    }

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = source_schema,
        .params = params,
        .mutation_claim = row_claim,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
        .generated_assignment_items = &ast.assignment_items,
        .generated_dml_ast = &ast,
    };
    var lowered = blk: {
        if (!parser.peekKeywordTag(tokens, parser_state.pos, .with)) {
            break :blk parseJoinedMutationSourceAlloc(
                alloc,
                tokens,
                &parser_state.pos,
                parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
                parser_context.ParserState.ContextAccessors.updateJoinedMutationSourceParserHooks(&parser_state),
            );
        }

        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        var ctes = try plan_mod.parseCtesForPlanAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            &base_table_name,
            parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
        );
        errdefer plan_mod.freePlanCtes(alloc, ctes);

        parser_state.generated_returning_items = generatedDmlFinalStatementReturningItems(&ast);
        const lowered_with_ctes = try parser_context.ParserState.ContextAccessors.parseUpdateJoinedMutationSourceWithCtes(&parser_state, ctes, &base_table_name);
        plan_mod.freePlanCtes(alloc, ctes);
        ctes = &.{};
        break :blk lowered_with_ctes;
    } catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedRowsQuery,
        else => return err,
    };
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn deleteJoinedSourceFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredJoinedMutationSource {
    if (ast.kind != .delete) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const source_schema = options.joined_source_schema orelse schema;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
    const row_claim = options.row_claim orelse return error.UnsupportedRowsQuery;
    if (row_claim.txn_id == null) return error.UnsupportedRowsQuery;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedDeleteJoinedRanges(tokens, ast, end);
    if (ast.source_tokens != null) {
        try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);
    }

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = source_schema,
        .params = params,
        .mutation_claim = row_claim,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
    };
    var lowered = blk: {
        if (!parser.peekKeywordTag(tokens, parser_state.pos, .with)) {
            break :blk parseJoinedMutationSourceAlloc(
                alloc,
                tokens,
                &parser_state.pos,
                parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
                parser_context.ParserState.ContextAccessors.deleteJoinedMutationSourceParserHooks(&parser_state),
            );
        }

        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        var ctes = try plan_mod.parseCtesForPlanAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            &base_table_name,
            parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
        );
        errdefer plan_mod.freePlanCtes(alloc, ctes);

        parser_state.generated_returning_items = generatedDmlFinalStatementReturningItems(&ast);
        const lowered_with_ctes = try parser_context.ParserState.ContextAccessors.parseDeleteJoinedMutationSourceWithCtes(&parser_state, ctes, &base_table_name);
        plan_mod.freePlanCtes(alloc, ctes);
        ctes = &.{};
        break :blk lowered_with_ctes;
    } catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedRowsQuery,
        else => return err,
    };
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn validateGeneratedUpdateJoinedRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 7 >= end or !tokens[start].matchesKeywordTag(.update)) return error.UnsupportedSqlShape;
    const target_start = try generatedUpdateTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    _ = try generatedUpdateTargetAliasEnd(tokens, ast, target_range, end);
    const assignments_range = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    if (assignments_range.start == 0 or assignments_range.start >= assignments_range.end or assignments_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[assignments_range.start - 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, assignments_range, &ast.assignment_items);
    if (ast.source_tokens) |source_range| {
        if (source_range.start == 0 or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[source_range.start - 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
        if (source_range.start - 1 != assignments_range.end) return error.UnsupportedSqlShape;
        try validateGeneratedJoinedTailRanges(tokens, end, source_range.end, ast);
    } else {
        try validateGeneratedJoinedTailRanges(tokens, end, assignments_range.end, ast);
    }
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);
}

fn validateGeneratedDeleteJoinedRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 6 >= end or !tokens[start].matchesKeywordTag(.delete) or !tokens[start + 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    const target_start = try generatedDeleteTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDeleteTargetAliasEnd(tokens, ast, target_range, end);
    if (ast.source_tokens) |source_range| {
        if (source_range.start == 0 or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
        if (!tokens[source_range.start - 1].matchesKeywordTag(.using)) return error.UnsupportedSqlShape;
        if (source_range.start - 1 != target_alias_end) return error.UnsupportedSqlShape;
        try validateGeneratedJoinedTailRanges(tokens, end, source_range.end, ast);
    } else {
        const where_range = ast.where_tokens orelse return error.UnsupportedSqlShape;
        if (where_range.start == 0 or where_range.start - 1 != target_alias_end) return error.UnsupportedSqlShape;
        try validateGeneratedJoinedTailRanges(tokens, end, where_range.start - 1, ast);
    }
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);
}

fn validateGeneratedJoinedTailRanges(
    tokens: []const Token,
    end: usize,
    source_end: usize,
    ast: generated_parser.GeneratedSqlDmlAst,
) !void {
    const where_range = ast.where_tokens orelse return error.UnsupportedSqlShape;
    if (where_range.start == 0 or where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[where_range.start - 1].matchesKeywordTag(.where)) return error.UnsupportedSqlShape;
    if (where_range.start - 1 != source_end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlTailRanges(tokens, end, source_end, ast.where_tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedDmlMutationTailMetadata(tokens, end, source_end, ast);
}

fn mergeMutationFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredMergeMutationPlan {
    if (ast.kind != .merge) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const source_schema = options.joined_source_schema orelse schema;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidSqlCatalog;
    const tokens = parsed_sql.items();
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    try validateGeneratedMergeRanges(tokens, ast, end);
    try validateGeneratedDmlRelationSourceBody(parsed_sql, ast);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .joined_source_schema = source_schema,
        .params = params,
        .generated_dml_ast = &ast,
        .generated_returning_items = generatedDmlTopLevelReturningItems(&ast),
        .generated_merge_arms = &ast.merge_arms,
    };
    var lowered = if (!parser.peekKeywordTag(tokens, parser_state.pos, .with)) try parseMergeMutationBodyAlloc(alloc, tokens, &parser_state.pos, parser_context.ParserState.ContextAccessors.mergeMutationParserOptions(&parser_state), .{
        .ctes = &.{},
        .base_table_name = null,
    }) else blk: {
        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        var parsed_ctes = try parseMergeCtesForPlanAlloc(
            alloc,
            tokens,
            &parser_state.pos,
            &base_table_name,
            parser_context.ParserState.ContextAccessors.joinCteSelectParserHooks(&parser_state),
            parser_context.ParserState.ContextAccessors.mergeMutationParserOptions(&parser_state),
            ast.cte_prefix,
        );
        errdefer parsed_ctes.deinit(alloc);

        parser_state.generated_returning_items = generatedDmlFinalStatementReturningItems(&ast);
        var final = try parseMergeMutationBodyAlloc(alloc, tokens, &parser_state.pos, parser_context.ParserState.ContextAccessors.mergeMutationParserOptions(&parser_state), .{
            .ctes = parsed_ctes.read_ctes,
            .data_modifying_ctes = parsed_ctes.data_modifying_ctes,
            .base_table_name = &base_table_name,
        });
        errdefer final.deinit(alloc);
        _ = base_table_name orelse return error.UnsupportedSqlShape;
        final.ctes = parsed_ctes.read_ctes;
        final.data_modifying_ctes = parsed_ctes.data_modifying_ctes;
        parsed_ctes.read_ctes = &.{};
        parsed_ctes.data_modifying_ctes = &.{};
        break :blk final;
    };
    errdefer lowered.deinit(alloc);
    if (!generatedDmlParserConsumedStatement(tokens, end, parser_state.pos)) return error.UnsupportedSqlShape;
    lowered.sync_level = options.sync_level;
    return lowered;
}

fn validateGeneratedMergeRanges(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !void {
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 9 >= end or !tokens[start].matchesKeywordTag(.merge) or !tokens[start + 1].matchesKeywordTag(.into)) return error.UnsupportedSqlShape;
    const target_start = generatedDmlOptionalOnlyTargetStart(tokens, start + 2, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedMergeTargetAliasEnd(tokens, ast, target_range, end);
    const source_range = ast.source_tokens orelse return error.UnsupportedSqlShape;
    if (source_range.start == 0 or source_range.start >= source_range.end or source_range.end > end) return error.UnsupportedSqlShape;
    if (!tokens[source_range.start - 1].matchesKeywordTag(.using)) return error.UnsupportedSqlShape;
    if (source_range.start - 1 != target_alias_end) return error.UnsupportedSqlShape;
    const body_range = ast.where_tokens orelse return error.UnsupportedSqlShape;
    if (ast.where_expression.tokens != null) return error.UnsupportedSqlShape;
    if (body_range.start == 0 or body_range.start >= body_range.end or body_range.end != end) return error.UnsupportedSqlShape;
    if (!tokens[body_range.start - 1].matchesKeywordTag(.on)) return error.UnsupportedSqlShape;
    if (body_range.start - 1 != source_range.end) return error.UnsupportedSqlShape;
    if (parser.findTopLevelKeywordTagFromIndex(tokens[0..end], body_range.start, .returning)) |returning_keyword| {
        const returning_range = ast.returning_tokens orelse return error.UnsupportedSqlShape;
        if (returning_range.start != returning_keyword + 1 or returning_range.start > returning_range.end or returning_range.end != end) return error.UnsupportedSqlShape;
    } else if (ast.returning_tokens != null) {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedDmlReturningItemsRange(tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedMergeArmsMetadata(tokens, ast, body_range, end);
}

fn validateGeneratedMergeArmsMetadata(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    body_range: generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !void {
    if (ast.merge_arms.count == 0 or ast.merge_arms.items.len != ast.merge_arms.count) return error.UnsupportedSqlShape;
    if (ast.merge_arms.first_tokens == null or ast.merge_arms.last_tokens == null) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(ast.merge_arms.first_tokens.?, ast.merge_arms.items[0].tokens)) return error.UnsupportedSqlShape;
    if (!generatedDmlTokenRangeEql(ast.merge_arms.last_tokens.?, ast.merge_arms.items[ast.merge_arms.count - 1].tokens)) return error.UnsupportedSqlShape;
    const body_end = if (ast.returning_tokens) |returning_range| returning_range.start - 1 else end;
    const first_when = parser.findTopLevelKeywordTagFromIndex(tokens[0..body_end], body_range.start, .when) orelse return error.UnsupportedSqlShape;
    if (first_when <= body_range.start) return error.UnsupportedSqlShape;
    var expected_start = first_when;
    var matched_count: usize = 0;
    var not_matched_count: usize = 0;
    for (ast.merge_arms.items, 0..) |arm, index| {
        try validateGeneratedMergeArmMetadata(tokens, arm, expected_start, body_end);
        if (arm.matched) {
            matched_count += 1;
        } else {
            not_matched_count += 1;
        }
        expected_start = arm.tokens.end;
        if (index + 1 < ast.merge_arms.items.len and (expected_start >= body_end or !tokens[expected_start].matchesKeywordTag(.when))) return error.UnsupportedSqlShape;
    }
    if (expected_start != body_end) return error.UnsupportedSqlShape;
    if (matched_count != ast.merge_arms.matched_count or not_matched_count != ast.merge_arms.not_matched_count) return error.UnsupportedSqlShape;
}

fn validateGeneratedMergeArmMetadata(
    tokens: []const Token,
    arm: generated_parser.GeneratedSqlMergeArmAst,
    expected_start: usize,
    body_end: usize,
) !void {
    if (arm.tokens.start != expected_start or arm.tokens.end > body_end or arm.tokens.start + 3 >= arm.tokens.end) return error.UnsupportedSqlShape;
    if (!tokens[arm.tokens.start].matchesKeywordTag(.when)) return error.UnsupportedSqlShape;
    var cursor = arm.tokens.start + 1;
    if (arm.matched) {
        if (!tokens[cursor].matchesKeywordTag(.matched)) return error.UnsupportedSqlShape;
        cursor += 1;
    } else {
        if (cursor + 1 >= arm.tokens.end or !tokens[cursor].matchesKeywordTag(.not) or !tokens[cursor + 1].matchesKeywordTag(.matched)) return error.UnsupportedSqlShape;
        cursor += 2;
    }
    const then_index = parser.findTopLevelKeywordTagFromIndex(tokens[0..arm.tokens.end], cursor, .then) orelse return error.UnsupportedSqlShape;
    if (arm.predicate_tokens) |predicate| {
        if (predicate.start != cursor + 1 or predicate.end != then_index or predicate.start >= predicate.end) return error.UnsupportedSqlShape;
        if (!tokens[cursor].matchesKeywordTag(.@"and")) return error.UnsupportedSqlShape;
        if (!generatedDmlTokenRangeEql(arm.predicate_expression.tokens orelse return error.UnsupportedSqlShape, predicate)) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, predicate, arm.predicate_expression);
    } else {
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, null, arm.predicate_expression);
        if (cursor != then_index) return error.UnsupportedSqlShape;
    }
    if (arm.action_tokens.start != then_index + 1 or arm.action_tokens.start >= arm.action_tokens.end or arm.action_tokens.end != arm.tokens.end) return error.UnsupportedSqlShape;
    switch (arm.action_kind) {
        .update => {
            if (!arm.matched or !tokens[arm.action_tokens.start].matchesKeywordTag(.update) or arm.action_tokens.start + 2 >= arm.action_tokens.end) return error.UnsupportedSqlShape;
            if (!tokens[arm.action_tokens.start + 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
            const assignments = arm.assignments_tokens orelse return error.UnsupportedSqlShape;
            if (assignments.start != arm.action_tokens.start + 2 or assignments.start >= assignments.end or assignments.end != arm.action_tokens.end) return error.UnsupportedSqlShape;
            try validateGeneratedDmlListItemsRange(tokens, assignments, &arm.assignment_items);
            if (arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
        .delete => {
            if (!arm.matched or !tokens[arm.action_tokens.start].matchesKeywordTag(.delete) or arm.action_tokens.end != arm.action_tokens.start + 1) return error.UnsupportedSqlShape;
            if (arm.assignments_tokens != null or arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
        .do_nothing => {
            if (!tokens[arm.action_tokens.start].matchesKeywordTag(.do) or arm.action_tokens.start + 2 != arm.action_tokens.end or !tokens[arm.action_tokens.start + 1].matchesKeywordTag(.nothing)) return error.UnsupportedSqlShape;
            if (arm.assignments_tokens != null or arm.insert_columns_tokens != null or arm.insert_values_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            try validateGeneratedDmlEmptyList(&arm.insert_value_items);
        },
        .insert => {
            if (arm.matched or !tokens[arm.action_tokens.start].matchesKeywordTag(.insert) or arm.assignments_tokens != null) return error.UnsupportedSqlShape;
            try validateGeneratedDmlEmptyList(&arm.assignment_items);
            var values_start = arm.action_tokens.start + 1;
            if (arm.insert_columns_tokens) |columns| {
                if (columns.start != values_start or columns.end > arm.action_tokens.end or tokens[columns.start].kind != .lparen) return error.UnsupportedSqlShape;
                const close = parser.findMatchingRParenIndex(tokens, columns.start) orelse return error.UnsupportedSqlShape;
                if (close >= arm.action_tokens.end or columns.end != close + 1) return error.UnsupportedSqlShape;
                try validateGeneratedDmlListItemsRange(tokens, .{ .start = columns.start + 1, .end = columns.end - 1 }, &arm.insert_column_items);
                values_start = columns.end;
            } else {
                try validateGeneratedDmlEmptyList(&arm.insert_column_items);
            }
            const values = arm.insert_values_tokens orelse return error.UnsupportedSqlShape;
            if (values.start != values_start + 1 or values.start >= values.end or values.end != arm.action_tokens.end or !tokens[values_start].matchesKeywordTag(.values)) return error.UnsupportedSqlShape;
            if (tokens[values.start].kind != .lparen or tokens[values.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
            try validateGeneratedDmlListItemsRange(tokens, .{ .start = values.start + 1, .end = values.end - 1 }, &arm.insert_value_items);
        },
    }
}

fn generatedDmlTopLevelAssignmentEqToken(
    tokens: []const Token,
    assignment_item: generated_parser.GeneratedSqlTokenRange,
) ?usize {
    var paren_depth: usize = 0;
    var index = assignment_item.start;
    while (index < assignment_item.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => paren_depth += 1,
            .rparen => {
                if (paren_depth == 0) return null;
                paren_depth -= 1;
            },
            .eq => if (paren_depth == 0) return index,
            else => {},
        }
    }
    return null;
}

fn validateGeneratedDmlAssignmentExpressionMetadata(
    tokens: []const Token,
    assignment_item: generated_parser.GeneratedSqlTokenRange,
    expression: generated_parser.GeneratedSqlExpressionAst,
) !bool {
    if (!generatedDmlTokenRangeEql(expression.tokens orelse return error.UnsupportedSqlShape, assignment_item)) return error.UnsupportedSqlShape;
    try generated_read_validate.validateGeneratedOptionalExpression(tokens, assignment_item, expression);
    if (expression.kind != .comparison) {
        const operator_index = generatedDmlTopLevelAssignmentEqToken(tokens, assignment_item) orelse return error.UnsupportedSqlShape;
        if (operator_index == assignment_item.start or operator_index + 1 >= assignment_item.end) return error.UnsupportedSqlShape;
        return false;
    }
    const operator_tokens = expression.operator_tokens orelse return error.UnsupportedSqlShape;
    if (operator_tokens.start >= tokens.len or
        operator_tokens.end != operator_tokens.start + 1 or
        tokens[operator_tokens.start].kind != .eq)
    {
        return error.UnsupportedSqlShape;
    }
    const left_tokens = expression.left_tokens orelse return error.UnsupportedSqlShape;
    const right_tokens = expression.right_tokens orelse return error.UnsupportedSqlShape;
    if (left_tokens.start != assignment_item.start or
        left_tokens.end != operator_tokens.start or
        right_tokens.start != operator_tokens.end or
        right_tokens.end != assignment_item.end)
    {
        return error.UnsupportedSqlShape;
    }
    if (expression.right_expression) |right_expression| {
        if (!generatedDmlTokenRangeEql(right_expression.tokens orelse return error.UnsupportedSqlShape, right_tokens)) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, right_tokens, right_expression.*);
    }
    return true;
}

fn validateGeneratedDmlAssignmentRhsMetadata(
    tokens: []const Token,
    rhs_start: usize,
    rhs_end: usize,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    const expression = generated_expression_ast orelse return;
    const rhs_tokens: generated_parser.GeneratedSqlTokenRange = .{ .start = rhs_start, .end = rhs_end };
    if (expression.kind != .comparison) {
        if (!generatedDmlTokenRangeEql(expression.tokens orelse return error.UnsupportedSqlShape, rhs_tokens)) return error.UnsupportedSqlShape;
        try generated_read_validate.validateGeneratedOptionalExpression(tokens, rhs_tokens, expression.*);
        return;
    }
    const right_tokens = expression.right_tokens orelse return error.UnsupportedSqlShape;
    const right_expression = expression.right_expression orelse return error.UnsupportedSqlShape;
    if (right_tokens.start != rhs_start or right_tokens.end != rhs_end) {
        if (try generated_read_validate.validateGeneratedOptionalExpressionForExactRange(tokens, rhs_tokens, right_expression)) return;
        return error.UnsupportedSqlShape;
    }
    if (!generatedDmlTokenRangeEql(right_expression.tokens orelse return error.UnsupportedSqlShape, right_tokens)) return error.UnsupportedSqlShape;
    try generated_read_validate.validateGeneratedOptionalExpression(tokens, right_tokens, right_expression.*);
}

fn updatePointFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredMutation {
    if (ast.kind != .update) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    if (ast.source_tokens != null) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 5 >= end or !tokens[start].matchesKeywordTag(.update)) return error.UnsupportedSqlShape;
    const target_start = try generatedUpdateTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedUpdateTargetAliasEnd(tokens, ast, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    var table_transferred = false;
    errdefer if (!table_transferred) plan_mod.freeTableAlias(alloc, target_table);
    const table_name = target_table.name;

    const assignments_range = ast.assignments_tokens orelse return error.UnsupportedSqlShape;
    const where_range = ast.where_tokens orelse return error.UnsupportedSqlShape;
    if (assignments_range.start <= target_range.end or assignments_range.end > end) return error.UnsupportedSqlShape;
    if (assignments_range.start == 0 or !tokens[assignments_range.start - 1].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    _ = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, assignments_range.start - 1);
    if (where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    if (where_range.start == 0 or where_range.start - 1 != assignments_range.end) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, assignments_range, &ast.assignment_items);
    try validateGeneratedDmlTailRanges(tokens, end, assignments_range.end, ast.where_tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .params = params,
        .unique_resolver = options.unique_resolver,
        .default_context = options.default_context,
    };
    const parser_options = parser_context.ParserState.ContextAccessors.updateParserOptions(&parser_state);

    var patch = std.ArrayListUnmanaged(FieldJsonValue).empty;
    errdefer {
        freeFieldJsonValues(alloc, patch.items);
        patch.deinit(alloc);
    }
    var patch_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
    errdefer {
        freeFieldExpressionValues(alloc, patch_expr.items);
        patch_expr.deinit(alloc);
    }
    var increment = std.ArrayListUnmanaged(FieldJsonValue).empty;
    errdefer {
        freeFieldJsonValues(alloc, increment.items);
        increment.deinit(alloc);
    }
    var increment_expr = std.ArrayListUnmanaged(FieldExpressionValue).empty;
    errdefer {
        freeFieldExpressionValues(alloc, increment_expr.items);
        increment_expr.deinit(alloc);
    }
    var json_set = std.ArrayListUnmanaged(JsonSetValue).empty;
    errdefer {
        freeJsonSetValues(alloc, json_set.items);
        json_set.deinit(alloc);
    }
    var array_update = std.ArrayListUnmanaged(ArrayTransformValue).empty;
    errdefer {
        freeArrayTransformValues(alloc, array_update.items);
        array_update.deinit(alloc);
    }

    var rewrite_identity = false;
    const assignment_hooks: ConflictUpdateSetAssignmentParserOptions = .{
        .value = parser_options.assignment_value_hooks,
        .primary_key_assignment = .{ .mark_rewrite = &rewrite_identity },
    };
    if (ast.assignment_items.count == 0 or
        ast.assignment_items.items.len != ast.assignment_items.count or
        ast.assignment_items.expressions.len != ast.assignment_items.count)
    {
        return error.UnsupportedSqlShape;
    }
    for (ast.assignment_items.items, 0..) |assignment_item, assignment_index| {
        const assignment_tokens = tokens[0..assignment_item.end];
        parser_state.pos = assignment_item.start;
        const use_generated_assignment_expression = try validateGeneratedDmlAssignmentExpressionMetadata(tokens, assignment_item, ast.assignment_items.expressions[assignment_index]);
        var generated_assignment_hooks = assignment_hooks;
        generated_assignment_hooks.value.expression_options.assignment_options.generated_expression_ast =
            if (use_generated_assignment_expression) &ast.assignment_items.expressions[assignment_index] else null;
        try parseConflictUpdateSetAssignmentAlloc(
            alloc,
            assignment_tokens,
            &parser_state.pos,
            schema,
            params,
            parser_options.conflict_existing_qualifiers,
            &.{},
            &.{},
            &patch,
            &patch_expr,
            &increment,
            &increment_expr,
            &json_set,
            &array_update,
            generated_assignment_hooks,
        );
        if (parser_state.pos != assignment_item.end) return error.UnsupportedSqlShape;
    }
    if (patch.items.len == 0 and patch_expr.items.len == 0 and increment.items.len == 0 and increment_expr.items.len == 0 and json_set.items.len == 0 and array_update.items.len == 0) return error.UnsupportedSqlShape;
    try validateSqlUpdateTargetPaths(schema, patch.items, patch_expr.items, increment.items, increment_expr.items, json_set.items, array_update.items);

    const target_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    const where_tokens = tokens[0..where_range.end];
    var where_pos = where_range.start;
    const where_json = try parsePointWhereJsonAlloc(alloc, where_tokens, &where_pos, params, schema, &target_qualifiers, parser_options.realtime_ns, &ast.where_expression);
    defer alloc.free(where_json);
    if (where_pos != where_range.end) return error.UnsupportedSqlShape;

    var returning: plan_mod.ReturningProjection = .{};
    errdefer returning.deinit(alloc);
    if (ast.returning_tokens) |returning_range| {
        parser_state.pos = returning_range.start;
        const returning_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        returning = try generatedReturningProjectionAlloc(alloc, tokens, returning_range, schema, &returning_qualifiers, &parser_state.pos, &ast.returning_items, parser_options.returning_hooks);
    }
    const returning_expression_count = returning.expressions.len;
    const returning_all = returning.returnsAll();
    const explicit_expected_version = if (updateWillLookupExistingRow(schema, returning))
        null
    else
        try expectedVersionForWhereAlloc(alloc, table_name, where_json, schema, options.unique_resolver orelse return error.UnsupportedRowsSelector);

    const body_json = try updateBodyJsonAlloc(alloc, where_json, patch.items, patch_expr.items, increment.items, increment_expr.items, json_set.items, array_update.items, returning, explicit_expected_version, rewrite_identity);
    defer alloc.free(body_json);
    var batch = try parseRowsBatchRequestWithWriteOptionsAlloc(alloc, table_name, body_json, schema, options.unique_resolver orelse return error.UnsupportedRowsSelector, options.default_context);
    errdefer batch.deinit(alloc);
    batch.req.sync_level = options.sync_level;

    freeFieldJsonValues(alloc, patch.items);
    patch.deinit(alloc);
    freeFieldExpressionValues(alloc, patch_expr.items);
    patch_expr.deinit(alloc);
    freeFieldJsonValues(alloc, increment.items);
    increment.deinit(alloc);
    freeFieldExpressionValues(alloc, increment_expr.items);
    increment_expr.deinit(alloc);
    freeJsonSetValues(alloc, json_set.items);
    json_set.deinit(alloc);
    freeArrayTransformValues(alloc, array_update.items);
    array_update.deinit(alloc);

    const owned_table_name = target_table.name;
    alloc.free(target_table.alias);
    table_transferred = true;
    const owned_returning = returning;
    returning = .{};
    return .{
        .table_name = owned_table_name,
        .batch = batch,
        .sync_level = options.sync_level,
        .returning = owned_returning,
        .returning_expression_count = returning_expression_count,
        .returning_all = returning_all,
    };
}

fn deletePointFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
) !plan_mod.LoweredMutation {
    if (ast.kind != .delete) return error.UnsupportedSqlShape;
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    if (ast.source_tokens != null) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 4 >= end or !tokens[start].matchesKeywordTag(.delete) or !tokens[start + 1].matchesKeywordTag(.from)) return error.UnsupportedSqlShape;
    const target_start = try generatedDeleteTargetTableStart(tokens, start, end);
    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, target_start, end);
    const target_alias_end = try generatedDeleteTargetAliasEnd(tokens, ast, target_range, end);
    const target_table = try tableAliasFromGeneratedDmlTargetAlloc(alloc, tokens, target_range, target_alias_end, ast.target_alias_name_tokens);
    var table_transferred = false;
    errdefer if (!table_transferred) plan_mod.freeTableAlias(alloc, target_table);
    const table_name = target_table.name;

    const where_range = ast.where_tokens orelse return error.UnsupportedSqlShape;
    if (where_range.start >= where_range.end or where_range.end > end) return error.UnsupportedSqlShape;
    const tail_start = if (where_range.start == 0) return error.UnsupportedSqlShape else where_range.start - 1;
    const after_portion = try generatedDmlOptionalTemporalPortionEnd(tokens, target_alias_end, tail_start);
    try validateGeneratedDmlTailRanges(tokens, end, after_portion, ast.where_tokens, ast.returning_tokens, &ast.returning_items);
    try validateGeneratedDmlWhereExpressionMetadata(tokens, end, ast);

    const parser_context = @import("parser_context.zig");
    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .params = params,
        .unique_resolver = options.unique_resolver,
        .default_context = options.default_context,
    };
    const parser_options = parser_context.ParserState.ContextAccessors.deleteParserOptions(&parser_state);

    const target_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
    const where_tokens = tokens[0..where_range.end];
    var where_pos = where_range.start;
    const where_json = try parsePointWhereJsonAlloc(alloc, where_tokens, &where_pos, params, schema, &target_qualifiers, parser_options.realtime_ns, &ast.where_expression);
    defer alloc.free(where_json);
    if (where_pos != where_range.end) return error.UnsupportedSqlShape;

    var returning: plan_mod.ReturningProjection = .{};
    errdefer returning.deinit(alloc);
    if (ast.returning_tokens) |returning_range| {
        parser_state.pos = returning_range.start;
        const returning_qualifiers = [_][]const u8{ target_table.name, target_table.alias };
        returning = try generatedReturningProjectionAlloc(alloc, tokens, returning_range, schema, &returning_qualifiers, &parser_state.pos, &ast.returning_items, parser_options.returning_hooks);
    }
    const returning_expression_count = returning.expressions.len;
    const returning_all = returning.returnsAll();
    const explicit_expected_version = if (returning.hasProjection())
        null
    else
        try expectedVersionForWhereAlloc(alloc, table_name, where_json, schema, options.unique_resolver orelse return error.UnsupportedRowsSelector);

    const body_json = try deleteBodyJsonAlloc(alloc, where_json, returning, explicit_expected_version);
    defer alloc.free(body_json);
    var batch = try parseRowsBatchRequestWithWriteOptionsAlloc(alloc, table_name, body_json, schema, options.unique_resolver orelse return error.UnsupportedRowsSelector, options.default_context);
    errdefer batch.deinit(alloc);
    batch.req.sync_level = options.sync_level;

    const owned_table_name = target_table.name;
    alloc.free(target_table.alias);
    table_transferred = true;
    const owned_returning = returning;
    returning = .{};
    return .{
        .table_name = owned_table_name,
        .batch = batch,
        .sync_level = options.sync_level,
        .returning = owned_returning,
        .returning_expression_count = returning_expression_count,
        .returning_all = returning_all,
    };
}

fn generatedReturningProjectionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    schema: runtime_schema.TableSchema,
    returning_qualifiers: []const []const u8,
    pos: *usize,
    generated_returning_items: *const generated_parser.GeneratedSqlListAst,
    returning_hooks: expr_projection.ReturningProjectionParserOptions,
) !plan_mod.ReturningProjection {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    const scoped_tokens = tokens[0..range.end];
    pos.* = range.start;
    var generated_returning_hooks = returning_hooks;
    generated_returning_hooks.generated_returning_items = generated_returning_items;
    var returning = try expr_projection.parseReturningProjectionAlloc(alloc, scoped_tokens, pos, schema, returning_qualifiers, generated_returning_hooks);
    errdefer returning.deinit(alloc);
    if (pos.* != range.end) return error.UnsupportedSqlShape;
    return returning;
}

fn generatedInsertColumnsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
    schema: runtime_schema.TableSchema,
    column_specs: *std.ArrayListUnmanaged(InsertColumnSpec),
) ![]const []const u8 {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .lparen or tokens[range.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, .{ .start = range.start + 1, .end = range.end - 1 }, items);
    if (items.count == 0 or items.items.len != items.count) return error.UnsupportedSqlShape;
    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (columns.items) |column| alloc.free(column);
        columns.deinit(alloc);
    }
    var expected_start = range.start + 1;
    for (items.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > range.end - 1) return error.UnsupportedSqlShape;
        if (item.start + 1 != item.end) return error.UnsupportedSqlShape;
        const column = try generatedDmlIdentifierAtAlloc(alloc, tokens, item.start);
        var column_transferred = false;
        errdefer if (!column_transferred) alloc.free(column);
        if (binder.relationalColumnForField(schema, column, null) != null) {
            try columns.append(alloc, column);
            column_transferred = true;
            try column_specs.append(alloc, .{ .column = column });
        } else if (binder.relationalPeriodForDdl(schema.periods, column)) |period| {
            const start_column = binder.relationalColumnForField(schema, period.start_column, null) orelse return error.InvalidSqlCatalog;
            const end_column = binder.relationalColumnForField(schema, period.end_column, null) orelse return error.InvalidSqlCatalog;
            if (start_column.field_type != end_column.field_type or !binder.relationalPeriodColumnType(start_column.field_type)) return error.InvalidSqlCatalog;
            const start_name = try alloc.dupe(u8, start_column.name);
            var start_transferred = false;
            errdefer if (!start_transferred) alloc.free(start_name);
            const end_name = try alloc.dupe(u8, end_column.name);
            var end_transferred = false;
            errdefer if (!end_transferred) alloc.free(end_name);
            try columns.append(alloc, start_name);
            start_transferred = true;
            try columns.append(alloc, end_name);
            end_transferred = true;
            try column_specs.append(alloc, .{ .period = period });
            alloc.free(column);
            column_transferred = true;
        } else return error.InvalidSqlCatalog;
        if (item_index + 1 == items.items.len) {
            expected_start = item.end;
        } else {
            if (item.end >= range.end - 1 or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        }
    }
    if (expected_start != range.end - 1) return error.UnsupportedSqlShape;
    if (columns.items.len == 0 or column_specs.items.len == 0) return error.UnsupportedSqlShape;
    return try columns.toOwnedSlice(alloc);
}

fn generatedInsertValueRowsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    value_rows: *const generated_parser.GeneratedSqlListAst,
    columns: []const []const u8,
    column_specs: []const InsertColumnSpec,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
) ![][]const []const u8 {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (columns.len == 0 or column_specs.len == 0) return error.UnsupportedSqlShape;
    try validateGeneratedDmlListItemsRange(tokens, range, value_rows);
    if (value_rows.count == 0 or value_rows.items.len != value_rows.count) return error.UnsupportedSqlShape;
    var rows = std.ArrayListUnmanaged([]const []const u8).empty;
    errdefer {
        freeInsertValueRows(alloc, rows.items);
        rows.deinit(alloc);
    }
    var expected_start = range.start;
    for (value_rows.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > range.end) return error.UnsupportedSqlShape;
        if (tokens[item.start].kind != .lparen or tokens[item.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
        var index = item.start + 1;
        var row = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (row.items) |value| alloc.free(value);
            row.deinit(alloc);
        }
        for (column_specs, 0..) |spec, spec_i| {
            switch (spec) {
                .column => |column_name| {
                    const column = binder.relationalColumnForField(schema, column_name, null) orelse return error.InvalidSqlCatalog;
                    const value_json = try sql_value.parseSqlColumnValueAlloc(alloc, tokens, &index, params, column, sql_value.currentRealtimeNs());
                    var value_transferred = false;
                    errdefer if (!value_transferred) alloc.free(value_json);
                    try row.append(alloc, value_json);
                    value_transferred = true;
                },
                .period => |period| {
                    const pair = try expr_predicate.parseSqlPeriodRangeValuePairAlloc(
                        alloc,
                        tokens,
                        &index,
                        params,
                        schema,
                        period,
                        sql_value.currentRealtimeNs(),
                    );
                    var start_transferred = false;
                    errdefer if (!start_transferred) alloc.free(pair.start_json);
                    var end_transferred = false;
                    errdefer if (!end_transferred) alloc.free(pair.end_json);
                    try row.append(alloc, pair.start_json);
                    start_transferred = true;
                    try row.append(alloc, pair.end_json);
                    end_transferred = true;
                },
            }
            if (spec_i + 1 < column_specs.len) {
                if (index >= item.end - 1 or tokens[index].kind != .comma) return error.UnsupportedSqlShape;
                index += 1;
            }
        }
        if (row.items.len != columns.len) return error.UnsupportedSqlShape;
        if (index != item.end - 1) return error.UnsupportedSqlShape;
        index += 1;
        if (index != item.end) return error.UnsupportedSqlShape;
        const owned_row = try row.toOwnedSlice(alloc);
        var row_transferred = false;
        errdefer if (!row_transferred) {
            for (owned_row) |value| alloc.free(value);
            alloc.free(owned_row);
        };
        row = .empty;
        try rows.append(alloc, owned_row);
        row_transferred = true;
        if (item_index + 1 == value_rows.items.len) {
            expected_start = item.end;
        } else {
            if (item.end >= range.end or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        }
    }
    if (expected_start != range.end) return error.UnsupportedSqlShape;
    if (rows.items.len == 0) return error.UnsupportedSqlShape;
    return try rows.toOwnedSlice(alloc);
}

fn generatedDmlIdentifierAtAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    index: usize,
) ![]const u8 {
    if (index >= tokens.len or tokens[index].kind != .identifier) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, tokens[index].text);
}

fn truncateSyntaxFromGeneratedDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
) !grammar.TruncateMutationSourceSyntax {
    if (ast.kind != .truncate) return error.UnsupportedSqlShape;
    const end = generatedDmlStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const start = try generatedDmlCommandStart(tokens, ast, end);
    if (start + 1 >= end or !tokens[start].matchesKeywordTag(.truncate)) return error.UnsupportedSqlShape;
    var index: usize = start + 1;
    if (index < end and tokens[index].matchesKeywordTag(.table)) index += 1;
    if (index < end and tokens[index].matchesKeywordTag(.only)) index += 1;

    const target_range = try requireGeneratedDmlTokenRangeAt(ast.target_table_tokens, index, end);
    const table_name = try generatedDmlTableReferenceIdentifierAlloc(alloc, tokens, target_range);
    var table_transferred = false;
    errdefer if (!table_transferred) alloc.free(table_name);
    index = target_range.end;

    var additional_table_names = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (additional_table_names.items) |name| alloc.free(name);
        additional_table_names.deinit(alloc);
    }
    if (ast.additional_target_tokens) |additional_range| {
        if (additional_range.start != index or additional_range.end > end) return error.UnsupportedSqlShape;
        try validateGeneratedDmlCommaPrefixedIdentifierListItemsRange(tokens, additional_range, &ast.additional_target_items);
        var expected_comma = additional_range.start;
        for (ast.additional_target_items.items) |item| {
            if (expected_comma >= additional_range.end or tokens[expected_comma].kind != .comma) return error.UnsupportedSqlShape;
            if (item.start != expected_comma + 1 or item.end != item.start + 1 or item.end > additional_range.end) return error.UnsupportedSqlShape;
            try additional_table_names.append(alloc, try generatedDmlTableReferenceIdentifierAlloc(alloc, tokens, item));
            expected_comma = item.end;
        }
        if (expected_comma != additional_range.end) return error.UnsupportedSqlShape;
        index = additional_range.end;
    } else {
        try validateGeneratedDmlEmptyList(&ast.additional_target_items);
    }

    var restart_identity = false;
    if (index < end and tokens[index].matchesKeywordTag(.restart)) {
        if (index + 1 >= end or !tokens[index + 1].matchesKeywordTag(.identity) or !ast.restart_identity) return error.UnsupportedSqlShape;
        restart_identity = true;
        index += 2;
    } else if (index < end and tokens[index].matchesKeywordTag(.@"continue")) {
        if (index + 1 >= end or !tokens[index + 1].matchesKeywordTag(.identity) or ast.restart_identity) return error.UnsupportedSqlShape;
        index += 2;
    } else if (index < end and tokens[index].matchesKeywordTag(.identity)) {
        return error.UnsupportedSqlShape;
    } else if (ast.restart_identity) {
        return error.UnsupportedSqlShape;
    }

    var cascade = false;
    if (index < end and tokens[index].matchesKeywordTag(.cascade)) {
        if (!ast.cascade) return error.UnsupportedSqlShape;
        cascade = true;
        index += 1;
        if (index < end and tokens[index].matchesKeywordTag(.restrict)) return error.UnsupportedSqlShape;
    } else if (index < end and tokens[index].matchesKeywordTag(.restrict)) {
        if (ast.cascade) return error.UnsupportedSqlShape;
        index += 1;
    } else if (ast.cascade) {
        return error.UnsupportedSqlShape;
    }
    if (index != end) return error.UnsupportedSqlShape;

    const owned_additional_table_names = try additional_table_names.toOwnedSlice(alloc);
    table_transferred = true;
    return .{
        .table_name = table_name,
        .additional_table_names = owned_additional_table_names,
        .restart_identity = restart_identity,
        .cascade = cascade,
    };
}

fn generatedDmlStatementEnd(tokens: []const Token, statement_span: @import("token.zig").SourceSpan) ?usize {
    if (tokens.len == 0) return null;
    var end = tokens.len;
    while (end > 0 and tokens[end - 1].kind == .semicolon) end -= 1;
    if (end == 0 or tokens[0].source_start != statement_span.start or tokens[end - 1].source_end != statement_span.end) return null;
    return end;
}

fn generatedDmlStatementSpanEnd(tokens: []const Token, statement_span: @import("token.zig").SourceSpan) ?usize {
    if (tokens.len == 0 or statement_span.start >= statement_span.end) return null;
    for (tokens, 0..) |token, index| {
        if (token.source_start < statement_span.start) continue;
        if (token.source_end == statement_span.end) return index + 1;
        if (token.source_start >= statement_span.end) return null;
    }
    return null;
}

fn generatedDmlStatementSpanStart(tokens: []const Token, statement_span: @import("token.zig").SourceSpan) ?usize {
    if (tokens.len == 0 or statement_span.start >= statement_span.end) return null;
    for (tokens, 0..) |token, index| {
        if (token.source_start == statement_span.start) return index;
        if (token.source_start > statement_span.start) return null;
    }
    return null;
}

fn generatedDmlCommandStart(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    end: usize,
) !usize {
    if (ast.cte_tokens) |cte_tokens| {
        if (end > tokens.len or cte_tokens.start != 1 or cte_tokens.end <= cte_tokens.start or cte_tokens.end >= end) return error.UnsupportedSqlShape;
        if (!tokens[0].matchesKeywordTag(.with)) return error.UnsupportedSqlShape;
        if (ast.cte_recursive) {
            if (tokens.len < 2 or !tokens[1].matchesKeywordTag(.recursive)) return error.UnsupportedSqlShape;
        } else if (tokens.len > 1 and tokens[1].matchesKeywordTag(.recursive)) {
            return error.UnsupportedSqlShape;
        }
        try validateGeneratedDmlCommandSpan(tokens, ast, cte_tokens.end);
        return cte_tokens.end;
    }
    if (ast.cte_recursive) return error.UnsupportedSqlShape;
    if (tokens.len > 0 and tokens[0].matchesKeywordTag(.with)) return error.UnsupportedSqlShape;
    try validateGeneratedDmlCommandSpan(tokens, ast, 0);
    return 0;
}

fn validateGeneratedDmlCommandSpan(
    tokens: []const Token,
    ast: generated_parser.GeneratedSqlDmlAst,
    command_start: usize,
) !void {
    if (command_start >= tokens.len) return error.UnsupportedSqlShape;
    const command = tokens[command_start];
    if (ast.command_span.start != command.source_start or ast.command_span.end != command.source_end) return error.UnsupportedSqlShape;
}

fn requireGeneratedDmlTokenRangeAt(
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    start: usize,
    end: usize,
) !generated_parser.GeneratedSqlTokenRange {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start != start or range.end != start + 1 or range.end > end) return error.UnsupportedSqlShape;
    return range;
}

fn generatedDmlTableReferenceIdentifierAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .identifier) return error.UnsupportedSqlShape;
    return try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[range.start].text);
}

fn generatedDmlAstMatchesWriteKind(
    generated_kind: generated_parser.GeneratedSqlDmlKind,
    write_kind: sql_statement_kind.SqlWriteStatementKind,
) bool {
    return switch (generated_kind) {
        .insert_values => write_kind == .insert,
        .insert_select => write_kind == .insert_source,
        .update => switch (write_kind) {
            .update, .update_source, .update_joined_source => true,
            else => false,
        },
        .delete => switch (write_kind) {
            .delete, .delete_source, .delete_joined_source => true,
            else => false,
        },
        .truncate => write_kind == .truncate,
        .merge => write_kind == .merge,
    };
}

fn lowerWritePlanWithCatalogForDmlTestAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    catalog: table_catalog.CatalogSource,
) !plan_mod.LoweredWritePlan {
    return try lowerWritePlanWithCatalogSessionForDmlTestAlloc(alloc, sql, schema, params, options, catalog, catalog_resources.SqlCatalogSession.default());
}

fn lowerWritePlanWithCatalogSessionForDmlTestAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    catalog: table_catalog.CatalogSource,
    session: catalog_resources.SqlCatalogSession,
) !plan_mod.LoweredWritePlan {
    var parsed_sql = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed_sql.deinit(alloc);
    return try lowerWritePlanWithCatalogSessionParsedSqlForDmlTestAlloc(alloc, &parsed_sql, schema, params, options, catalog, session);
}

fn lowerWritePlanWithCatalogParsedSqlForDmlTestAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    catalog: table_catalog.CatalogSource,
) !plan_mod.LoweredWritePlan {
    return try lowerWritePlanWithCatalogSessionParsedSqlForDmlTestAlloc(alloc, parsed_sql, schema, params, options, catalog, catalog_resources.SqlCatalogSession.default());
}

fn lowerWritePlanWithCatalogSessionParsedSqlForDmlTestAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    schema: runtime_schema.TableSchema,
    params: []const sql_value.SqlValue,
    options: plan_mod.LowerWritePlanOptions,
    catalog: table_catalog.CatalogSource,
    session: catalog_resources.SqlCatalogSession,
) !plan_mod.LoweredWritePlan {
    if (schema.storage_mode == .document) {
        return try lowerDocumentWritePlanParsedSqlAlloc(alloc, parsed_sql, schema, params, options);
    }
    var context = lowering_context.CatalogWritePlanLoweringContext{
        .alloc = alloc,
        .schema = schema,
        .params = params,
        .callbacks = .{
            .lower_with_options = lowerWritePlanParsedSqlWithFunctionBindingsForDmlTestAlloc,
        },
    };
    return try context.lowerParsedWithSession(parsed_sql, options, catalog, session);
}

