test "sql adapter lower dml validates generated child read payloads" {
    const alloc = std.testing.allocator;
    var insert_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM usage_records WHERE status = 'ready'",
    );
    defer insert_source.deinit(alloc);
    switch (insert_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source, dml),
        else => return error.TestUnexpectedResult,
    }
    var insert_source_stale_read_ast = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM usage_records WHERE status = 'ready'",
    );
    defer insert_source_stale_read_ast.deinit(alloc);
    if (insert_source_stale_read_ast.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    const source_read = if (dml.source_read) |*source_read| source_read else return error.TestUnexpectedResult;
                    const read_ast = source_read.read_ast orelse return error.TestUnexpectedResult;
                    read_ast.projection_tokens = read_ast.source_tokens;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (insert_source_stale_read_ast.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source_stale_read_ast, dml)),
        else => return error.TestUnexpectedResult,
    }
    var insert_source_alias = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT s.id FROM incoming_usage AS s WHERE s.status = 'ready'",
    );
    defer insert_source_alias.deinit(alloc);
    switch (insert_source_alias.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source_alias, dml),
        else => return error.TestUnexpectedResult,
    }
    if (insert_source_alias.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.source_read.?.source_table_tokens == null or
                        dml.source_read.?.source_alias_tokens == null or
                        dml.source_read.?.source_alias_name_tokens == null)
                    {
                        return error.TestUnexpectedResult;
                    }
                    dml.source_read.?.source_alias_tokens = null;
                    dml.source_read.?.source_alias_name_tokens = null;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (insert_source_alias.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source_alias, dml)),
        else => return error.TestUnexpectedResult,
    }

    var insert_source_function = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM antfly.full_text_search(index => 'docs_body_fts', query => 'refund', limit => 10) AS hits",
    );
    defer insert_source_function.deinit(alloc);
    switch (insert_source_function.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source_function, dml),
        else => return error.TestUnexpectedResult,
    }
    if (insert_source_function.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.source_read.?.source_antfly_function_items.len != 1) return error.TestUnexpectedResult;
                    if ((dml.source_read.?.read_ast orelse return error.TestUnexpectedResult).source_antfly_function_items.len != 1) return error.TestUnexpectedResult;
                    dml.source_read.?.source_antfly_function_items[0].kind = .semantic_search;
                },
