        try std.testing.expectEqual(document_write.DocumentWriteOperation.projection_write, documentWriteOperationForParsedSql(&parsed_sql));
        var lowered = try lowerWritePlanWithCatalogForDmlTestAlloc(
            alloc,
            case.sql,
            schema,
            &.{},
            .{},
            catalog.iface(),
        );
        defer lowered.deinit(alloc);
        switch (lowered) {
            .document_write => |projection_write| {
                try std.testing.expectEqual(document_write.DocumentWriteOperation.projection_write, projection_write.operation);
                try std.testing.expectEqual(case.expected_keys.len, projection_write.batch.req.transforms.len);
                try std.testing.expectEqual(@as(u32, @intCast(case.expected_keys.len)), projection_write.batch.transformed);
                try std.testing.expectEqual(case.expected_predicates, projection_write.batch.req.predicates.len);
                for (case.expected_keys, projection_write.batch.req.transforms) |expected_key, transform| {
                    try std.testing.expectEqualStrings(expected_key, transform.key);
                    try std.testing.expectEqual(@as(usize, 1), transform.operations.len);
                    try std.testing.expectEqual(db_mod.types.TransformOpType.set, transform.operations[0].op);
                    try std.testing.expectEqualStrings("title", transform.operations[0].path);
                    try std.testing.expectEqualStrings("\"Launch\"", transform.operations[0].value_json.?);
                }
                for (projection_write.batch.req.predicates, 0..) |predicate, i| {
                    try std.testing.expectEqualStrings(case.expected_keys[i], predicate.key);
                    try std.testing.expectEqual(@as(u64, 42), predicate.expected_version);
                }
            },
            else => return error.TestUnexpectedResult,
        }
    }

    const cases = [_]struct {
        sql: []const u8,
        operation: document_write.DocumentWriteOperation,
    }{
        .{ .sql = "UPDATE docs SET _doc = '{}' WHERE _id = 'doc:a'", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":\"not-array\"}') WHERE _id = 'doc:a'", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":[{\"op\":\"set\",\"path\":\"title\",\"value\":\"Launch\"}]}') WHERE title = 'Launch'", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":[{\"op\":\"set\",\"path\":\"title\",\"value\":\"Launch\"}]}') WHERE _id IN ('doc:a', 'doc:b') AND _version = 42", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":[{\"op\":\"set\",\"path\":\"title\",\"value\":\"Launch\"}]}') WHERE _version = 42 AND _id IN ('doc:a', 'doc:b')", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":[{\"op\":\"set\",\"path\":\"title\",\"value\":\"Launch\"}]}') WHERE _version = 42 AND title = 'Launch'", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, '{\"ops\":[{\"op\":\"set\",\"path\":\"title\",\"value\":\"Launch\"}]}') WHERE _id = 'doc:a' AND title = 'Launch'", .operation = .document_patch },
        .{ .sql = "UPDATE docs SET title_lc = 'launch' WHERE _id = 'doc:a'", .operation = .projection_write },
        .{ .sql = "UPDATE docs SET _id = 'doc:b' WHERE _id = 'doc:a'", .operation = .projection_write },
        .{ .sql = "UPDATE docs SET _version = 43 WHERE _id = 'doc:a'", .operation = .projection_write },
        .{ .sql = "UPDATE docs SET title = 'Launch' WHERE _id = 'doc:a' RETURNING _id, title", .operation = .projection_write },
        .{ .sql = "UPDATE docs SET title = 'Joined' FROM docs AS source WHERE docs._id = source._id", .operation = .projection_write },
        .{ .sql = "DELETE FROM docs USING docs AS source WHERE docs._id = source._id", .operation = .non_identity_delete },
        .{ .sql = "TRUNCATE docs", .operation = .truncate_table },
        .{ .sql = "MERGE INTO docs USING docs AS source ON docs._id = source._id WHEN MATCHED THEN DELETE", .operation = .merge },
    };
    for (cases) |case| {
        var parsed_sql = try tokenized.ParsedSql.initAlloc(alloc, case.sql);
        defer parsed_sql.deinit(alloc);
        try std.testing.expectEqual(case.operation, documentWriteOperationForParsedSql(&parsed_sql));
        if (lowerWritePlanWithCatalogForDmlTestAlloc(
            alloc,
            case.sql,
            schema,
            &.{},
            .{},
            catalog.iface(),
        )) |_| {
            return error.TestExpectedError;
        } else |err| switch (err) {
            error.DocumentSqlWriteUnsupported,
            error.InvalidSqlCatalog,
            error.UnsupportedSqlShape,
            => {},
            else => return err,
        }
    }

    const payload_parse_error_sql = "UPDATE docs SET _doc = antfly.json_patch(_doc, $1) WHERE _id = 'doc:a'";
    try std.testing.expectError(error.MissingSqlParameter, lowerWritePlanWithCatalogForDmlTestAlloc(
        alloc,
        payload_parse_error_sql,
        schema,
        &.{},
        .{},
        catalog.iface(),
    ));

    const preflight_cases = [_]struct {
        preflight: db_mod.document_write.DocumentWritePreflight,
        rejection: db_mod.document_write.DocumentWritePreflightRejection,
    }{
        .{
            .preflight = .{
                .surface = .sql_adapter,
                .operation = .full_document_insert,
                .authorization_allowed = false,
                .row_filter_allowed = false,
                .audit_satisfied = false,
                .conflict_free = false,
                .match_requirement_satisfied = false,
                .operation_admitted = true,
            },
            .rejection = .authorization,
        },
        .{
            .preflight = .{
                .surface = .sql_adapter,
                .operation = .full_document_insert,
                .row_filter_allowed = false,
                .audit_satisfied = false,
                .conflict_free = false,
                .match_requirement_satisfied = false,
                .operation_admitted = true,
            },
            .rejection = .row_filter,
        },
        .{
            .preflight = .{
                .surface = .sql_adapter,
                .operation = .full_document_insert,
                .audit_satisfied = false,
                .conflict_free = false,
                .match_requirement_satisfied = false,
                .operation_admitted = true,
            },
            .rejection = .audit_required,
        },
        .{
            .preflight = .{
                .surface = .sql_adapter,
                .operation = .full_document_insert,
                .conflict_free = false,
                .match_requirement_satisfied = false,
                .operation_admitted = true,
            },
            .rejection = .conflict,
        },
        .{
            .preflight = .{
                .surface = .sql_adapter,
                .operation = .full_document_insert,
                .match_requirement_satisfied = false,
                .operation_admitted = true,
            },
            .rejection = .no_match,
        },
    };
    const preflight_sql_cases = [_]struct {
        sql: []const u8,
        operation: db_mod.document_write.DocumentWriteOperation,
    }{
        .{
            .sql = "INSERT INTO docs (_id, title) VALUES ('doc:preflight-projection', 'Launch')",
            .operation = .full_document_insert,
        },
        .{
            .sql = "INSERT INTO docs (title) VALUES ('Generated Preflight')",
            .operation = .generated_id_insert,
        },
        .{
            .sql = payload_parse_error_sql,
            .operation = .document_patch,
        },
        .{
            .sql = "UPDATE docs SET title = 'Projection Preflight' WHERE _id = 'doc:preflight-projection'",
            .operation = .projection_write,
        },
    };
    for (preflight_cases) |case| {
        try std.testing.expectEqual(case.rejection, db_mod.document_write.documentWritePreflightRejection(case.preflight).?);
        for (preflight_sql_cases) |sql_case| {
            var preflight = case.preflight;
            preflight.operation = sql_case.operation;
            try std.testing.expectEqual(case.rejection, db_mod.document_write.documentWritePreflightRejection(preflight).?);
            try std.testing.expectError(error.DocumentSqlWriteUnsupported, lowerWritePlanWithCatalogForDmlTestAlloc(
                alloc,
                sql_case.sql,
                schema,
                &.{},
                .{ .document_preflight = preflight },
                catalog.iface(),
            ));
        }
    }
}

test "sql adapter lower dml detects dotted path conflicts" {
    try std.testing.expect(sqlDottedPathsConflict("metadata", "metadata.status"));
    try std.testing.expect(sqlDottedPathsConflict("metadata.status", "metadata"));
    try std.testing.expect(sqlDottedPathsConflict("metadata.status", "metadata.status"));
    try std.testing.expect(!sqlDottedPathsConflict("metadata.status", "metadata_status"));
    try std.testing.expect(!sqlDottedPathsConflict("metadata.status", "metadata.state"));
}

test "sql adapter lower dml detects json set path conflicts" {
    const status_path = [_][]const u8{"status"};
    const nested_status_path = [_][]const u8{ "profile", "status" };
    const profile_path = [_][]const u8{"profile"};
    const settings_path = [_][]const u8{"settings"};

    try std.testing.expect(sqlJsonSetPathsConflict("metadata", &status_path, "metadata", &status_path));
    try std.testing.expect(sqlJsonSetPathsConflict("metadata", &profile_path, "metadata", &nested_status_path));
    try std.testing.expect(!sqlJsonSetPathsConflict("metadata", &status_path, "metadata", &settings_path));
    try std.testing.expect(sqlJsonSetPathsConflict("metadata", &status_path, "metadata.status", &settings_path));
    try std.testing.expect(sqlDottedPathConflictsJsonSetPath("metadata.profile.status", "metadata", &profile_path));
    try std.testing.expect(sqlDottedPathConflictsJsonSetPath("metadata.profile.status", "metadata", &settings_path));
    try std.testing.expect(!sqlDottedPathConflictsJsonSetPath("profile.status", "metadata", &settings_path));

    const alloc = std.testing.allocator;
    const typed_path = try jsonSetTypedTransformPathAlloc(alloc, "metadata", &nested_status_path);
    defer alloc.free(typed_path);
    try std.testing.expectEqualStrings("metadata.profile.status", typed_path);
    try std.testing.expectError(error.UnsupportedSqlShape, jsonSetTypedTransformPathAlloc(alloc, "metadata", &.{""}));
    try std.testing.expectError(error.UnsupportedSqlShape, jsonSetTypedTransformPathAlloc(alloc, "metadata", &.{"bad.segment"}));
    try std.testing.expectEqualStrings("append", arrayTransformOpToken(.push));
    try std.testing.expectEqualStrings("remove", arrayTransformOpToken(.pull));
    try std.testing.expectEqualStrings("add_to_set", arrayTransformOpToken(.add_to_set));
    try std.testing.expectEqualStrings("update", conflictActionName(.update));
    try std.testing.expectEqualStrings("nothing", conflictActionName(.nothing));
    const conjunction_tokens = [_]Token{
        .{ .kind = .lparen, .text = "(" },
        .{ .kind = .identifier, .text = "active" },
        .{ .kind = .identifier, .text = "and" },
        .{ .kind = .identifier, .text = "verified" },
        .{ .kind = .rparen, .text = ")" },
    };
    try std.testing.expect(conflictParenthesizedConjunctionCanStart(&conjunction_tokens, 0));
    try std.testing.expect(!conflictParenthesizedDisjunctionCanStart(&conjunction_tokens, 0));
    const keyword_tokens = [_]Token{
        .{ .kind = .identifier, .text = "CURRENT_DATE", .keyword = .current_date },
        .{ .kind = .identifier, .text = "array_append" },
    };
    try std.testing.expect(keywordAt(keyword_tokens[0..], 0, "current_date"));
    try std.testing.expect(keywordAt(keyword_tokens[0..], 1, "array_append"));
    try std.testing.expect(!keywordAt(keyword_tokens[0..], 0, "current_timestamp"));
    const existing_qualifiers = [_][]const u8{ "usage_records", "public.usage_records" };
    try std.testing.expect(conflictQualifierMatches(alloc, &existing_qualifiers, "usage_records"));
    try std.testing.expect(conflictQualifierMatches(alloc, &existing_qualifiers, "public.usage_records"));
    try std.testing.expectEqualStrings("status", conflictExistingFieldName(alloc, &existing_qualifiers, "public.usage_records.status").?);
    const normalized_existing_qualifiers = [_][]const u8{ "usage_records", "usage_records" };
    try std.testing.expectEqualStrings("quantity", conflictExistingFieldName(alloc, &normalized_existing_qualifiers, "public.usage_records.quantity").?);
    try std.testing.expect(conflictExistingFieldName(alloc, &existing_qualifiers, "other.status") == null);
    const default_column: runtime_schema.RelationalColumn = .{
        .name = "status",
        .path = "status",
        .field_type = .keyword,
        .default_value = .{ .kind = .literal, .value_json = "\"pending\"" },
    };
    try std.testing.expect(conflictProposedColumnAvailable(&.{}, default_column, "status"));
    const required_column: runtime_schema.RelationalColumn = .{
        .name = "status",
        .path = "status",
        .field_type = .keyword,
    };
    try std.testing.expect(!conflictProposedColumnAvailable(&.{}, required_column, "status"));
    try std.testing.expect(conflictProposedColumnAvailable(&.{"status"}, required_column, "status"));
    const source_assignments = [_]JoinedMutationSourceAssignment{
        .{ .field = "status", .source_qualifier = "src", .source_field = "status" },
        .{ .field = "amount", .source_qualifier = "src", .source_field = "amount" },
    };
    try validateJoinedMutationSourceAssignments(&source_assignments, "src");
    try std.testing.expectError(error.UnsupportedSqlShape, validateJoinedMutationSourceAssignments(&source_assignments, "other"));

    const assignments = [_]db_mod.types.RelationalRowsExpressionAssignment{
        .{ .field = "status", .expression = .{ .kind = .field, .field = "source_status" } },
        .{ .field = "status_lower", .expression = .{ .kind = .lower, .operands = &.{.{ .kind = .field, .field = "source_status" }} } },
    };
    try std.testing.expectEqual(@as(usize, 1), expressionAssignmentComputedCount(&assignments));

    const transforms = [_]db_mod.types.DocumentTransform{
        .{ .key = "doc-1", .operations = &.{.{ .op = .set, .path = "status", .value_json = "\"open\"" }} },
        .{ .key = "doc-2", .operations = &.{
            .{ .op = .inc, .path = "count", .value_json = "1" },
            .{ .op = .push, .path = "events", .value_json = "\"opened\"" },
        } },
    };
    try std.testing.expectEqual(@as(usize, 3), transformOperationCount(&transforms));

    const positive = try normalizedIncrementJsonAlloc(alloc, "3.25", false);
    defer alloc.free(positive);
    try std.testing.expectEqualStrings("3.25", positive);
    const negative = try normalizedIncrementJsonAlloc(alloc, "3.25", true);
    defer alloc.free(negative);
    try std.testing.expectEqualStrings("-3.25", negative);
    try std.testing.expectError(error.UnsupportedSqlShape, normalizedIncrementJsonAlloc(alloc, "\"3\"", false));
}

test "sql adapter lower dml lowers on conflict date_bin expression update" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"updated_at_ns":{"type":"datetime"}},"required":["id","email"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"usage_records_email_key","columns":["email"]}]}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"email\":\"a@example.test\",\"updated_at_ns\":1}", .version = 8 };

    var lowered = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, updated_at_ns) VALUES ('u2', 'a@example.test', 3700000000000) ON CONFLICT (email) DO UPDATE SET updated_at_ns = date_bin(INTERVAL '1 hour', excluded.updated_at_ns, 0) RETURNING updated_at_ns",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms[0].operations.len);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, lowered.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("updated_at_ns", lowered.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("3600000000000", lowered.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"updated_at_ns\":3600000000000}", lowered.batch.returning_rows[0]);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, updated_at_ns) VALUES ('u2', 'a@example.test', 3700000000000) ON CONFLICT (email) DO UPDATE SET updated_at_ns = date_bin(INTERVAL '1 month', excluded.updated_at_ns, 0) RETURNING updated_at_ns",
        schema,
        &.{},
        resolver_ctx.resolver(),
    ));
}

test "sql adapter lower dml lowers on conflict array transforms from excluded scalar" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"tag":{"type":"keyword"},"status":{"type":"keyword"},"tags":{"type":"array","items":{"type":"keyword"}},"amount":{"type":"numeric"}},"required":["id","email"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"usage_records_email_key","columns":["email"]}]}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"email\":\"a@example.test\",\"tag\":\"old\",\"tags\":[\"old\"],\"amount\":4}", .version = 8 };

    var lowered = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, tag) VALUES ('u2', 'a@example.test', 'new') ON CONFLICT (email) DO UPDATE SET tags = array_append(tags, excluded.tag) RETURNING tags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms[0].operations.len);
    try std.testing.expectEqual(db_mod.types.TransformOpType.push, lowered.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("tags", lowered.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"new\"", lowered.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"tags\":[\"old\",\"new\"]}", lowered.batch.returning_rows[0]);

    var coalesced = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, tag) VALUES ('u2', 'a@example.test', null) ON CONFLICT (email) DO UPDATE SET tags = array_append(tags, coalesce(excluded.tag, 'fallback')) RETURNING tags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer coalesced.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), coalesced.batch.transformed);
    try std.testing.expectEqual(db_mod.types.TransformOpType.push, coalesced.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("tags", coalesced.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"fallback\"", coalesced.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"tags\":[\"old\",\"fallback\"]}", coalesced.batch.returning_rows[0]);

    var position = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, tag) VALUES ('u2', 'a@example.test', 'old') ON CONFLICT (email) DO UPDATE SET amount = array_position(tags, excluded.tag) RETURNING amount",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer position.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), position.batch.transformed);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, position.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("amount", position.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("1", position.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"amount\":1}", position.batch.returning_rows[0]);

    var joined_text = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email) VALUES ('u2', 'a@example.test') ON CONFLICT (email) DO UPDATE SET status = array_to_string(tags, ',') RETURNING status",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer joined_text.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), joined_text.batch.transformed);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, joined_text.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("status", joined_text.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"old\"", joined_text.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"status\":\"old\"}", joined_text.batch.returning_rows[0]);

    var expression_patch = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, tag) VALUES ('u2', 'a@example.test', 'new') ON CONFLICT (email) DO UPDATE SET tags = array_append((tags), excluded.tag) RETURNING tags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer expression_patch.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), expression_patch.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), expression_patch.batch.transforms[0].operations.len);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, expression_patch.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("tags", expression_patch.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("[\"old\",\"new\"]", expression_patch.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"tags\":[\"old\",\"new\"]}", expression_patch.batch.returning_rows[0]);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, tag) VALUES ('u2', 'a@example.test', null) ON CONFLICT (email) DO UPDATE SET tags = array_append(tags, excluded.tag) RETURNING tags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, amount) VALUES ('u2', 'a@example.test', 3) ON CONFLICT (email) DO UPDATE SET tags = array_append(tags, excluded.amount) RETURNING tags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, amount) VALUES ('u2', 'a@example.test', 3) ON CONFLICT (email) DO UPDATE SET amount = array_position(tags, excluded.amount) RETURNING amount",
        schema,
        &.{},
        resolver_ctx.resolver(),
    ));
}

test "sql adapter lower dml lowers on conflict jsonb concat update" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"status":{"type":"keyword"},"metadata":{"type":"json"},"flag_count":{"type":"numeric"}},"required":["id","email"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"usage_records_email_key","columns":["email"]}]}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"email\":\"a@example.test\",\"metadata\":{\"source\":\"old\"}}", .version = 8 };

    var lowered = try lowerInsertWithResolverForTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, email, metadata) VALUES ('u2', 'a@example.test', '{\"source\":\"insert\"}'::jsonb) ON CONFLICT (email) DO UPDATE SET metadata = metadata || '{\"source\":\"conflict\",\"flags\":[\"seen\"]}'::jsonb RETURNING metadata.source, metadata.flags",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 2), lowered.batch.transforms[0].operations.len);
    try std.testing.expectEqualStrings("metadata.source", lowered.batch.transforms[0].operations[0].path);
