test "sql adapter lower dml lowers now and current_timestamp update values" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"updated_at_ns":{"type":"numeric"},"name":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"name\":\"old\",\"updated_at_ns\":1}", .version = 22 };

    var lowered = try lowerUpdateForTestAlloc(
        alloc,
        "UPDATE users SET updated_at_ns = NOW() WHERE id = $1 RETURNING updated_at_ns",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms[0].operations.len);
    try std.testing.expectEqualStrings("updated_at_ns", lowered.batch.transforms[0].operations[0].path);
    const planned_now = try std.fmt.parseInt(u64, lowered.batch.transforms[0].operations[0].value_json.?, 10);
    try std.testing.expect(planned_now > 0);
    var returned = try std.json.parseFromSlice(std.json.Value, alloc, lowered.batch.returning_rows[0], .{});
    defer returned.deinit();
    switch (returned.value.object.get("updated_at_ns").?) {
        .integer => |value| try std.testing.expectEqual(@as(i64, @intCast(planned_now)), value),
        else => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(@as(u64, 22), lowered.batch.predicates[0].expected_version);

    var current_resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"name\":\"old\",\"updated_at_ns\":1}", .version = 23 };
    var lowered_current = try lowerUpdateForTestAlloc(
        alloc,
        "UPDATE users SET updated_at_ns = CURRENT_TIMESTAMP(6) WHERE id = $1 RETURNING updated_at_ns",
        schema,
        &.{.{ .string = "u1" }},
        current_resolver_ctx.resolver(),
    );
    defer lowered_current.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered_current.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered_current.batch.transforms[0].operations.len);
    try std.testing.expectEqualStrings("updated_at_ns", lowered_current.batch.transforms[0].operations[0].path);
    const planned_current = try std.fmt.parseInt(u64, lowered_current.batch.transforms[0].operations[0].value_json.?, 10);
    try std.testing.expect(planned_current > 0);
    var returned_current = try std.json.parseFromSlice(std.json.Value, alloc, lowered_current.batch.returning_rows[0], .{});
    defer returned_current.deinit();
    switch (returned_current.value.object.get("updated_at_ns").?) {
        .integer => |value| try std.testing.expectEqual(@as(i64, @intCast(planned_current)), value),
        else => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(@as(u64, 23), lowered_current.batch.predicates[0].expected_version);

    var current_date_resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"name\":\"old\",\"updated_at_ns\":1}", .version = 24 };
    var lowered_current_date = try lowerUpdateForTestAlloc(
        alloc,
        "UPDATE users SET updated_at_ns = CURRENT_DATE WHERE id = $1 RETURNING updated_at_ns",
        schema,
        &.{.{ .string = "u1" }},
        current_date_resolver_ctx.resolver(),
    );
    defer lowered_current_date.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), lowered_current_date.batch.transformed);
    const planned_current_date = try std.fmt.parseInt(u64, lowered_current_date.batch.transforms[0].operations[0].value_json.?, 10);
    try std.testing.expect(planned_current_date > 0);
    try std.testing.expectEqual(@as(u64, 0), planned_current_date % @as(u64, 86_400 * std.time.ns_per_s));
    try std.testing.expectEqual(@as(u64, 24), lowered_current_date.batch.predicates[0].expected_version);
}

